import { startOfMonth, endOfMonth, eachDayOfInterval } from 'date-fns';
import { useState, memo, useMemo } from 'react';

import { useCalendarEvents } from '../api/domains/calendar';
import type { CalendarEvent } from '../types';
import logger from '../utils/logger';

import EventEditorModal from './EventEditorModal';
import { LoadingSkeleton } from './performance';
interface Props {
  month: Date;
  events?: CalendarEvent[];
}

const CalendarViewComponent = memo(({ month, events }: Props): React.ReactElement => {
  const [editorOpen, setEditorOpen] = useState(false);

  // Memoize expensive date calculations
  const dateRange = useMemo(() => {
    const from = startOfMonth(month).toISOString();
    const to = endOfMonth(month).toISOString();
    return { from, to };
  }, [month]);

  const fetch = useCalendarEvents(dateRange.from, dateRange.to);

  // Memoize event array processing
  const evts = useMemo(() => {
    if (events !== null && events !== undefined) {
      return events;
    }
    if (fetch.data !== null && fetch.data !== undefined) {
      return fetch.data;
    }
    return [];
  }, [events, fetch.data]);

  // Log any errors for debugging
  if (fetch.error !== null && fetch.error !== undefined) {
    logger.error('Error loading calendar events:', fetch.error);
  }

  // Memoize expensive day calculations and event grouping
  const { days, grouped } = useMemo(() => {
    const days = eachDayOfInterval({ 
      start: new Date(dateRange.from), 
      end: new Date(dateRange.to) 
    });

    const grouped: Record<string, CalendarEvent[]> = {};
    // Safely process events
    evts.forEach((e) => {
      if (e.start !== null && e.start !== undefined && e.start !== '') {
        const d = e.start.split('T')[0];
        if (grouped[d] === undefined) {
          grouped[d] = [];
        }
        grouped[d].push(e);
      }
    });

    return { days, grouped };
  }, [dateRange.from, dateRange.to, evts]);

  if (fetch.isLoading) {
    return (
      <div className="border rounded p-2">
        <LoadingSkeleton columns={7} rows={6} variant="table" />
      </div>
    );
  }

  return (
    <div className="border rounded p-2">
      {(events === null || events === undefined) && (
        <button
          className="mb-2 px-2 py-1 bg-blue-500 text-white rounded"
          onClick={() => {
            setEditorOpen(true);
          }}
        >
          + Add Event
        </button>
      )}
      <div className="grid grid-cols-7 gap-1 text-sm">
        {days.map((d, index) => (
          <div key={d.toISOString()} className="border p-1 min-h-16">
            <div className="font-bold text-xs">{d.getDate()}</div>
            {(grouped[d.toISOString().split('T')[0]] ?? []).map((ev) => (
              <div key={ev.id} className="text-xs bg-gray-200 rounded mt-1 px-1" title={ev.title}>
                {ev.title}
              </div>
            ))}
          </div>
        ))}
      </div>
      {(events === null || events === undefined) && editorOpen && (
        <EventEditorModal
          onClose={() => {
            setEditorOpen(false);
          }}
        />
      )}
    </div>
  );
});

CalendarViewComponent.displayName = 'CalendarViewComponent';

export default CalendarViewComponent;

import { AlertTriangle, Target } from 'lucide-react';
import React, { useMemo } from 'react';
import {
  PieChart,
  Pie,
  Cell,
  ResponsiveContainer,
  Tooltip,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Legend,
} from 'recharts';

import { Badge } from '@/components/ui/Badge';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Progress } from '@/components/ui/Progress';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';

import {
  useCurriculumExpectations,
  useUnitPlans,
  useETFOLessonPlans,
} from '../hooks/useETFOPlanning';

interface StrandCoverage {
  strand: string;
  total: number;
  covered: number;
  percentage: number;
}

interface GradeCoverage {
  grade: number;
  subjects: {
    subject: string;
    total: number;
    covered: number;
    percentage: number;
  }[];
}

export default function CurriculumExpectationCoverage(): React.ReactElement {
  // Fetch data
  const { data: expectations = [] } = useCurriculumExpectations();
  const { data: unitPlans = [] } = useUnitPlans();
  const { data: lessonPlans = [] } = useETFOLessonPlans();

  // Calculate coverage metrics
  const coverageMetrics = useMemo(() => {
    // Get all expectation IDs that are covered in units or lessons
    const coveredExpectationIds = new Set<string>();

    // From unit plans
    unitPlans.forEach((unit) => {
      unit.expectations?.forEach((exp) => {
        coveredExpectationIds.add(exp.expectation.id);
      });
    });

    // From lesson plans
    lessonPlans.forEach((lesson) => {
      lesson.expectations?.forEach((exp) => {
        coveredExpectationIds.add(exp.expectation.id);
      });
    });

    // Group expectations by subject and strand
    const bySubject: Record<string, typeof expectations> = {};
    const byStrand: Record<string, typeof expectations> = {};
    const byGrade: Record<number, Record<string, typeof expectations>> = {};

    expectations.forEach((exp) => {
      // By subject
      if (bySubject[exp.subject] === undefined) {
        bySubject[exp.subject] = [];
      }
      bySubject[exp.subject].push(exp);

      // By strand
      const strand = exp.strand !== null && exp.strand !== undefined && exp.strand !== '' ? exp.strand : 'Other';
      if (byStrand[strand] === undefined) {
        byStrand[strand] = [];
      }
      byStrand[strand].push(exp);

      // By grade and subject
      if (byGrade[exp.grade] === undefined) {
        byGrade[exp.grade] = {};
      }
      if (byGrade[exp.grade][exp.subject] === undefined) {
        byGrade[exp.grade][exp.subject] = [];
      }
      byGrade[exp.grade][exp.subject].push(exp);
    });

    // Calculate coverage by subject
    const subjectCoverage = Object.entries(bySubject).map(([subject, exps]) => {
      const covered = exps.filter((exp) => coveredExpectationIds.has(exp.id)).length;
      return {
        subject,
        total: exps.length,
        covered,
        percentage: Math.round((covered / exps.length) * 100),
      };
    });

    // Calculate coverage by strand
    const strandCoverage: StrandCoverage[] = Object.entries(byStrand).map(([strand, exps]) => {
      const covered = exps.filter((exp) => coveredExpectationIds.has(exp.id)).length;
      return {
        strand,
        total: exps.length,
        covered,
        percentage: Math.round((covered / exps.length) * 100),
      };
    });

    // Calculate coverage by grade
    const gradeCoverage: GradeCoverage[] = Object.entries(byGrade)
      .map(([grade, subjects]) => {
        const subjectData = Object.entries(subjects).map(([subject, exps]) => {
          const covered = exps.filter((exp) => coveredExpectationIds.has(exp.id)).length;
          return {
            subject,
            total: exps.length,
            covered,
            percentage: Math.round((covered / exps.length) * 100),
          };
        });

        return {
          grade: Number(grade),
          subjects: subjectData,
        };
      })
      .sort((a, b) => a.grade - b.grade);

    // Overall metrics
    const totalExpectations = expectations.length;
    const coveredExpectations = expectations.filter((exp) =>
      coveredExpectationIds.has(exp.id),
    ).length;
    const overallPercentage =
      totalExpectations > 0 ? Math.round((coveredExpectations / totalExpectations) * 100) : 0;

    // Find gaps (uncovered expectations grouped by priority)
    const uncoveredExpectations = expectations.filter((exp) => !coveredExpectationIds.has(exp.id));
    // For now, treat all gaps as regular priority since we don't have type classification
    const highPriorityGaps: typeof expectations = [];
    const regularGaps = uncoveredExpectations;

    return {
      overall: {
        total: totalExpectations,
        covered: coveredExpectations,
        percentage: overallPercentage,
      },
      bySubject: subjectCoverage,
      byStrand: strandCoverage,
      byGrade: gradeCoverage,
      gaps: {
        highPriority: highPriorityGaps,
        regular: regularGaps,
      },
    };
  }, [expectations, unitPlans, lessonPlans]);

  // Colors for charts
  const COLORS = [
    '#4f46e5',
    '#10b981',
    '#f59e0b',
    '#ef4444',
    '#8b5cf6',
    '#3b82f6',
    '#06b6d4',
    '#ec4899',
  ];

  const getStatusColor = (percentage: number): string => {
    if (percentage >= 80) {
      return 'text-green-600';
    }
    if (percentage >= 60) {
      return 'text-yellow-600';
    }
    return 'text-red-600';
  };

  return (
    <div className="space-y-6">
      {/* Overall Coverage Summary */}
      <Card>
        <CardHeader>
          <CardTitle className="text-2xl">Curriculum Expectation Coverage</CardTitle>
          <CardDescription>
            Track how well your lesson plans cover the Ontario curriculum expectations
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="grid gap-6 md:grid-cols-3">
            <div className="text-center">
              <div className="text-4xl font-bold text-indigo-600">
                {coverageMetrics.overall.covered}
              </div>
              <div className="text-sm text-gray-600">Expectations Covered</div>
            </div>
            <div className="text-center">
              <div className="text-4xl font-bold text-gray-400">
                {coverageMetrics.overall.total - coverageMetrics.overall.covered}
              </div>
              <div className="text-sm text-gray-600">Remaining</div>
            </div>
            <div className="text-center">
              <div
                className={`text-4xl font-bold ${getStatusColor(coverageMetrics.overall.percentage)}`}
              >
                {coverageMetrics.overall.percentage}%
              </div>
              <div className="text-sm text-gray-600">Overall Coverage</div>
            </div>
          </div>
          <Progress className="mt-4 h-3" value={coverageMetrics.overall.percentage} />
        </CardContent>
      </Card>

      {/* Coverage Visualizations */}
      <Tabs className="space-y-4" defaultValue="subject">
        <TabsList className="grid w-full grid-cols-4">
          <TabsTrigger value="subject">By Subject</TabsTrigger>
          <TabsTrigger value="strand">By Strand</TabsTrigger>
          <TabsTrigger value="grade">By Grade</TabsTrigger>
          <TabsTrigger value="gaps">Coverage Gaps</TabsTrigger>
        </TabsList>

        <TabsContent value="subject">
          <Card>
            <CardHeader>
              <CardTitle>Coverage by Subject</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="grid gap-4 md:grid-cols-2">
                <div className="space-y-4">
                  {coverageMetrics.bySubject.map((subject, _index) => (
                    <div key={subject.subject} className="space-y-2">
                      <div className="flex justify-between items-center">
                        <span className="font-medium">{subject.subject}</span>
                        <span className={`font-bold ${getStatusColor(subject.percentage)}`}>
                          {subject.percentage}%
                        </span>
                      </div>
                      <Progress className="h-2" value={subject.percentage} />
                      <div className="text-sm text-gray-600">
                        {subject.covered} of {subject.total} expectations covered
                      </div>
                    </div>
                  ))}
                </div>
                <div className="h-64">
                  <ResponsiveContainer height="100%" width="100%">
                    <PieChart>
                      <Pie
                        cx="50%"
                        cy="50%"
                        data={coverageMetrics.bySubject}
                        dataKey="covered"
                        fill="#8884d8"
                        label={({ subject, percentage }) => `${subject}: ${percentage}%`}
                        labelLine={false}
                        outerRadius={80}
                      >
                        {coverageMetrics.bySubject.map((_entry, _index) => (
                          <Cell key={`cell-${_index}`} fill={COLORS[_index % COLORS.length]} />
                        ))}
                      </Pie>
                      <Tooltip />
                    </PieChart>
                  </ResponsiveContainer>
                </div>
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="strand">
          <Card>
            <CardHeader>
              <CardTitle>Coverage by Strand</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="h-96">
                <ResponsiveContainer height="100%" width="100%">
                  <BarChart
                    data={coverageMetrics.byStrand}
                    margin={{ top: 20, right: 30, left: 20, bottom: 60 }}
                  >
                    <CartesianGrid strokeDasharray="3 3" />
                    <XAxis angle={-45} dataKey="strand" height={100} textAnchor="end" />
                    <YAxis />
                    <Tooltip />
                    <Legend />
                    <Bar dataKey="covered" fill="#4f46e5" name="Covered" />
                    <Bar dataKey="total" fill="#e5e7eb" name="Total" />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="grade">
          <Card>
            <CardHeader>
              <CardTitle>Coverage by Grade Level</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-6">
                {coverageMetrics.byGrade.map((grade, _index) => (
                  <div key={grade.grade} className="space-y-3">
                    <h4 className="text-lg font-semibold">Grade {grade.grade}</h4>
                    <div className="grid gap-3 md:grid-cols-2 lg:grid-cols-3">
                      {grade.subjects.map((subject, _index) => (
                        <div key={subject.subject} className="p-3 bg-gray-50 rounded-lg">
                          <div className="flex justify-between items-center mb-2">
                            <span className="font-medium text-sm">{subject.subject}</span>
                            <Badge
                              variant={
                                subject.percentage >= 80
                                  ? 'default'
                                  : subject.percentage >= 60
                                    ? 'secondary'
                                    : 'destructive'
                              }
                            >
                              {subject.percentage}%
                            </Badge>
                          </div>
                          <Progress className="h-2" value={subject.percentage} />
                          <div className="text-xs text-gray-600 mt-1">
                            {subject.covered}/{subject.total} covered
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="gaps">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <AlertTriangle className="h-5 w-5 text-yellow-600" />
                Coverage Gaps Analysis
              </CardTitle>
              <CardDescription>
                Curriculum expectations not yet covered in your planning
              </CardDescription>
            </CardHeader>
            <CardContent>
              <div className="space-y-6">
                {/* High Priority Gaps */}
                {coverageMetrics.gaps.highPriority.length > 0 ? (
                  <div>
                    <h4 className="font-medium text-red-600 mb-3">
                      High Priority Expectations ({coverageMetrics.gaps.highPriority.length})
                    </h4>
                    <div className="space-y-2">
                      {coverageMetrics.gaps.highPriority.slice(0, 5).map((exp, _index) => (
                        <div key={exp.id} className="p-3 bg-red-50 rounded-lg">
                          <div className="flex items-start justify-between">
                            <div className="flex-1">
                              <div className="font-medium text-sm">
                                {exp.code} - {exp.subject} Grade {exp.grade}
                              </div>
                              <div className="text-sm text-gray-600 mt-1">{exp.description}</div>
                            </div>
                            <Badge className="ml-2" variant="destructive">
                              Regular
                            </Badge>
                          </div>
                        </div>
                      ))}
                      {coverageMetrics.gaps.highPriority.length > 5 && (
                        <div className="text-sm text-gray-600 text-center">
                          +{coverageMetrics.gaps.highPriority.length - 5} more high priority gaps
                        </div>
                      )}
                    </div>
                  </div>
                ) : null}

                {/* Regular Gaps */}
                {coverageMetrics.gaps.regular.length > 0 ? (
                  <div>
                    <h4 className="font-medium text-yellow-600 mb-3">
                      Regular Expectations ({coverageMetrics.gaps.regular.length})
                    </h4>
                    <div className="space-y-2">
                      {coverageMetrics.gaps.regular.slice(0, 5).map((exp, _index) => (
                        <div key={exp.id} className="p-3 bg-yellow-50 rounded-lg">
                          <div className="flex items-start">
                            <div className="flex-1">
                              <div className="font-medium text-sm">
                                {exp.code} - {exp.subject} Grade {exp.grade}
                              </div>
                              <div className="text-sm text-gray-600 mt-1">{exp.description}</div>
                            </div>
                          </div>
                        </div>
                      ))}
                      {coverageMetrics.gaps.regular.length > 5 && (
                        <div className="text-sm text-gray-600 text-center">
                          +{coverageMetrics.gaps.regular.length - 5} more regular gaps
                        </div>
                      )}
                    </div>
                  </div>
                ) : null}

                {/* No Gaps Message */}
                {coverageMetrics.gaps.highPriority.length === 0 &&
                  coverageMetrics.gaps.regular.length === 0 ? (
                    <div className="text-center py-8">
                      <Target className="h-12 w-12 text-green-600 mx-auto mb-3" />
                      <p className="text-lg font-medium text-green-600">Excellent Coverage!</p>
                      <p className="text-gray-600">
                        All curriculum expectations are covered in your planning.
                      </p>
                    </div>
                  ) : null}
              </div>
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
}

import * as RadixDialog from '@radix-ui/react-dialog';
import type { ReactNode } from 'react';

interface DialogProps {
  open: boolean;
  onOpenChange?: (open: boolean) => void;
  onClose?: () => void;
  children: ReactNode;
  title?: string;
  maxWidth?: string;
  description?: string;
}

function Dialog({
  open,
  onOpenChange,
  onClose,
  children,
  title,
  maxWidth = 'lg',
  description,
}: DialogProps): React.ReactElement {
  // Helper to check if string has content
  const hasContent = (value: string | undefined): boolean => 
    value !== undefined && value.trim() !== '';

  const handleOpenChange = (newOpen: boolean): void => {
    if (onOpenChange !== undefined) {
      onOpenChange(newOpen);
    }
    if (!newOpen && onClose !== undefined) {
      onClose();
    }
  };

  const maxWidthClasses = {
    sm: 'max-w-sm',
    md: 'max-w-md',
    lg: 'max-w-lg',
    xl: 'max-w-xl',
    '2xl': 'max-w-2xl',
    '3xl': 'max-w-3xl',
    '4xl': 'max-w-4xl',
  };

  return (
    <RadixDialog.Root open={open} onOpenChange={handleOpenChange}>
      <RadixDialog.Portal>
        <RadixDialog.Overlay aria-hidden="true" className="fixed inset-0 bg-black/50 z-50" />
        <RadixDialog.Content
          aria-describedby={hasContent(description) ? 'dialog-description' : undefined}
          aria-labelledby={hasContent(title) ? 'dialog-title' : undefined}
          aria-modal="true"
          className="fixed inset-0 z-50 flex items-center justify-center outline-none"
          role="dialog"
        >
          <div
            className={`bg-white rounded shadow w-full ${maxWidthClasses[maxWidth as keyof typeof maxWidthClasses] ?? maxWidthClasses.lg} mx-4`}
          >
            {hasContent(title) && (
              <div className="px-6 py-4 border-b">
                <RadixDialog.Title asChild>
                  <h2 className="text-lg font-semibold" id="dialog-title">
                    {title}
                  </h2>
                </RadixDialog.Title>
              </div>
            )}
            {hasContent(description) && (
              <RadixDialog.Description asChild>
                <p className="sr-only" id="dialog-description">
                  {description}
                </p>
              </RadixDialog.Description>
            )}
            <div className="p-6 max-h-[80vh] overflow-y-auto">{children}</div>
          </div>
        </RadixDialog.Content>
      </RadixDialog.Portal>
    </RadixDialog.Root>
  );
}

export { Dialog };

import {
  CheckCircle2,
  Circle,
  AlertCircle,
  TrendingUp,
  Calendar,
  Clock,
  Target,
  Users,
} from 'lucide-react';
import React from 'react';

import { Badge } from '@/components/ui/Badge';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Progress } from '@/components/ui/Progress';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';

import {
  useLongRangePlans,
  useUnitPlans,
  useETFOLessonPlans,
  useDaybookEntries,
} from '../hooks/useETFOPlanning';
import { useETFOProgress } from '../hooks/useETFOProgress';

interface PlanningLevel {
  name: string;
  icon: React.ReactNode;
  total: number;
  completed: number;
  inProgress: number;
  notStarted: number;
  description: string;
}

export default function ETFOPlanningCoverage(): React.ReactElement {
  // Fetch data for all planning levels
  const { data: longRangePlans = [] } = useLongRangePlans();
  const { data: unitPlans = [] } = useUnitPlans();
  const { data: lessonPlans = [] } = useETFOLessonPlans();
  const { data: daybookEntries = [] } = useDaybookEntries();
  const { progressData } = useETFOProgress();

  // Calculate coverage for each planning level
  const planningLevels: PlanningLevel[] = [
    {
      name: 'Long-Range Plans',
      icon: <Calendar className="h-5 w-5" />,
      total: 8, // Assuming 8 subjects for elementary
      completed: longRangePlans.filter((p) => p.goals !== '' && (p.themes?.length ?? 0) > 0).length,
      inProgress: longRangePlans.filter((p) => p.goals !== '' && (p.themes?.length ?? 0) === 0).length,
      notStarted: 8 - longRangePlans.length,
      description: 'Year-long curriculum organization by subject',
    },
    {
      name: 'Unit Plans',
      icon: <Target className="h-5 w-5" />,
      total: longRangePlans.reduce((sum, lrp) => sum + (lrp._count?.unitPlans ?? 0) + 5, 0), // Expected units
      completed: unitPlans.filter(
        (u) => u.bigIdeas !== '' && u.assessmentPlan !== '' && (u.successCriteria?.length ?? 0) > 0,
      ).length,
      inProgress: unitPlans.filter(
        (u) => u.bigIdeas !== '' && (u.assessmentPlan === '' || (u.successCriteria?.length ?? 0) === 0),
      ).length,
      notStarted: unitPlans.filter((u) => u.bigIdeas === '').length,
      description: '3-6 week thematic units with big ideas and assessments',
    },
    {
      name: 'Lesson Plans',
      icon: <Clock className="h-5 w-5" />,
      total: unitPlans.reduce((sum, unit) => sum + (unit.estimatedHours ?? 20), 0), // Estimated lessons needed
      completed: lessonPlans.filter((l) => l.mindsOn !== '' && l.action !== '' && l.consolidation !== '').length,
      inProgress: lessonPlans.filter(
        (l) =>
          (l.mindsOn !== '' || l.action !== '' || l.consolidation !== '') && !(l.mindsOn !== '' && l.action !== '' && l.consolidation !== ''),
      ).length,
      notStarted: lessonPlans.filter((l) => l.mindsOn === '' && l.action === '' && l.consolidation === '').length,
      description: 'Daily lessons with three-part structure',
    },
    {
      name: 'Daybook Reflections',
      icon: <Users className="h-5 w-5" />,
      total: lessonPlans.length, // One reflection per lesson
      completed: daybookEntries.filter((d) => d.whatWorked !== '' && d.nextSteps !== '').length,
      inProgress: daybookEntries.filter(
        (d) => (d.whatWorked !== '' || d.nextSteps !== '') && !(d.whatWorked !== '' && d.nextSteps !== ''),
      ).length,
      notStarted: lessonPlans.length - daybookEntries.length,
      description: 'Daily reflections and student observations',
    },
  ];

  const calculatePercentage = (completed: number, total: number): number => total > 0 ? Math.round((completed / total) * 100) : 0;

  const getStatusColor = (percentage: number): string => {
    if (percentage >= 80) {
return 'text-green-600';
}
    if (percentage >= 50) {
return 'text-yellow-600';
}
    return 'text-red-600';
  };

  // Calculate overall progress
  const overallTotal = planningLevels.reduce((sum, level) => sum + level.total, 0);
  const overallCompleted = planningLevels.reduce((sum, level) => sum + level.completed, 0);
  const overallPercentage = calculatePercentage(overallCompleted, overallTotal);

  return (
    <div className="space-y-6">
      {/* Overall Progress Card */}
      <Card>
        <CardHeader>
          <CardTitle className="text-2xl">ETFO Planning Coverage Dashboard</CardTitle>
          <CardDescription>
            Track your progress across all five levels of ETFO-aligned planning
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <span className="text-lg font-medium">Overall Progress</span>
              <span className={`text-2xl font-bold ${getStatusColor(overallPercentage)}`}>
                {overallPercentage}%
              </span>
            </div>
            <Progress className="h-3" value={overallPercentage} />
            <div className="grid grid-cols-3 gap-4 mt-4">
              <div className="text-center">
                <div className="text-2xl font-bold text-green-600">{overallCompleted}</div>
                <div className="text-sm text-gray-600">Completed</div>
              </div>
              <div className="text-center">
                <div className="text-2xl font-bold text-yellow-600">
                  {planningLevels.reduce((sum, level) => sum + level.inProgress, 0)}
                </div>
                <div className="text-sm text-gray-600">In Progress</div>
              </div>
              <div className="text-center">
                <div className="text-2xl font-bold text-gray-400">
                  {planningLevels.reduce((sum, level) => sum + level.notStarted, 0)}
                </div>
                <div className="text-sm text-gray-600">Not Started</div>
              </div>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Planning Levels Breakdown */}
      <div className="grid gap-4 md:grid-cols-2">
        {planningLevels.map((level, _index) => {
          const percentage = calculatePercentage(level.completed, level.total);
          return (
            <Card key={level.name}>
              <CardHeader>
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    {level.icon}
                    <CardTitle className="text-lg">{level.name}</CardTitle>
                  </div>
                  <Badge
                    variant={
                      percentage >= 80
                        ? 'default'
                        : percentage >= 50
                          ? 'secondary'
                          : 'destructive'
                    }
                  >
                    {percentage}%
                  </Badge>
                </div>
                <CardDescription>{level.description}</CardDescription>
              </CardHeader>
              <CardContent>
                <div className="space-y-3">
                  <Progress className="h-2" value={percentage} />
                  <div className="grid grid-cols-3 gap-2 text-sm">
                    <div className="flex items-center gap-1">
                      <CheckCircle2 className="h-4 w-4 text-green-600" />
                      <span>{level.completed} Complete</span>
                    </div>
                    <div className="flex items-center gap-1">
                      <AlertCircle className="h-4 w-4 text-yellow-600" />
                      <span>{level.inProgress} In Progress</span>
                    </div>
                    <div className="flex items-center gap-1">
                      <Circle className="h-4 w-4 text-gray-400" />
                      <span>{level.notStarted} Not Started</span>
                    </div>
                  </div>
                </div>
              </CardContent>
            </Card>
          );
        })}
      </div>

      {/* Detailed Coverage by Subject/Grade */}
      <Card>
        <CardHeader>
          <CardTitle>Coverage by Subject & Grade</CardTitle>
          <CardDescription>
            Detailed breakdown of planning coverage across subjects and grade levels
          </CardDescription>
        </CardHeader>
        <CardContent>
          <Tabs className="space-y-4" defaultValue="subject">
            <TabsList>
              <TabsTrigger value="subject">By Subject</TabsTrigger>
              <TabsTrigger value="timeline">Timeline View</TabsTrigger>
              <TabsTrigger value="gaps">Coverage Gaps</TabsTrigger>
            </TabsList>

            <TabsContent className="space-y-4" value="subject">
              {/* Group plans by subject */}
              {Object.entries(
                longRangePlans.reduce<Record<string, typeof longRangePlans>>(
                  (acc, plan) => {
                    if (!(plan.subject in acc)) {
                      acc[plan.subject] = [];
                    }
                    acc[plan.subject].push(plan);
                    return acc;
                  },
                  {},
                ),
              ).map(([subject, plans]) => (
                <div key={subject} className="space-y-2">
                  <h4 className="font-medium">{subject}</h4>
                  <div className="grid gap-2">
                    {plans.map((plan, _index) => {
                      const planUnits = unitPlans.filter((u) => u.longRangePlanId === plan.id);
                      const unitPercentage = (plan._count?.unitPlans !== undefined && plan._count.unitPlans > 0)
                        ? calculatePercentage(planUnits.length, plan._count.unitPlans)
                        : 0;

                      return (
                        <div
                          key={plan.id}
                          className="flex items-center justify-between p-3 bg-gray-50 rounded-lg"
                        >
                          <div>
                            <span className="font-medium">Grade {plan.grade}</span>
                            <span className="text-sm text-gray-600 ml-2">{plan.title}</span>
                          </div>
                          <div className="flex items-center gap-4">
                            <div className="text-sm">
                              <span className="text-gray-600">Units: </span>
                              <span className="font-medium">
                                {planUnits.length}/{plan._count?.unitPlans ?? '?'}
                              </span>
                            </div>
                            <Progress className="w-24 h-2" value={unitPercentage} />
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              ))}
            </TabsContent>

            <TabsContent className="space-y-4" value="timeline">
              <div className="text-center text-gray-600">
                <Calendar className="h-12 w-12 mx-auto mb-2 text-gray-400" />
                <p>Timeline visualization showing planning progress over the school year</p>
                <p className="text-sm mt-2">
                  This feature helps track which units are planned for each month
                </p>
              </div>
            </TabsContent>

            <TabsContent className="space-y-4" value="gaps">
              <div className="space-y-3">
                <h4 className="font-medium flex items-center gap-2">
                  <AlertCircle className="h-5 w-5 text-yellow-600" />
                  Planning Gaps Identified
                </h4>

                {/* Show units without lesson plans */}
                {unitPlans
                  .filter((unit) => {
                    const unitLessons = lessonPlans.filter((l) => l.unitPlanId === unit.id);
                    return unitLessons.length === 0;
                  })
                  .map((unit, _index) => (
                    <div key={unit.id} className="p-3 bg-yellow-50 rounded-lg">
                      <div className="flex items-center justify-between">
                        <div>
                          <span className="font-medium">{unit.title}</span>
                          <span className="text-sm text-gray-600 ml-2">
                            No lesson plans created
                          </span>
                        </div>
                        <Badge className="bg-yellow-100" variant="outline">
                          Needs Attention
                        </Badge>
                      </div>
                    </div>
                  ))}

                {/* Show lessons without reflections */}
                {lessonPlans
                  .filter((lesson) => {
                    const hasReflection = daybookEntries.some(
                      (d) =>
                        new Date(d.date).toDateString() === new Date(lesson.date).toDateString(),
                    );
                    return !hasReflection;
                  })
                  .slice(0, 5)
                  .map((lesson, _index) => (
                    <div key={lesson.id} className="p-3 bg-orange-50 rounded-lg">
                      <div className="flex items-center justify-between">
                        <div>
                          <span className="font-medium">{lesson.title}</span>
                          <span className="text-sm text-gray-600 ml-2">
                            Missing daybook reflection
                          </span>
                        </div>
                        <Badge className="bg-orange-100" variant="outline">
                          No Reflection
                        </Badge>
                      </div>
                    </div>
                  ))}
              </div>
            </TabsContent>
          </Tabs>
        </CardContent>
      </Card>

      {/* Progress Insights */}
      {progressData !== undefined && (
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <TrendingUp className="h-5 w-5" />
              Planning Insights
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid gap-4 md:grid-cols-3">
              <div className="text-center p-4 bg-blue-50 rounded-lg">
                <div className="text-2xl font-bold text-blue-600">
                  {Math.round((overallCompleted / Math.max(overallTotal, 1)) * 40)}h
                </div>
                <div className="text-sm text-gray-600">Weekly Planning Time</div>
              </div>
              <div className="text-center p-4 bg-green-50 rounded-lg">
                <div className="text-2xl font-bold text-green-600">{overallPercentage}%</div>
                <div className="text-sm text-gray-600">On-Time Completion</div>
              </div>
              <div className="text-center p-4 bg-purple-50 rounded-lg">
                <div className="text-2xl font-bold text-purple-600">
                  {Math.round((daybookEntries.length / Math.max(lessonPlans.length, 1)) * 100)}%
                </div>
                <div className="text-sm text-gray-600">Reflection Rate</div>
              </div>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

import { AlertCircle, RefreshCw, Home, Mail } from 'lucide-react';
import React, { Component } from 'react';
import type { ReactNode, ErrorInfo } from 'react';

import { errorReportingService } from '../services/errorReportingService';
import logger from '../utils/logger';

import { Alert, AlertDescription, AlertTitle } from './ui/alert';
import { Button } from './ui/Button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from './ui/card';
interface ErrorBoundaryProps {
  children: ReactNode;
  fallback?: ReactNode;
  onError?: (error: Error, errorInfo: ErrorInfo) => void;
  errorTitle?: string;
  errorDescription?: string;
  showDetails?: boolean;
  allowRetry?: boolean;
  allowHome?: boolean;
  supportEmail?: string;
}

interface ErrorBoundaryState {
  hasError: boolean;
  error?: Error;
  errorInfo?: ErrorInfo;
  retryCount: number;
}

// Base Error Boundary with customizable options
class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  constructor(props: ErrorBoundaryProps) {
    super(props);
    this.state = { hasError: false, retryCount: 0 };
  }

  static getDerivedStateFromError(error: Error): Partial<ErrorBoundaryState> {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo): void {
    logger.error('ErrorBoundary caught an error:', error, errorInfo);
    this.setState({ errorInfo });

    // Call custom error handler if provided
    if (this.props.onError !== undefined) {
      this.props.onError(error, errorInfo);
    }

    // Send to error reporting service
    errorReportingService.captureError(error, {
      component: 'ErrorBoundary',
      errorBoundaryProps: {
        errorTitle: this.props.errorTitle,
        errorDescription: this.props.errorDescription,
      },
      retryCount: this.state.retryCount,
    }, errorInfo);
  }

  handleReset = (): void => {
    this.setState({ 
      hasError: false, 
      error: undefined, 
      errorInfo: undefined,
      retryCount: this.state.retryCount + 1 
    });
  };

  render(): React.ReactNode {
    if (this.state.hasError) {
      if (this.props.fallback !== undefined) {
        return this.props.fallback;
      }

      const { 
        errorTitle = 'Something went wrong', 
        errorDescription = 'An unexpected error occurred. Please try again.',
        showDetails = process.env.NODE_ENV === 'development',
        allowRetry = true,
        allowHome = true,
        supportEmail
      } = this.props;

      return (
        <div className="min-h-[400px] flex items-center justify-center p-4">
          <Card className="max-w-lg w-full">
            <CardHeader>
              <div className="flex items-center gap-2">
                <AlertCircle className="h-5 w-5 text-red-500" />
                <CardTitle>{errorTitle}</CardTitle>
              </div>
              <CardDescription>{errorDescription}</CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              {this.state.retryCount > 2 ? (
                <Alert variant="destructive">
                  <AlertTitle>Multiple Errors</AlertTitle>
                  <AlertDescription>
                    This error has occurred multiple times. Please refresh the page or contact support.
                  </AlertDescription>
                </Alert>
              ) : null}

              <div className="flex flex-wrap gap-2">
                {allowRetry ? (
                  <Button aria-label="Click button" onClick={this.handleReset}>
                    <RefreshCw className="h-4 w-4 mr-2" />
                    Try Again
                  </Button>
                ) : null}

                {allowHome ? (
                  <Button aria-label="Click button" onClick={(): void => {
                    window.location.href = '/';
                  }}>
                    <Home className="h-4 w-4 mr-2" />
                    Go Home
                  </Button>
                ) : null}

                {supportEmail !== undefined && supportEmail !== '' ? (
                  <Button 
                    variant="outline" 
                    onClick={(): void => {
                      window.location.href = `mailto:${supportEmail}?subject=Error Report`;
                    }}
                  >
                    <Mail className="h-4 w-4 mr-2" />
                    Contact Support
                  </Button>
                ) : null}
              </div>

              {showDetails && this.state.error !== undefined ? (
                <details className="mt-4 bg-gray-100 p-4 rounded-md">
                  <summary className="cursor-pointer font-medium text-gray-700">
                    Error Details (Development)
                  </summary>
                  <div className="mt-2">
                    <div className="text-xs text-gray-600">
                      {this.state.error instanceof Error ? this.state.error.message : String(this.state.error)}
                    </div>
                    {this.state.error instanceof Error && this.state.error.stack !== undefined && this.state.error.stack !== '' ? (
                      <pre className="mt-2 text-xs text-gray-600 whitespace-pre-wrap overflow-auto">
                        {this.state.error.stack}
                      </pre>
                    ) : null}
                    {this.state.errorInfo !== undefined && this.state.errorInfo.componentStack !== undefined && this.state.errorInfo.componentStack !== '' ? (
                      <pre className="mt-2 text-xs text-gray-600 whitespace-pre-wrap overflow-auto">
                        Component Stack:{'\n'}{this.state.errorInfo.componentStack}
                      </pre>
                    ) : null}
                  </div>
                </details>
              ) : null}
            </CardContent>
          </Card>
        </div>
      );
    }

    return this.props.children;
  }
}

// Feature-specific error boundaries
