// Create alias for backward compatibility
const ErrorBoundaries = ErrorBoundary;

// Named exports for all error boundaries
export { ErrorBoundary, ErrorBoundaries };

import type { ReactNode } from 'react';
import React, { Component } from 'react';

import logger from '../utils/logger';
interface Props {
  children: ReactNode;
  fallback?: ReactNode;
}

interface State {
  hasError: boolean;
  error?: Error;
}

export default class ErrorBoundary extends Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = { hasError: false };
  }

  static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: React.ErrorInfo): void {
    logger.error('=== ERROR BOUNDARY CAUGHT AN ERROR ===');
    logger.error(`Error: ${error.name} - ${(error instanceof Error ? error.message : String(error))}`);
    logger.error('Error stack:', error.stack);
    logger.error('Component stack:', errorInfo.componentStack);
    logger.error('======================================');
  }

  render(): React.ReactNode {
    if (this.state.hasError) {
      if (this.props.fallback) {
        return this.props.fallback;
      }

      return (
        <div className="min-h-screen flex items-center justify-center bg-gray-50">
          <div className="max-w-md mx-auto text-center">
            <div className="mx-auto h-12 w-12 text-red-400">
              <svg fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path
                  d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-2.5L13.732 4c-.77-.833-1.964-.833-2.732 0L3.732 16.5c-.77.833.192 2.5 1.732 2.5z"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                />
              </svg>
            </div>
            <h1 className="mt-4 text-xl font-semibold text-gray-900">Something went wrong</h1>
            <p className="mt-2 text-gray-600">
              We&apos;re sorry, but something unexpected happened. Please refresh the page and try
              again.
            </p>
            <div className="mt-6">
              <button
                className="inline-flex items-center px-4 py-2 border border-transparent text-sm font-medium rounded-md text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500"
                onClick={() => {
 window.location.reload(); 
}}
              >
                Refresh Page
              </button>
            </div>
            {process.env.NODE_ENV === 'development' && this.state.error && (
              <details className="mt-4 text-left bg-gray-100 p-4 rounded-md">
                <summary className="cursor-pointer font-medium text-gray-700">
                  Error Details (Development)
                </summary>
                <pre className="mt-2 text-xs text-gray-600 whitespace-pre-wrap">
                  {this.state.error.stack}
                </pre>
              </details>
            )}
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

import React, { useState } from 'react';

import { useAddCalendarEvent } from '../api/domains/calendar';

import { Dialog } from './Dialog';

interface Props {
  onClose: () => void;
}

export default function EventEditorModal({ onClose }: Props): React.ReactElement {
  const [title, setTitle] = useState('');
  const [date, setDate] = useState('');
  const mutation = useAddCalendarEvent();

  const submit = (): void => {
    if (date === null || date === undefined || date === '' || title === null || title === undefined || title === '') {
return;
}
    mutation.mutate({
      title,
      start: `${date}T00:00:00.000Z`,
      end: `${date}T23:59:59.000Z`,
      allDay: true,
      eventType: 'CUSTOM',
      source: 'MANUAL',
    });
    onClose();
  };

  return (
    <Dialog open onOpenChange={onClose}>
      <div className="space-y-2 w-64">
        <h2 className="text-lg">Add Event</h2>
        <input
          className="border p-1 w-full"
          placeholder="Title"
          value={title}
          onChange={(e): void => {
 setTitle(e.target.value); 
}}
        />
        <input
          className="border p-1 w-full"
          type="date"
          value={date}
          onChange={(e): void => {
 setDate(e.target.value); 
}}
        />
        <div className="flex gap-2 mt-2">
          <button className="px-2 py-1 bg-blue-500 text-white rounded" onClick={submit}>
            Save
          </button>
          <button
            className="px-2 py-1 bg-gray-200 text-gray-800 rounded border"
            type="button"
            onClick={onClose}
          >
            Cancel
          </button>
        </div>
      </div>
    </Dialog>
  );
}

import React, { useState } from 'react';

import { useUploadResource } from '../api/domains/resource/hooks';

// Updated for ETFO-aligned media resource uploads
export default function FileUpload(): React.ReactElement {
  const [file, setFile] = useState<File | null>(null);
  const upload = useUploadResource();

  return (
    <div className="space-y-2">
      <input type="file" onChange={(e): void => {
 setFile(e.target.files !== null && e.target.files !== undefined && e.target.files.length > 0 ? e.target.files[0] : null); 
}} />
      <button
        className="border px-2 py-1"
        disabled={file === null || file === undefined}
        onClick={(): void => {
          if (file !== null && file !== undefined) {
            upload.mutate({
              file,
              metadata: {
                title: file.name,
                description: '',
                tags: [],
                category: 'document'
              }
            });
          }
        }}
      >
        Upload
      </button>
    </div>
  );
}

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';

import { useKeyboardShortcut } from '../hooks/useKeyboardShortcut';

import { KeyboardShortcutsHelp } from './KeyboardShortcutsHelp';
// import { useNotification } from '../contexts/NotificationContext';

export const GlobalKeyboardShortcuts: React.FC = (): React.ReactElement => {
  const navigate = useNavigate();
  const _location = useLocation();
  // const { addNotification } = useNotification();
  const [isHelpOpen, setIsHelpOpen] = useState(false);
  const [isSearchOpen, setIsSearchOpen] = useState(false);

  // Wrap all handlers in useCallback to prevent infinite re-renders
  const handleShowHelp = useCallback((): void => {
 setIsHelpOpen(true); 
}, []) // eslint-disable-line react-hooks/exhaustive-deps
  const handleCreateNewLesson = useCallback((): void => {
    navigate('/planner/quick-lesson');
    // addNotification('info', 'Create a new lesson plan');
  }, [navigate]);
  const handleSave = useCallback((): void => {
    // Dispatch a custom event that components can listen to
    window.dispatchEvent(new CustomEvent('global:save'));
    // addNotification('success', 'Saved successfully');
  }, []) // eslint-disable-line react-hooks/exhaustive-deps

  // Global: Show keyboard shortcuts help (? or F1)
  useKeyboardShortcut(handleShowHelp, {
    key: '?',
    description: 'Show keyboard shortcuts help',
    category: 'global',
  });

  useKeyboardShortcut(handleShowHelp, {
    key: 'F1',
    description: 'Show help',
    category: 'global',
  });

  // Global: Create new lesson plan (Ctrl/Cmd + N)
  useKeyboardShortcut(
    handleCreateNewLesson,
    {
      key: 'n',
      ctrl: true,
      cmd: true,
      description: 'Create new lesson plan',
      category: 'global',
    },
  );

  // Global: Save current work (Ctrl/Cmd + S)
  useKeyboardShortcut(
    handleSave,
    {
      key: 's',
      ctrl: true,
      cmd: true,
      description: 'Save current work',
      category: 'global',
      preventDefault: true,
    },
  );

  // Global: Search/Find (Ctrl/Cmd + F)
  const handleSearch = useCallback((): void => {
    setIsSearchOpen(true);
    // Dispatch event for components to handle search
    window.dispatchEvent(new CustomEvent('global:search'));
  }, []) // eslint-disable-line react-hooks/exhaustive-deps

  useKeyboardShortcut(handleSearch, {
    key: 'f',
    ctrl: true,
    cmd: true,
    description: 'Search/Find',
    category: 'global',
    preventDefault: true,
  });

  const handleEscape = useCallback((): void => {
    // Dispatch event for components to handle escape
    window.dispatchEvent(new CustomEvent('global:escape'));
    setIsSearchOpen(false);
  }, []) // eslint-disable-line react-hooks/exhaustive-deps

  const handleNavigateDashboard = useCallback((): void => {
 navigate('/planner/dashboard'); 
}, [navigate]);
  const handleNavigatePlanning = useCallback((): void => {
 navigate('/planner/long-range'); 
}, [navigate]);
  const handleNavigateCurriculum = useCallback((): void => {
 navigate('/curriculum'); 
}, [navigate]);
  const handleNavigateHelp = useCallback((): void => {
 navigate('/help'); 
}, [navigate]);
  const handleGoBack = useCallback((): void => {
 window.history.back(); 
}, []) // eslint-disable-line react-hooks/exhaustive-deps
  const handleGoForward = useCallback((): void => {
 window.history.forward(); 
}, []) // eslint-disable-line react-hooks/exhaustive-deps

  // Global: Close modals/overlays (Escape)
  useKeyboardShortcut(
    handleEscape,
    {
      key: 'Escape',
      description: 'Close modals/overlays',
      category: 'global',
      visible: false, // Don't show in help since it's obvious
    },
  );

  // Navigation: Dashboard (Alt + D)
  useKeyboardShortcut(handleNavigateDashboard, {
    key: 'd',
    alt: true,
    description: 'Go to Dashboard',
    category: 'navigation',
  });

  // Navigation: Planning (Alt + P)
  useKeyboardShortcut(handleNavigatePlanning, {
    key: 'p',
    alt: true,
    description: 'Go to Planning',
    category: 'navigation',
  });

  // Navigation: Curriculum (Alt + C)
  useKeyboardShortcut(handleNavigateCurriculum, {
    key: 'c',
    alt: true,
    description: 'Go to Curriculum',
    category: 'navigation',
  });

  // Navigation: Help (Alt + H)
  useKeyboardShortcut(handleNavigateHelp, {
    key: 'h',
    alt: true,
    description: 'Go to Help',
    category: 'navigation',
  });

  // Navigation: Previous page (Alt + Left Arrow)
  useKeyboardShortcut(handleGoBack, {
    key: 'ArrowLeft',
    alt: true,
    description: 'Go back',
    category: 'navigation',
  });

  // Navigation: Next page (Alt + Right Arrow)
  useKeyboardShortcut(handleGoForward, {
    key: 'ArrowRight',
    alt: true,
    description: 'Go forward',
    category: 'navigation',
  });

  return (
    <div data-testid="keyboard-shortcuts-container">
      <KeyboardShortcutsHelp isOpen={isHelpOpen} onClose={(): void => {
 setIsHelpOpen(false); 
}} />

      {/* Global Search Modal */}
      {isSearchOpen && <GlobalSearch onClose={(): void => {
 setIsSearchOpen(false); 
}} />}
    </div>
  );
};

// Simple global search component
const GlobalSearch: React.FC<{ onClose: () => void }> = ({ onClose }): React.ReactElement => {
  const [query, setQuery] = useState('');
  const navigate = useNavigate();
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    // Focus input when component mounts
    inputRef.current?.focus();
  }, []);

  const handleSearch = (e: React.FormEvent): void => {
    e.preventDefault();
    if (query !== null && query !== undefined && query.trim() !== '') {
      // Navigate to curriculum page with search query
      navigate(`/curriculum?search=${encodeURIComponent(query)}`);
      onClose();
    }
  };

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto">
      <div className="flex min-h-screen items-start justify-center px-4 pt-20">
        <div
          aria-label="Close search dialog"
          className="fixed inset-0 bg-gray-500 bg-opacity-75 transition-opacity"
          role="button"
          tabIndex={0}
          onClick={onClose}
          onKeyDown={(e) => {
            if (e.key === 'Enter' || e.key === ' ') {
              onClose();
            }
          }}
        />

        <div className="relative bg-white rounded-lg shadow-xl p-6 w-full max-w-lg">
          <h3 className="text-lg font-medium text-gray-900 mb-4">Search Teaching Engine</h3>

          <form onSubmit={handleSearch}>
            <input
              ref={inputRef}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              placeholder="Search for curriculum, lessons, or resources..."
              type="text"
              value={query}
              onChange={(e): void => {
 setQuery(e.target.value); 
}}
            />

            <div className="mt-4 flex justify-end space-x-3">
              <button
                className="px-4 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-md hover:bg-gray-50"
                type="button"
                onClick={onClose}
              >
                Cancel
              </button>
              <button
                className="px-4 py-2 text-sm font-medium text-white bg-blue-600 border border-transparent rounded-md hover:bg-blue-700"
                type="submit"
              >
                Search
              </button>
            </div>
          </form>

          <p className="mt-2 text-xs text-gray-500">
            Press{' '}
            <kbd className="px-1 py-0.5 text-xs bg-gray-100 border border-gray-300 rounded">
              Esc
            </kbd>{' '}
            to close
          </p>
        </div>
      </div>
    </div>
  );
};

