// Standalone hook to show keyboard shortcuts help
export const useKeyboardShortcutsHelp = (): { isOpen: boolean; showHelp: () => void; hideHelp: () => void; } => {
  const [isOpen, setIsOpen] = useState(false);

  const showHelp = (): void => {
 setIsOpen(true); 
};
  const hideHelp = (): void => {
 setIsOpen(false); 
};

  return { isOpen, showHelp, hideHelp };
};

import { useState } from 'react';

import { useLanguage } from '../contexts/LanguageContext';

export default function LanguageSwitcher(): React.ReactElement {
  const { language, setLanguage } = useLanguage();
  const [isOpen, setIsOpen] = useState(false);

  const languages = [
    { code: 'en', name: 'English', flag: '🇨🇦' },
    { code: 'fr', name: 'Français', flag: '🇫🇷' },
  ];

  const currentLanguage = languages.find((lang) => lang.code === language) ?? languages[0];

  const handleLanguageChange = (langCode: string): void => {
    setLanguage(langCode);
    setIsOpen(false);
  };

  return (
    <div className="relative">
      <button
        aria-label="Switch language"
        className="flex items-center gap-2 px-3 py-2 text-sm text-gray-700 hover:text-gray-900 hover:bg-gray-50 rounded-md transition-colors"
        onClick={() => {
 setIsOpen(!isOpen); 
}}
      >
        <span className="text-lg">{currentLanguage.flag}</span>
        <span className="hidden sm:block">{currentLanguage.name}</span>
        <svg
          className={`w-4 h-4 transition-transform ${isOpen ? 'rotate-180' : ''}`}
          fill="none"
          stroke="currentColor"
          viewBox="0 0 24 24"
        >
          <path d="M19 9l-7 7-7-7" strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} />
        </svg>
      </button>

      {isOpen && (
        <>
          {/* Backdrop */}
          <div className="fixed inset-0 z-10" onClick={() => {
 setIsOpen(false); 
}} />

          {/* Dropdown */}
          <div className="absolute right-0 mt-1 w-48 bg-white rounded-md shadow-lg border border-gray-200 z-20">
            <div className="py-1">
              {languages.map((lang, _index) => (
                <button
                  key={lang.code}
                  className={`w-full text-left px-4 py-2 text-sm hover:bg-gray-50 flex items-center gap-3 ${
                    language === lang.code ? 'bg-blue-50 text-blue-700' : 'text-gray-700'
                  }`}
                  onClick={() => {
 handleLanguageChange(lang.code); 
}}
                >
                  <span className="text-lg">{lang.flag}</span>
                  <span>{lang.name}</span>
                  {language === lang.code && (
                    <svg
                      className="w-4 h-4 ml-auto text-blue-600"
                      fill="currentColor"
                      viewBox="0 0 20 20"
                    >
                      <path
                        clipRule="evenodd"
                        d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z"
                        fillRule="evenodd"
                      />
                    </svg>
                  )}
                </button>
              ))}
            </div>
          </div>
        </>
      )}
    </div>
  );
}

import { 
  Bold, Italic, Underline, List, ListOrdered, 
  Undo, Redo, Type, Save, Send,
  Eye, Edit3, Languages, Trash2, RefreshCw
} from 'lucide-react';
import { useState, useRef, useEffect } from 'react';

import { cn } from '../lib/utils';
import type { NewsletterSection, NewsletterDraft, NewsletterTone } from '../types/newsletter';

interface NewsletterEditorProps {
  draft: NewsletterDraft;
  isGenerating?: boolean;
  onSave: (draft: NewsletterDraft) => void;
  onSend?: (draft: NewsletterDraft) => void;
  onRegenerate?: (tone?: NewsletterTone) => void;
  className?: string;
}

export function NewsletterEditor({
  draft,
  isGenerating = false,
  onSave,
  onSend,
  onRegenerate,
  className,
}: NewsletterEditorProps): React.ReactElement {
  const [editingSection, setEditingSection] = useState<string | null>(null);
  const [language, setLanguage] = useState<'en' | 'fr'>('en');
  const [previewMode, setPreviewMode] = useState(false);
  const [unsavedChanges, setUnsavedChanges] = useState(false);
  const [localDraft, setLocalDraft] = useState<NewsletterDraft>(draft);

  const editorRefs = useRef<Record<string, HTMLDivElement | null>>({});

  // Update local draft when prop changes
  useEffect((): (() => void) => {
    setLocalDraft(draft);
    setUnsavedChanges(false);

    return (): void => { // Cleanup
    };
  }, [draft]);

  // Auto-save functionality
  useEffect((): (() => void) | undefined => {
    if (unsavedChanges) {
      const timer = setTimeout((): void => {
        onSave(localDraft);
        setUnsavedChanges(false);
      }, 2000); // Auto-save after 2 seconds of inactivity

      return (): void => {
 clearTimeout(timer); 
};
    }

    return undefined;
  }, [localDraft, unsavedChanges, onSave]);

  const updateSection = (sectionId: string, field: 'content' | 'contentFr' | 'title' | 'titleFr', value: string): void => {
    const updatedSections = localDraft.sections.map((section): NewsletterSection =>
      section.id === sectionId
        ? { ...section, [field]: value }
        : section
    );

    setLocalDraft({ ...localDraft, sections: updatedSections });
    setUnsavedChanges(true);
  };

  const updateTitle = (field: 'title' | 'titleFr', value: string): void => {
    setLocalDraft({ ...localDraft, [field]: value });
    setUnsavedChanges(true);
  };

  const formatText = (command: string, value?: string): void => {
    document.execCommand(command, false, value);
  };

  const removeSection = (sectionId: string): void => {
    const updatedSections = localDraft.sections.filter((section): boolean => section.id !== sectionId);
    setLocalDraft({ ...localDraft, sections: updatedSections });
    setUnsavedChanges(true);
  };

  const addNewSection = (): void => {
    const newSection: NewsletterSection = {
      id: `section-${Date.now()}`,
      title: 'New Section',
      titleFr: 'Nouvelle Section',
      content: 'Start typing your content here...',
      contentFr: 'Commencez à taper votre contenu ici...',
      isEditable: true,
      order: localDraft.sections.length,
    };

    setLocalDraft({
      ...localDraft,
      sections: [...localDraft.sections, newSection]
    });
    setUnsavedChanges(true);
    setEditingSection(newSection.id);
  };

  const handleKeyDown = (e: React.KeyboardEvent, _sectionId: string, _field: 'content' | 'contentFr'): void => {
    if (e.ctrlKey || e.metaKey) {
      switch (e.key) {
        case 'b':
          e.preventDefault();
          formatText('bold');
          break;
        case 'i':
          e.preventDefault();
          formatText('italic');
          break;
        case 'u':
          e.preventDefault();
          formatText('underline');
          break;
        case 's':
          e.preventDefault();
          onSave(localDraft);
          setUnsavedChanges(false);
          break;
      }
    }
  };

  const renderToolbar = (_sectionId: string): React.ReactElement => (
    <div className="flex items-center gap-1 p-2 border-b bg-gray-50 rounded-t-lg">
      <button
        className="p-1.5 hover:bg-gray-200 rounded"
        title="Bold (Ctrl+B)"
        onClick={(): void => {
 formatText('bold'); 
}}
      >
        <Bold className="w-4 h-4" />
      </button>
      <button
        className="p-1.5 hover:bg-gray-200 rounded"
        title="Italic (Ctrl+I)"
        onClick={(): void => {
 formatText('italic'); 
}}
      >
        <Italic className="w-4 h-4" />
      </button>
      <button
        className="p-1.5 hover:bg-gray-200 rounded"
        title="Underline (Ctrl+U)"
        onClick={(): void => {
 formatText('underline'); 
}}
      >
        <Underline className="w-4 h-4" />
      </button>

      <div className="w-px h-6 bg-gray-300 mx-1" />

      <button
        className="p-1.5 hover:bg-gray-200 rounded"
        title="Bullet List"
        onClick={(): void => {
 formatText('insertUnorderedList'); 
}}
      >
        <List className="w-4 h-4" />
      </button>
      <button
        className="p-1.5 hover:bg-gray-200 rounded"
        title="Numbered List"
        onClick={(): void => {
 formatText('insertOrderedList'); 
}}
      >
        <ListOrdered className="w-4 h-4" />
      </button>

      <div className="w-px h-6 bg-gray-300 mx-1" />

      <button
        className="p-1.5 hover:bg-gray-200 rounded"
        title="Undo"
        onClick={(): void => {
 formatText('undo'); 
}}
      >
        <Undo className="w-4 h-4" />
      </button>
      <button
        className="p-1.5 hover:bg-gray-200 rounded"
        title="Redo"
        onClick={(): void => {
 formatText('redo'); 
}}
      >
        <Redo className="w-4 h-4" />
      </button>

      <div className="flex-1" />

      <button
        className="p-1.5 text-blue-600 hover:bg-blue-100 rounded text-sm font-medium"
        onClick={(): void => {
 setEditingSection(null); 
}}
      >
        Done
      </button>
    </div>
  );

  const renderSection = (section: NewsletterSection): React.ReactElement => {
    const isEditing = editingSection === section.id;
    const content = language === 'en' ? section.content : section.contentFr;
    const title = language === 'en' ? section.title : section.titleFr;

    return (
      <div key={section.id} className="border border-gray-200 rounded-lg overflow-hidden">
        {/* Section header */}
        <div className="flex items-center justify-between p-3 bg-gray-50 border-b">
          <div className="flex-1">
            {isEditing && section.isEditable ? (
              <input
                className="w-full px-2 py-1 text-sm font-medium bg-white border border-gray-300 rounded"
                placeholder="Section title..."
                type="text"
                value={title}
                onChange={(e): void => {
 updateSection(
                  section.id, 
                  language === 'en' ? 'title' : 'titleFr', 
                  e.target.value
                ); 
}}
              />
            ) : (
              <h3 className="text-sm font-medium text-gray-900">{title}</h3>
            )}
          </div>

          <div className="flex items-center gap-1">
            {section.isEditable && (
              <>
                <button
                  className="p-1.5 text-gray-600 hover:text-gray-800 hover:bg-gray-200 rounded"
                  title={isEditing ? "Stop editing" : "Edit section"}
                  onClick={(): void => {
 setEditingSection(isEditing ? null : section.id); 
}}
                >
                  <Edit3 className="w-4 h-4" />
                </button>
                <button
                  className="p-1.5 text-red-600 hover:text-red-800 hover:bg-red-100 rounded"
                  title="Remove section"
                  onClick={(): void => {
 removeSection(section.id); 
}}
                >
                  <Trash2 className="w-4 h-4" />
                </button>
              </>
            )}
          </div>
        </div>

        {/* Section content */}
        {isEditing && section.isEditable ? (
          <div>
            {renderToolbar(section.id)}
            <div
              ref={(el): void => {
                editorRefs.current[section.id] = el;
              }}
              contentEditable
              className="p-4 min-h-[100px] focus:outline-none prose prose-sm max-w-none"
              dangerouslySetInnerHTML={{ __html: content }}
              role="textbox"
              style={{ whiteSpace: 'pre-wrap' }}
              tabIndex={0}
              onBlur={(e): void => {
                updateSection(
                  section.id,
                  language === 'en' ? 'content' : 'contentFr',
                  e.currentTarget.innerHTML
                );
              }}
              onKeyDown={(e): void => {
                handleKeyDown(e, section.id, language === 'en' ? 'content' : 'contentFr');
              }}
            />
          </div>
        ) : (
          <div 
            className="p-4 prose prose-sm max-w-none"
            dangerouslySetInnerHTML={{ __html: content }}
          />
        )}
      </div>
    );
  };

  return (
    <div className={cn("max-w-4xl mx-auto", className)}>
      {/* Header controls */}
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-4">
          <h1 className="text-2xl font-bold text-gray-900">Newsletter Editor</h1>
          {unsavedChanges && (
            <span className="text-sm text-orange-600 font-medium">
              Unsaved changes...
            </span>
          )}
        </div>

        <div className="flex items-center gap-2">
          {/* Language toggle */}
          <button
            className={cn(
              "flex items-center gap-2 px-3 py-2 rounded-lg transition-colors",
              "border border-gray-300 hover:bg-gray-50"
            )}
            onClick={(): void => {
 setLanguage(language === 'en' ? 'fr' : 'en'); 
}}
          >
            <Languages className="w-4 h-4" />
            <span className="text-sm font-medium">
              {language === 'en' ? 'English' : 'Français'}
            </span>
          </button>

          {/* Preview toggle */}
          <button
            className={cn(
              "flex items-center gap-2 px-3 py-2 rounded-lg transition-colors",
              previewMode
                ? "bg-blue-600 text-white"
                : "border border-gray-300 hover:bg-gray-50"
            )}
            onClick={(): void => {
 setPreviewMode(!previewMode); 
}}
          >
            <Eye className="w-4 h-4" />
            <span className="text-sm font-medium">
              {previewMode ? 'Edit' : 'Preview'}
            </span>
          </button>

          {/* Action buttons */}
          {!previewMode && (
            <>
              {onRegenerate !== null && onRegenerate !== undefined && (
                <button
                  className="flex items-center gap-2 px-3 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 disabled:opacity-50"
                  disabled={isGenerating}
                  onClick={(): void => {
 onRegenerate(); 
}}
                >
                  <RefreshCw className={cn("w-4 h-4", isGenerating && "animate-spin")} />
                  <span className="text-sm font-medium">Regenerate</span>
                </button>
              )}

              <button
                className="flex items-center gap-2 px-3 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700"
                onClick={(): void => {
                  onSave(localDraft);
                  setUnsavedChanges(false);
                }}
              >
                <Save className="w-4 h-4" />
                <span className="text-sm font-medium">Save</span>
              </button>

              {onSend !== null && onSend !== undefined && (
                <button
                  className="flex items-center gap-2 px-3 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50"
                  disabled={localDraft.isDraft}
                  onClick={(): void => {
 onSend(localDraft); 
}}
                >
                  <Send className="w-4 h-4" />
                  <span className="text-sm font-medium">Send</span>
                </button>
              )}
            </>
          )}
        </div>
      </div>

      {/* Newsletter title */}
      <div className="mb-6">
        {!previewMode ? (
          <input
            className="w-full text-3xl font-bold text-gray-900 bg-transparent border-none focus:outline-none focus:ring-2 focus:ring-blue-500 rounded px-2 py-1"
            placeholder="Newsletter title..."
            type="text"
            value={language === 'en' ? localDraft.title : localDraft.titleFr}
            onChange={(e): void => {
 updateTitle(
              language === 'en' ? 'title' : 'titleFr',
              e.target.value
            ); 
}}
          />
        ) : (
          <h1 className="text-3xl font-bold text-gray-900">
            {language === 'en' ? localDraft.title : localDraft.titleFr}
          </h1>
        )}
      </div>

      {/* Loading state */}
      {isGenerating && (
        <div className="text-center py-8">
          <div className="inline-flex items-center gap-3 px-4 py-2 bg-blue-50 rounded-lg">
            <div className="animate-spin rounded-full h-5 w-5 border-t-2 border-b-2 border-blue-600" />
            <span className="text-blue-600 font-medium">Generating newsletter content...</span>
          </div>
        </div>
      )}

      {/* Newsletter sections */}
      <div className="space-y-6">
        {localDraft.sections
          .sort((a, b) => a.order - b.order)
          .map(renderSection)}

        {/* Add section button */}
        {!previewMode && (
          <button
            className="w-full py-4 border-2 border-dashed border-gray-300 rounded-lg text-gray-600 hover:border-gray-400 hover:text-gray-700 transition-colors"
            onClick={addNewSection}
          >
            <div className="flex items-center justify-center gap-2">
              <Type className="w-5 h-5" />
              <span className="font-medium">Add New Section</span>
            </div>
          </button>
        )}
      </div>

      {/* Footer info */}
      <div className="mt-8 pt-6 border-t border-gray-200 text-sm text-gray-500">
        <div className="flex justify-between items-center">
          <div>
            Template type: General newsletter | 
            Date range: {localDraft.dateFrom.toLocaleDateString()} - {localDraft.dateTo.toLocaleDateString()} |
            Tone: {localDraft.tone}
          </div>
          <div>
            {localDraft.isDraft ? 'Draft' : 'Finalized'} • 
            Last updated: {localDraft.updatedAt?.toLocaleString() ?? 'Never'}
          </div>
        </div>
      </div>
    </div>
  );
}

import { useNotificationContext } from '../contexts/NotificationContext';

export default function NotificationCenter(): React.ReactElement {
  const { notifications, markRead } = useNotificationContext();
  if (notifications.length === 0) {
return <div>No notifications</div>;
}
  return (
    <ul className="space-y-2">
      {notifications.map((n, _index) => (
        <li key={n.id} className="border p-2 flex justify-between">
          <span className={n.read ? 'opacity-50' : ''}>{n.message}</span>
          {!n.read && (
            <button className="text-sm underline" onClick={() => {
 markRead(n.id); 
}}>
              Mark read
            </button>
          )}
        </li>
      ))}
    </ul>
  );
}

// Offline Notification Component
// Shows a persistent notification when the app is offline

import { AlertCircle, RefreshCw, WifiOff, X } from 'lucide-react';
import React, { useEffect, useState } from 'react';

import { isOnline } from '../utils/serviceWorkerRegistration';

import { Button } from './ui/Button';

export function OfflineNotification(): React.ReactElement | null {
  const [isOnlineState, setIsOnlineState] = useState(isOnline());
  const [dismissed, setDismissed] = useState(false);
  const [retrying, setRetrying] = useState(false);

  useEffect(() => {
    const handleOnline = (): void => {
      setIsOnlineState(true);
      setDismissed(false);
    };

    const handleOffline = (): void => {
      setIsOnlineState(false);
      setDismissed(false);
    };

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const handleRetry = async (): Promise<void> => {
    setRetrying(true);

    // Try to fetch a small resource to check connectivity
    try {
      await fetch('/api/health', { method: 'HEAD' });
      setIsOnlineState(true);
    } catch {
      setIsOnlineState(false);
    } finally {
      setRetrying(false);
    }
  };

  // Don't show if online or dismissed
  if (isOnlineState !== null && isOnlineState !== undefined && isOnlineState || dismissed !== null && dismissed !== undefined && dismissed) {
    return null;
  }

  return (
    <div className="fixed bottom-4 left-4 right-4 md:left-auto md:right-4 md:max-w-md z-50 animate-slide-up">
      <div className="bg-yellow-50 border border-yellow-200 rounded-lg shadow-lg p-4">
        <div className="flex items-start">
          <div className="flex-shrink-0">
            <WifiOff className="h-5 w-5 text-yellow-600" />
          </div>
          <div className="ml-3 flex-1">
            <h3 className="text-sm font-medium text-yellow-800">
              You&apos;re offline
            </h3>
            <div className="mt-1 text-sm text-yellow-700">
              <p>You can continue working. Your changes will sync when you&apos;re back online.</p>
            </div>
            <div className="mt-3 flex items-center gap-2">
              <Button
                className="text-yellow-700 border-yellow-300 hover:bg-yellow-100"
                disabled={retrying}
                size="sm"
                variant="outline"
                onClick={() => {
 void handleRetry(); 
}}
              >
                {retrying !== null && retrying !== undefined && retrying ? (
                  <>
                    <RefreshCw className="w-3 h-3 mr-1 animate-spin" />
                    Checking...
                  </>
                ) : (
                  <>
                    <RefreshCw className="w-3 h-3 mr-1" />
                    Retry
                  </>
                )}
              </Button>
              <Button
                className="text-yellow-700 hover:bg-yellow-100"
                size="sm"
                variant="ghost"
                onClick={(): void => {
 setDismissed(true); 
}}
              >
                Dismiss
              </Button>
            </div>
          </div>
          <div className="ml-auto pl-3">
            <button
              className="inline-flex rounded-md bg-yellow-50 p-1.5 text-yellow-500 hover:bg-yellow-100 focus:outline-none focus:ring-2 focus:ring-yellow-600 focus:ring-offset-2 focus:ring-offset-yellow-50"
              onClick={(): void => {
 setDismissed(true); 
}}
            >
              <span className="sr-only">Dismiss</span>
              <X className="h-4 w-4" />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

// Conflict Resolution Modal Component
interface ConflictResolutionModalProps {
  conflict: {
    localData: unknown;
    remoteData: unknown;
    entity: string;
    entityId: string;
  };
  onResolve: (resolution: 'local' | 'remote' | 'merge', mergedData?: unknown) => void;
  onCancel: () => void;
}

export function ConflictResolutionModal({ 
  conflict, 
  onResolve, 
  onCancel 
}: ConflictResolutionModalProps): React.ReactElement {
  const [selectedResolution, setSelectedResolution] = useState<'local' | 'remote' | 'merge'>('local');
  const [_mergedData, _setMergedData] = useState<unknown>(null);

  const handleResolve = (): void => {
    if (selectedResolution !== null && selectedResolution !== undefined && selectedResolution === 'merge' && _mergedData !== null && _mergedData !== undefined) {
      onResolve('merge', _mergedData);
    } else {
      onResolve(selectedResolution);
    }
  };

  return (
    <div className="fixed inset-0 bg-gray-500 bg-opacity-75 flex items-center justify-center z-50">
      <div className="bg-white rounded-lg shadow-xl max-w-2xl w-full max-h-[80vh] overflow-hidden">
        <div className="px-6 py-4 border-b border-gray-200">
          <div className="flex items-center">
            <AlertCircle className="h-6 w-6 text-orange-500 mr-2" />
            <h3 className="text-lg font-medium text-gray-900">
              Sync Conflict Detected
            </h3>
          </div>
          <p className="mt-1 text-sm text-gray-500">
            Your offline changes conflict with updates from the server. Please choose how to resolve this conflict.
          </p>
        </div>

        <div className="px-6 py-4 overflow-y-auto max-h-[50vh]">
          <div className="space-y-4">
            {/* Local version */}
            <div className="border rounded-lg p-4">
              <label className="flex items-center cursor-pointer">
                <input
                  checked={selectedResolution === 'local'}
                  className="mr-3"
                  type="radio"
                  value="local"
                  onChange={(e): void => {
 setSelectedResolution(e.target.value as 'local'); 
}}
                />
                <div className="flex-1">
                  <div className="font-medium text-gray-900">Keep your version</div>
                  <div className="text-sm text-gray-500 mt-1">
                    Use the changes you made while offline
                  </div>
                  <div className="mt-2 p-2 bg-gray-50 rounded text-xs font-mono overflow-x-auto">
                    {JSON.stringify(conflict.localData, null, 2)}
                  </div>
                </div>
              </label>
            </div>

            {/* Remote version */}
            <div className="border rounded-lg p-4">
              <label className="flex items-center cursor-pointer">
                <input
                  checked={selectedResolution === 'remote'}
                  className="mr-3"
                  type="radio"
                  value="remote"
                  onChange={(e): void => {
 setSelectedResolution(e.target.value as 'remote'); 
}}
                />
                <div className="flex-1">
                  <div className="font-medium text-gray-900">Keep server version</div>
                  <div className="text-sm text-gray-500 mt-1">
                    Discard your offline changes and use the server version
                  </div>
                  <div className="mt-2 p-2 bg-gray-50 rounded text-xs font-mono overflow-x-auto">
                    {JSON.stringify(conflict.remoteData, null, 2)}
                  </div>
                </div>
              </label>
            </div>

            {/* Merge option (if applicable) */}
            <div className="border rounded-lg p-4">
              <label className="flex items-center cursor-pointer">
                <input
                  checked={selectedResolution === 'merge'}
                  className="mr-3"
                  type="radio"
                  value="merge"
                  onChange={(e): void => {
 setSelectedResolution(e.target.value as 'merge'); 
}}
                />
                <div className="flex-1">
                  <div className="font-medium text-gray-900">Merge changes</div>
                  <div className="text-sm text-gray-500 mt-1">
                    Combine both versions (recommended for non-conflicting changes)
                  </div>
                </div>
              </label>
            </div>
          </div>
        </div>

        <div className="px-6 py-4 border-t border-gray-200 flex justify-end gap-3">
          <Button aria-label="Click button" onClick={onCancel}>
            Cancel
          </Button>
          <Button aria-label="Click button" onClick={handleResolve}>
            Resolve Conflict
          </Button>
        </div>
      </div>
    </div>
  );
}

// CSS for animations
const styles = `
  @keyframes slide-up {
    from {
      transform: translateY(100%);
      opacity: 0;
    }
    to {
      transform: translateY(0);
      opacity: 1;
    }
  }

  .animate-slide-up {
    animation: slide-up 0.3s ease-out;
  }
`;

// Inject styles
if (typeof document !== 'undefined' && document !== null) {
  const styleSheet = document.createElement('style');
  styleSheet.innerText = styles;
  document.head.appendChild(styleSheet);
}

import { useRoutineStats } from '../api/domains/routine/hooks';

interface OralRoutineSummaryProps {
  className?: string;
}

export default function OralRoutineSummary({ className = '' }: OralRoutineSummaryProps): React.ReactElement {
  // Get current week
  const today = new Date();
  const startOfWeek = new Date(today);
  startOfWeek.setDate(today.getDate() - today.getDay());
  const endOfWeek = new Date(startOfWeek);
  endOfWeek.setDate(endOfWeek.getDate() + 6);

  const { data: stats, isLoading } = useRoutineStats({
    startDate: startOfWeek.toISOString(),
    endDate: endOfWeek.toISOString(),
  });

  if (isLoading) {
    return <div className={`animate-pulse bg-gray-100 rounded-lg h-24 ${className}`} />;
  }

  if (!stats || stats.totalRoutines === 0) {
    return (
      <div className={`bg-blue-50 rounded-lg p-4 border border-blue-200 ${className}`}>
        <div className="flex items-center gap-3">
          <span className="text-2xl">📢</span>
          <div>
            <h3 className="text-sm font-medium text-blue-900">Oral Routines</h3>
            <p className="text-xs text-blue-700">No routines scheduled this week</p>
          </div>
        </div>
      </div>
    );
  }

  const completionRate = Math.round((stats.completedRoutines / stats.totalRoutines) * 100);
  const participationDisplay = stats.averageEngagement
    ? `${Math.round(stats.averageEngagement * 100)}% avg`
    : 'No data';

  const getCompletionColor = (): string => {
    if (completionRate >= 80) {
return 'text-green-600';
}
    if (completionRate >= 60) {
return 'text-yellow-600';
}
    return 'text-red-600';
  };

  const getCompletionIcon = (): string => {
    if (completionRate >= 80) {
return '🔥';
}
    if (completionRate >= 60) {
return '👍';
}
    return '😐';
  };

  return (
    <div
      className={`bg-white rounded-lg p-4 border border-gray-200 hover:shadow-sm transition-shadow ${className}`}
    >
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <span className="text-2xl">📢</span>
          <div>
            <h3 className="text-sm font-medium text-gray-900">Oral Routines</h3>
            <p className="text-xs text-gray-600">This week&apos;s progress</p>
          </div>
        </div>
        <div className="text-right">
          <div className={`text-lg font-semibold ${getCompletionColor()} flex items-center gap-1`}>
            <span>{getCompletionIcon()}</span>
            <span>
              {stats.completedRoutines}/{stats.totalRoutines}
            </span>
          </div>
          <div className="text-xs text-gray-500">{participationDisplay}</div>
        </div>
      </div>

      {/* Progress bar */}
      <div className="mt-3">
        <div className="w-full bg-gray-200 rounded-full h-2">
          <div
            className={`h-2 rounded-full transition-all duration-300 ${
              completionRate >= 80
                ? 'bg-green-500'
                : completionRate >= 60
                  ? 'bg-yellow-500'
                  : 'bg-red-500'
            }`}
            style={{ width: `${completionRate}%` }}
          />
        </div>
        <div className="flex justify-between text-xs text-gray-500 mt-1">
          <span>0%</span>
          <span>{completionRate}% complete</span>
          <span>100%</span>
        </div>
      </div>
    </div>
  );
}

import React from 'react';
import { Navigate, useLocation } from 'react-router-dom';

import { useAuth } from '../contexts/AuthContext';
import logger from '../utils/logger';

interface ProtectedRouteProps {
  children: React.ReactNode;
}

export default function ProtectedRoute({ children }: ProtectedRouteProps): React.ReactElement {
  const { isAuthenticated, isLoading, isInitialized } = useAuth();
  const location = useLocation();

  // Debug logging in development
  if (process.env.NODE_ENV !== null && process.env.NODE_ENV !== undefined && process.env.NODE_ENV === 'development') {
    logger.info('[ProtectedRoute] Auth state:', {
      isAuthenticated,
      isLoading,
      isInitialized,
      currentPath: location.pathname,
    });
  }

  // Don't render anything until auth is initialized
  if (isInitialized !== null && isInitialized !== undefined && !isInitialized || isInitialized === null || isInitialized === undefined || isLoading !== null && isLoading !== undefined && isLoading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-blue-500" />
      </div>
    );
  }

  if (isAuthenticated !== null && isAuthenticated !== undefined && !isAuthenticated || isAuthenticated === null || isAuthenticated === undefined) {
    // Redirect them to the /login page, but save the current location they were
    // trying to go to when they were redirected. This allows us to send them
    // along to that page after they log in, which is a nicer user experience
    // than dropping them off on the home page.
    logger.info('[ProtectedRoute] Not authenticated, redirecting to login');
    return <Navigate replace state={{ from: location }} to="/login" />;
  }

  return <>{children}</>;
}

import { useState } from 'react';

import { useMediaResources } from '../api/domains/resource';
import type { MediaResource } from '../api/domains/resource/api';

import { Dialog } from './Dialog';

interface ResourceSelectorProps {
  userId: number;
  onSelect: (resource: MediaResource) => void;
  onClose: () => void;
  fileTypeFilter?: string;
  title?: string;
}

export default function ResourceSelector({
  userId,
  onSelect,
  onClose,
  fileTypeFilter,
  title = 'Select Resource',
}: ResourceSelectorProps): React.ReactElement {
  const [search, setSearch] = useState('');
  const [selectedFileType, setSelectedFileType] = useState(fileTypeFilter || '');

  const { data: mediaData, isLoading } = useMediaResources({ userId });
  const resources = mediaData?.resources ?? [];

  // Filter resources
  const filteredResources = resources.filter((resource) => {
    // File type filter
    if (selectedFileType && resource.type !== selectedFileType) {
      return false;
    }

    // Search filter
    if (search && !resource.title.toLowerCase().includes(search.toLowerCase())) {
      return false;
    }

    return true;
  });

  const getFileIcon = (fileType: string): string => {
    switch (fileType) {
      case 'image':
        return '🖼️';
      case 'pdf':
        return '📄';
      case 'video':
        return '🎥';
      case 'audio':
        return '🎵';
      default:
        return '📎';
    }
  };

  const formatFileSize = (bytes: number): string => {
    if (bytes === 0) {
return '0 Bytes';
}
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return `${parseFloat((bytes / Math.pow(k, i)).toFixed(2))  } ${  sizes[i]}`;
  };

  const getResourceUrl = (resource: MediaResource): string => resource.fileUrl || resource.thumbnailUrl || '/placeholder-image.png';

  return (
    <Dialog open onOpenChange={(open) => !open && onClose()}>
      <div className="w-full max-w-4xl max-h-[80vh] overflow-hidden flex flex-col">
        {/* Header */}
        <div className="flex justify-between items-center p-6 border-b">
          <h2 className="text-xl font-semibold">{title}</h2>
          <button className="text-gray-500 hover:text-gray-700" onClick={onClose}>
            ✕
          </button>
        </div>

        {/* Filters */}
        <div className="p-6 border-b bg-gray-50">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium mb-1">Search</label>
              <input
                className="w-full border rounded px-3 py-2"
                placeholder="Search resources..."
                type="text"
                value={search}
                onChange={(e) => {
 setSearch(e.target.value); 
}}
              />
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">File Type</label>
              <select
                className="w-full border rounded px-3 py-2"
                disabled={!!fileTypeFilter} // Disable if filtered from props
                value={selectedFileType}
                onChange={(e) => {
 setSelectedFileType(e.target.value); 
}}
              >
                <option value="">All Types</option>
                <option value="image">Images</option>
                <option value="pdf">PDFs</option>
                <option value="video">Videos</option>
                <option value="audio">Audio</option>
              </select>
            </div>
          </div>
        </div>

        {/* Resources List */}
        <div className="flex-1 overflow-y-auto p-6">
          {isLoading ? (
            <div className="text-center py-8">Loading resources...</div>
          ) : filteredResources.length === 0 ? (
            <div className="text-center py-8 text-gray-500">
              {resources.length === 0 ? 'No resources available' : 'No resources match your search'}
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {filteredResources.map((resource, _index) => (
                <div
                  key={resource.id}
                  className="border rounded-lg p-4 hover:shadow-md hover:bg-blue-50 cursor-pointer transition-all"
                  onClick={() => {
 onSelect(resource); 
}}
                >
                  {/* Thumbnail */}
                  <div className="w-full h-32 mb-3 flex items-center justify-center bg-gray-100 rounded">
                    {resource.type === 'image' ? (
                      <img
                        alt={resource.title}
                        className="w-full h-full object-cover rounded"
                        src={getResourceUrl(resource)}
                        onError={(e) => {
                          e.currentTarget.style.display = 'none';
                          e.currentTarget.nextElementSibling?.classList.remove('hidden');
                        }}
                      />
                    ) : null}
                    <div className={`text-4xl ${resource.type === 'image' ? 'hidden' : ''}`}>
                      {getFileIcon(resource.type)}
                    </div>
                  </div>

                  {/* Info */}
                  <h3 className="font-medium truncate mb-1">{resource.title}</h3>

                  <div className="text-sm text-gray-500 mb-2">
                    <div className="flex items-center gap-2">
                      <span className="capitalize">{resource.type}</span>
                      {resource.fileSize && (
                        <>
                          <span>•</span>
                          <span>{formatFileSize(resource.fileSize)}</span>
                        </>
                      )}
                    </div>
                  </div>

                  {/* Tags */}
                  {resource.tags.length > 0 && (
                    <div className="flex flex-wrap gap-1">
                      {resource.tags.slice(0, 2).map((tag, _index) => (
                        <span
                          key={tag}
                          className="px-2 py-1 bg-blue-100 text-blue-800 text-xs rounded"
                        >
                          {tag}
                        </span>
                      ))}
                      {resource.tags.length > 2 && (
                        <span className="text-xs text-gray-500">+{resource.tags.length - 2}</span>
                      )}
                    </div>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="p-6 border-t bg-gray-50">
          <div className="flex justify-between items-center">
            <div className="text-sm text-gray-600">
              {filteredResources.length} of {resources.length} resources
            </div>
            <button
              className="px-4 py-2 text-gray-600 border border-gray-300 rounded hover:bg-gray-50"
              onClick={onClose}
            >
              Cancel
            </button>
          </div>
        </div>
      </div>
    </Dialog>
  );
}

