import { useState, useEffect } from 'react';

import { sanitizeHtml } from '../utils/sanitization';

interface Props {
  value: string;
  onChange: (val: string) => void;
  placeholder?: string;
  className?: string;
}

export default function RichTextEditor({ 
  value, 
  onChange, 
  placeholder = "Start typing...",
  className = ""
}: Props): React.ReactElement {
  const [html, setHtml] = useState(value);

  useEffect(() => {
    return () => { // Cleanup
    };

    setHtml(value);
  }, [value]);

  const handleInput = (e: React.FormEvent<HTMLDivElement>): void => {
    const target = e.currentTarget;
    const rawHTML = target.innerHTML;

    // Sanitize the HTML to prevent XSS
    const sanitizedHTML = sanitizeHtml(rawHTML);

    // Only update if content actually changed to prevent cursor jumping
    if (sanitizedHTML !== html) {
      setHtml(sanitizedHTML);
      onChange(sanitizedHTML);

      // If we had to sanitize, update the display
      if (sanitizedHTML !== rawHTML) {
        target.innerHTML = sanitizedHTML;
      }
    }
  };

  const handlePaste = (e: React.ClipboardEvent<HTMLDivElement>): void => {
    e.preventDefault();

    // Get plain text from clipboard and insert it safely
    const text = e.clipboardData.getData('text/plain');
    // Properly escape HTML entities
    const sanitizedText = text
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;');

    // Insert the text at cursor position
    if (window.getSelection !== null && window.getSelection !== undefined) {
      const selection = window.getSelection();
      if (selection !== null && selection !== undefined && selection.getRangeAt !== null && selection.getRangeAt !== undefined && selection.rangeCount > 0) {
        const range = selection.getRangeAt(0);
        range.deleteContents();
        range.insertNode(document.createTextNode(sanitizedText));
        range.collapse(false);
        selection.removeAllRanges();
        selection.addRange(range);
      }
    }

    // Trigger change event by creating a proper FormEvent
    const divElement = e.currentTarget;
    const syntheticEvent = {
      ...e,
      currentTarget: divElement,
      target: divElement
    } as React.FormEvent<HTMLDivElement>;
    handleInput(syntheticEvent);
  };

  return (
    <div className={`relative ${className}`}>
      <div
        dangerouslySetInnerHTML={{ __html: sanitizeHtml(html) }}
        contentEditable
        aria-label="Rich text editor"
        aria-multiline="true"
        className="border border-gray-300 rounded-md p-3 min-h-[150px] focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none"
        data-placeholder={placeholder}
        role="textbox"
        style={{
          minHeight: '150px',
        }}
        suppressContentEditableWarning={true}
        onInput={handleInput}
        onPaste={handlePaste}
      />

      {/* Placeholder styling - using CSS-in-JS approach for safety */}
      <style>
        {`
          [contenteditable]:empty:before {
            content: attr(data-placeholder);
            color: #9ca3af;
            pointer-events: none;
          }
        `}
      </style>
    </div>
  );
}

import { useState, useEffect } from 'react';

import { substituteApi } from '../api/domains/substitute';

import { Dialog } from './Dialog';

interface Props {
  onClose: () => void;
}

export default function SubPlanGenerator({ onClose }: Props): React.ReactElement {
  const [date, setDate] = useState(() => new Date().toISOString().slice(0, 10));
  const [days, setDays] = useState(1);
  const [url, setUrl] = useState<string>();

  const generate = async (): Promise<void> => {
    const blob = await substituteApi.generateSubPlanPDF(date, days);

    // Clean up previous URL if it exists
    if (url) {
      URL.revokeObjectURL(url);
    }

    setUrl(URL.createObjectURL(blob));
  };

  // Clean up URL when component unmounts
  useEffect(() => () => {
      if (url) {
        URL.revokeObjectURL(url);
      }
    }, [url]);

  return (
    <Dialog open onOpenChange={onClose}>
      <div className="space-y-2 w-80">
        <h2 className="text-lg">Generate Sub Plan</h2>
        <input
          className="border p-1 w-full"
          type="date"
          value={date}
          onChange={(e) => {
 setDate(e.target.value); 
}}
        />
        <select
          className="border p-1 w-full"
          value={days}
          onChange={(e) => {
 setDays(Number(e.target.value)); 
}}
        >
          <option value={1}>1 day</option>
          <option value={2}>2 days</option>
          <option value={3}>3 days</option>
        </select>
        <button className="px-2 py-1 bg-blue-500 text-white rounded" onClick={() => {
 void generate(); 
}}>
          Generate
        </button>
        {url && <iframe className="w-full h-64 border" src={url} />}
      </div>
    </Dialog>
  );
}

import { useState } from 'react';

interface Props {
  tags: string[];
  onChange: (tags: string[]) => void;
  placeholder?: string;
}

export default function TagInput({ tags, onChange, placeholder }: Props): React.ReactElement {
  const [input, setInput] = useState('');

  const addTag = (): void => {
    const val = input.trim();
    if (val && !tags.includes(val)) {
      onChange([...tags, val]);
    }
    setInput('');
  };

  return (
    <div>
      <div className="flex flex-wrap gap-1">
        {tags.map((t, _index) => (
          <span key={t} className="px-1 bg-gray-200 text-sm flex items-center gap-1">
            {t}
            <button
              aria-label={`Remove ${t}`}
              type="button"
              onClick={() => {
 onChange(tags.filter((c) => c !== t)); 
}}
            >
              ×
            </button>
          </span>
        ))}
      </div>
      <input
        className="border p-1 mt-1"
        placeholder={placeholder}
        value={input}
        onChange={(e) => {
 setInput(e.target.value); 
}}
        onKeyDown={(e) => {
          if (e.key === 'Enter' || e.key === ',') {
            e.preventDefault();
            addTag();
          }
        }}
      />
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';

import { apiClient } from '../api/core/client';
import { useLanguage } from '../contexts/LanguageContext';
import logger from '../utils/logger';
import { safeJsonParse } from '../utils/typeGuards';

import LanguageSwitcher from './LanguageSwitcher';
import PreferenceWizard from './onboarding/PreferenceWizard';
import { Button } from './ui/Button';
import { Progress } from './ui/Progress';
interface OnboardingStep {
  id: string;
  title: string;
  description: string;
  content: React.ReactNode;
  action?: {
    label: string;
    onClick: () => void;
  };
}

interface TeacherOnboardingFlowProps {
  onComplete?: () => void;
}

export default function TeacherOnboardingFlow({ onComplete }: TeacherOnboardingFlowProps): React.ReactElement | null {
  const { t } = useLanguage();
  const navigate = useNavigate();

  // Initialize state with more stable logic to prevent flashing
  const [visible, setVisible] = useState(() => {
    try {
      const onboarded = localStorage.getItem('onboarded');
      // Default to false to not block the UI on initial load
      return onboarded === 'false'; // Only show if explicitly set to false
    } catch {
      return false; // Default to not showing
    }
  });

  const [currentStep, setCurrentStep] = useState(0);
  const [completedSteps, setCompletedSteps] = useState<string[]>(() => {
    try {
      const saved = localStorage.getItem('onboarding-completed-steps');
      return saved ? safeJsonParse(saved, []) : [];
    } catch {
      return [];
    }
  });
  const [isCreatingSampleData, setIsCreatingSampleData] = useState(false);

  // Define completeOnboarding first
  const completeOnboarding = useCallback((): void => {
    localStorage.setItem('onboarded', 'true');
    setVisible(false);
    onComplete?.();
  }, [onComplete]);

  // Save completed steps to localStorage with debouncing to prevent flashing
  useEffect(() => {
    return () => { // Cleanup
    };

    if (completedSteps.length > 0) {
      try {
        localStorage.setItem('onboarding-completed-steps', JSON.stringify(completedSteps));
      } catch (_error) {
        logger.warn('Failed to save onboarding progress:', _error);
      }
    }
  }, [completedSteps]);

  // Handle escape key to close wizard
  useEffect(() => {
    return () => { // Cleanup
    };

    if (!visible) {
return;
}

    const handleEscape = (event: KeyboardEvent): void => {
      if (event.key === 'Escape') {
        completeOnboarding();
      }
    };

    document.addEventListener('keydown', handleEscape);
    return () => {
      document.removeEventListener('keydown', handleEscape);
    };
  }, [visible, completeOnboarding]);

  const markStepCompleted = (stepId: string): void => {
    if (!completedSteps.includes(stepId)) {
      setCompletedSteps((prev) => [...prev, stepId]);
    }
  };

  const createSampleData = async (): Promise<void> => {
    setIsCreatingSampleData(true);
    try {
      // Create sample curriculum expectations
      await apiClient.post('/api/curriculum-expectations', {
        grade: '1',
        subject: 'Mathematics',
        strand: 'Number Sense',
        code: 'M1.NS.1',
        description:
          'demonstrate an understanding of numbers up to 20, including identifying number patterns and skip counting by 2s, 5s, and 10s',
        learningGoals: ['Count to 20', 'Identify patterns', 'Skip count'],
        successCriteria: [
          'I can count from 1 to 20',
          'I can find patterns in numbers',
          'I can skip count by 2s, 5s, and 10s',
        ],
        isSample: true,
      });

      await apiClient.post('/api/curriculum-expectations', {
        grade: '1',
        subject: 'Language Arts',
        strand: 'Reading',
        code: 'LA1.R.1',
        description: 'read simple texts with understanding, using various reading strategies',
        learningGoals: ['Read simple texts', 'Use reading strategies', 'Demonstrate comprehension'],
        successCriteria: [
          'I can read grade-level texts',
          'I can use different strategies when reading',
          'I can answer questions about what I read',
        ],
        isSample: true,
      });

      // Create sample long-range plan
      const _longRangePlan = await apiClient.post('/api/long-range-plans', {
        title: 'Grade 1 Fall Term Sample Plan',
        description: 'A sample long-range plan for Grade 1 covering September to December',
        startDate: new Date('2024-09-01').toISOString(),
        endDate: new Date('2024-12-20').toISOString(),
        grade: '1',
        isSample: true,
      });

      markStepCompleted('sample-data');
    } catch (_error) {
      logger.error('Error creating sample data:', _error);
    } finally {
      setIsCreatingSampleData(false);
    }
  };

