  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-lg shadow-xl max-w-4xl w-full max-h-[90vh] overflow-y-auto">
        {/* Header */}
        <div className="border-b border-gray-200 p-6">
          <div className="flex items-center justify-between mb-4">
            <div className="flex-1">
              <h2 className="text-2xl font-bold text-gray-900">{currentStepData.title}</h2>
              <p className="text-gray-600 mt-1">{currentStepData.description}</p>
            </div>
            <div className="flex items-center space-x-3">
              <LanguageSwitcher />
              <Button
                className="text-gray-500 hover:text-gray-700"
                size="sm"
                variant="outline"
                onClick={completeOnboarding}
              >
                {t('skip_tour', 'Skip Tour')}
              </Button>
            </div>
          </div>

          {/* Progress bar */}
          <div className="space-y-2">
            <div className="flex justify-between text-sm text-gray-500">
              <span>
                {t('step_x_of_y', 'Step {0} of {1}', [
                  (currentStep + 1).toString(),
                  steps.length.toString(),
                ])}
              </span>
              <span>
                {t('percent_complete', '{0}% complete', [Math.round(progress).toString()])}
              </span>
            </div>
            <Progress className="h-2" value={progress} />
          </div>

          {/* Step indicators */}
          <div className="flex justify-center space-x-2 mt-4">
            {steps.map((step, index) => (
              <button
                key={step.id}
                className={`w-3 h-3 rounded-full transition-colors ${
                  index === currentStep
                    ? 'bg-indigo-600'
                    : index < currentStep
                      ? 'bg-green-500'
                      : 'bg-gray-300'
                }`}
                title={step.title}
                onClick={() => {
 skipToStep(index); 
}}
              />
            ))}
          </div>
        </div>

        {/* Content */}
        <div className="p-6">{currentStepData.content}</div>

        {/* Actions */}
        <div className="border-t border-gray-200 p-6 flex justify-between items-center">
          <Button aria-label="Click button" onClick={previousStep}>
            {t('previous', 'Previous')}
          </Button>

          <div className="flex items-center space-x-3">
            {currentStepData.action ? (
              <Button
                className="min-w-[120px]"
                disabled={isCreatingSampleData}
                onClick={currentStepData.action.onClick}
              >
                {isCreatingSampleData ? (
                  <div className="flex items-center space-x-2">
                    <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                    <span>{t('loading', 'Loading...')}</span>
                  </div>
                ) : (
                  currentStepData.action.label
                )}
              </Button>
            ) : (
              currentStep < steps.length - 1 && (
                <Button aria-label="Click button" onClick={nextStep}>
                  {t('next', 'Next')}
                </Button>
              )
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

