import { LockIcon, AlertCircle, CheckCircle } from 'lucide-react';
import React, { useEffect, useState } from 'react';

import { useWorkflowState, ETFOLevel, ETFO_LEVEL_PATHS } from '../hooks/useWorkflowState';

import { Alert, AlertDescription, AlertTitle } from './ui/alert';
import { Button } from './ui/Button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from './ui/card';
import { useToast } from './ui/use-toast';

interface WorkflowGateProps {
  level: ETFOLevel;
  children: React.ReactNode;
}

export default function WorkflowGate({ level, children }: WorkflowGateProps): React.ReactElement {
  const { workflowState, isLevelAccessible, getBlockedReason, getLevelProgress, getPreviousLevel } =
    useWorkflowState();
  const { toast } = useToast();
  const [isChecking, setIsChecking] = useState(true);

  useEffect(() => {
    return () => { // Cleanup
    };

    if (workflowState) {
      setIsChecking(false);

      // Show toast if blocked
      if (!isLevelAccessible(level)) {
        const blockedReason = getBlockedReason(level);
        toast({
          title: 'Access Restricted',
          description: blockedReason ?? 'You must complete previous levels first',
          variant: 'destructive',
        });
      }
    }
  }, [workflowState, level, isLevelAccessible, getBlockedReason, toast]);

  if (isChecking) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-blue-500" />
      </div>
    );
  }

  // If level is accessible, render children
  if (isLevelAccessible(level)) {
    return <>{children}</>;
  }

  // Otherwise, show blocked message
  const blockedReason = getBlockedReason(level);
  const previousLevel = getPreviousLevel(level);
  const previousLevelProgress = (previousLevel != null) ? getLevelProgress(previousLevel) : null;

  return (
    <div className="container mx-auto py-8 max-w-2xl">
      <Card>
        <CardHeader>
          <div className="flex items-center gap-3">
            <LockIcon className="h-8 w-8 text-muted-foreground" />
            <div>
              <CardTitle>Access Restricted</CardTitle>
              <CardDescription>This planning level is not yet available</CardDescription>
            </div>
          </div>
        </CardHeader>
        <CardContent className="space-y-4">
          <Alert>
            <AlertCircle className="h-4 w-4" />
            <AlertTitle>Why is this locked?</AlertTitle>
            <AlertDescription>
              {blockedReason ||
                'You must complete the previous planning levels before accessing this one.'}
            </AlertDescription>
          </Alert>

          {(previousLevel != null) && previousLevelProgress && (
            <div className="space-y-3">
              <h3 className="font-semibold">Previous Level Progress</h3>
              <div className="bg-muted rounded-lg p-4 space-y-2">
                <div className="flex items-center justify-between">
                  <span className="font-medium">{getLevelName(previousLevel)}</span>
                  <span className="text-sm text-muted-foreground">
                    {previousLevelProgress.completedItems} / {previousLevelProgress.totalItems}{' '}
                    completed
                  </span>
                </div>
                <div className="w-full bg-secondary rounded-full h-2">
                  <div
                    className="bg-primary h-2 rounded-full transition-all duration-300"
                    style={{ width: `${previousLevelProgress.progressPercentage}%` }}
                  />
                </div>
                {previousLevelProgress.isComplete ? (
                  <div className="flex items-center gap-2 text-green-600">
                    <CheckCircle className="h-4 w-4" />
                    <span className="text-sm">Completed!</span>
                  </div>
                ) : (
                  <p className="text-sm text-muted-foreground">
                    Complete this level to unlock {getLevelName(level)}
                  </p>
                )}
              </div>
            </div>
          )}

          <div className="space-y-3">
            <h3 className="font-semibold">How to Unlock</h3>
            <ol className="list-decimal list-inside space-y-2 text-sm">
              {getUnlockSteps(level).map((step, _index) => (
                <li key={_index} className="text-muted-foreground">
                  {step}
                </li>
              ))}
            </ol>
          </div>

          <div className="flex gap-3">
            {(previousLevel != null) && (
              <Button
                className="flex-1"
                onClick={() => (window.location.href = ETFO_LEVEL_PATHS[previousLevel])}
              >
                Go to {getLevelName(previousLevel)}
              </Button>
            )}
            <Button
              className="flex-1"
              variant="outline"
              onClick={() => (window.location.href = '/')}
            >
              Back to Dashboard
            </Button>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

function getLevelName(level: ETFOLevel): string {
  const names = {
    [ETFOLevel.CURRICULUM_EXPECTATIONS]: 'Curriculum Expectations',
    [ETFOLevel.LONG_RANGE_PLANS]: 'Long-Range Plans',
    [ETFOLevel.UNIT_PLANS]: 'Unit Plans',
    [ETFOLevel.LESSON_PLANS]: 'Lesson Plans',
    [ETFOLevel.DAYBOOK_ENTRIES]: 'Daybook Entries',
  };
  return names[level] || level;
}

function getUnlockSteps(level: ETFOLevel): string[] {
  const steps = {
    [ETFOLevel.CURRICULUM_EXPECTATIONS]: [
      'This is the first level and is always accessible',
      'Import curriculum expectations to get started',
    ],
    [ETFOLevel.LONG_RANGE_PLANS]: [
      'Import at least one curriculum expectation',
      'Navigate to Curriculum Expectations',
      'Click "Import Curriculum" to add expectations',
    ],
    [ETFOLevel.UNIT_PLANS]: [
      'Create at least one long-range plan',
      'Add goals to your long-range plan',
      'Save the plan with all required fields',
    ],
    [ETFOLevel.LESSON_PLANS]: [
      'Create at least one unit plan',
      'Add big ideas to your unit plan',
      'Link curriculum expectations to the unit',
      'Save the unit plan with all required fields',
    ],
    [ETFOLevel.DAYBOOK_ENTRIES]: [
      'Create at least one lesson plan',
      'Add learning goals and materials',
      'Define activities for the lesson',
      'Save the lesson plan with all required fields',
    ],
  };
  return steps[level] || ['Complete the previous planning level'];
}

import { AlertTriangle, RefreshCw, FileText, Wifi, Settings } from 'lucide-react';
import type { ReactNode } from 'react';
import React, { Component } from 'react';

import { cn } from '../../lib/utils';
import logger from '../../utils/logger';
import { Alert, AlertDescription } from '../ui/alert';
import { Button } from '../ui/Button';
interface Props {
  children: ReactNode;
  fallback?: ReactNode;
  onRetry?: () => void;
  enableManualFallback?: boolean;
}

interface State {
  hasError: boolean;
  error?: Error;
  errorInfo?: React.ErrorInfo;
  retryCount: number;
}

// Common AI-related error types
export enum AIErrorType {
  API_KEY_MISSING = 'API_KEY_MISSING',
  API_RATE_LIMIT = 'API_RATE_LIMIT',
  API_UNAVAILABLE = 'API_UNAVAILABLE',
  NETWORK_ERROR = 'NETWORK_ERROR',
  TIMEOUT = 'TIMEOUT',
  INVALID_RESPONSE = 'INVALID_RESPONSE',
  QUOTA_EXCEEDED = 'QUOTA_EXCEEDED',
  UNKNOWN = 'UNKNOWN',
}

interface AIError extends Error {
  type?: AIErrorType;
  statusCode?: number;
  retryable?: boolean;
  suggestedAction?: string;
}

export class AIErrorBoundary extends Component<Props, State> {
  private maxRetries = 3;
  private retryTimeout?: NodeJS.Timeout;

  constructor(props: Props) {
    super(props);
    this.state = { 
      hasError: false, 
      retryCount: 0 
    };
  }

  static getDerivedStateFromError(error: Error): Partial<State> {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: React.ErrorInfo): void {
    this.setState({ errorInfo });

    // Log AI-specific errors with context
    logger.error('=== AI ERROR BOUNDARY ===');
    logger.error(`Error: ${error.name} - ${(error instanceof Error ? error.message : String(error))}`);
    logger.error('Stack:', error.stack);
    logger.error('Component Stack:', errorInfo.componentStack);
    logger.error('Retry Count:', this.state.retryCount);
    logger.error('========================');

    // Report to monitoring service if available
    if (window.gtag !== undefined) {
      window.gtag('event', 'ai_error', {
        event_category: 'AI Integration',
        event_label: (error instanceof Error ? error.message : String(error)),
        value: this.state.retryCount,
      });
    }
  }

  private classifyError(error: Error): AIError {
    const message = (error instanceof Error ? error.message : String(error)).toLowerCase();
    let type = AIErrorType.UNKNOWN;
    let retryable = false;
    let suggestedAction = 'Something unexpected happened with the AI assistant. You can try again or continue creating your lesson manually. Your work is automatically saved.';

    if (message.includes('api key') || message.includes('unauthorized')) {
      type = AIErrorType.API_KEY_MISSING;
      suggestedAction = 'AI features need setup. Ask your school\'s IT admin to configure AI settings, or continue creating your lesson manually. Your work will be saved automatically.';
    } else if (message.includes('rate limit') || message.includes('too many requests')) {
      type = AIErrorType.API_RATE_LIMIT;
      retryable = true;
      suggestedAction = 'AI is busy right now. Try again in a few minutes, or continue working manually. Your progress is saved automatically.';
    } else if (message.includes('timeout') || message.includes('timed out')) {
      type = AIErrorType.TIMEOUT;
      retryable = true;
      suggestedAction = 'AI is taking longer than usual. Check your internet connection and try again, or continue creating your lesson manually.';
    } else if (message.includes('network') || message.includes('fetch')) {
      type = AIErrorType.NETWORK_ERROR;
      retryable = true;
      suggestedAction = 'Connection issue detected. Check your internet connection and try again. You can continue working manually while we resolve this.';
    } else if (message.includes('quota') || message.includes('billing')) {
      type = AIErrorType.QUOTA_EXCEEDED;
      suggestedAction = 'AI usage limit reached for this month. Contact your school\'s IT admin about increasing the limit, or continue creating lessons manually.';
    } else if (message.includes('unavailable') || message.includes('service')) {
      type = AIErrorType.API_UNAVAILABLE;
      retryable = true;
      suggestedAction = 'AI assistant is temporarily down for maintenance. Try again in a few minutes or continue working manually. Your content will be saved.';
    } else if (message.includes('invalid') || message.includes('malformed')) {
      type = AIErrorType.INVALID_RESPONSE;
      suggestedAction = 'AI generated an unexpected response. Please try again or continue creating your lesson manually. Your work is automatically saved.';
    }

    return {
      ...error,
      type,
      retryable,
      suggestedAction,
    } as AIError;
  }

  private handleRetry = (): void => {
    if (this.state.retryCount >= this.maxRetries) {
      return;
    }

    this.setState(prevState => ({
      hasError: false,
      error: undefined,
      errorInfo: undefined,
      retryCount: prevState.retryCount + 1,
    }));

    // Call external retry handler if provided
    if (this.props.onRetry !== undefined) {
      this.props.onRetry();
    }

    // Auto-retry with exponential backoff for retryable errors
    if (this.state.error) {
      const aiError = this.classifyError(this.state.error);
      if (aiError.retryable === true) {
      const delay = Math.pow(2, this.state.retryCount) * 1000; // 1s, 2s, 4s
      this.retryTimeout = setTimeout(() => {
        // Force re-render to trigger retry
        this.forceUpdate();
        }, delay);
      }
    }
  };

  private handleManualFallback = (): void => {
    // Switch to manual mode - hide AI features
    this.setState({
      hasError: false,
      error: undefined,
      errorInfo: undefined,
    });

    // Store preference to disable AI for this session
    sessionStorage.setItem('ai_disabled', 'true');

    // Reload the page to apply changes
    window.location.reload();
  };

  componentWillUnmount(): void {
    if (this.retryTimeout !== undefined) {
      clearTimeout(this.retryTimeout);
    }
  }

  private getErrorIcon(type: AIErrorType): React.ReactElement {
    switch (type) {
      case AIErrorType.API_KEY_MISSING:
        return <Settings className="h-6 w-6" />;
      case AIErrorType.NETWORK_ERROR:
      case AIErrorType.API_UNAVAILABLE:
        return <Wifi className="h-6 w-6" />;
      case AIErrorType.QUOTA_EXCEEDED:
      case AIErrorType.API_RATE_LIMIT:
        return <AlertTriangle className="h-6 w-6" />;
      default:
        return <AlertTriangle className="h-6 w-6" />;
    }
  }

  private getErrorSeverity(type: AIErrorType): 'error' | 'warning' | 'info' {
    switch (type) {
      case AIErrorType.API_KEY_MISSING:
      case AIErrorType.QUOTA_EXCEEDED:
        return 'error';
      case AIErrorType.API_RATE_LIMIT:
      case AIErrorType.TIMEOUT:
        return 'warning';
      default:
        return 'error';
    }
  }

  render(): React.ReactNode {
    if (this.state.hasError && this.state.error) {
      if (this.props.fallback !== undefined && this.props.fallback !== null) {
        return this.props.fallback;
      }

      const aiError = this.classifyError(this.state.error);
      const canRetry = this.state.retryCount < this.maxRetries;
      const severity = this.getErrorSeverity(aiError.type ?? AIErrorType.UNKNOWN);

      return (
        <div className="min-h-[200px] flex items-center justify-center p-6">
          <div className="max-w-md w-full">
            <Alert className={cn({
              'border-red-200 bg-red-50': severity === 'error',
              'border-yellow-200 bg-yellow-50': severity === 'warning',
              'border-blue-200 bg-blue-50': severity === 'info',
            })}>
              <div className={cn('flex items-start gap-3', {
                'text-red-600': severity === 'error',
                'text-yellow-600': severity === 'warning',
                'text-blue-600': severity === 'info',
              })}>
                {this.getErrorIcon(aiError.type ?? AIErrorType.UNKNOWN)}
                <div className="flex-1">
                  <h3 
                    className="font-semibold mb-2"
                    id="ai-error-title"
                  >
                    AI Assistant Unavailable
                  </h3>
                  <AlertDescription 
                    aria-live="polite"
                    className="mb-4"
                    id="ai-error-description"
                    role="alert"
                  >
                    {aiError.suggestedAction}
                  </AlertDescription>

                  {/* Retry Information */}
                  {this.state.retryCount > 0 && (
                    <p className="text-sm text-gray-600 mb-3">
                      Retry attempt {this.state.retryCount} of {this.maxRetries}
                    </p>
                  )}

                  {/* Action Buttons */}
                  <div 
                    aria-describedby="ai-error-description"
                    aria-labelledby="ai-error-title"
                    className="flex flex-wrap gap-2"
                    role="group"
                  >
                    {canRetry && aiError.retryable === true && (
                      <Button
                        aria-label="Retry AI generation"
                        className="gap-2"
                        size="sm"
                        variant="outline"
                        onClick={this.handleRetry}
                      >
                        <RefreshCw aria-hidden="true" className="h-4 w-4" />
                        Retry
                      </Button>
                    )}

                    {this.props.enableManualFallback === true && (
                      <Button
                        aria-label="Continue creating content manually without AI assistance"
                        className="gap-2"
                        size="sm"
                        variant="outline"
                        onClick={this.handleManualFallback}
                      >
                        <FileText aria-hidden="true" className="h-4 w-4" />
                        Continue Manually
                      </Button>
                    )}

                    {aiError.type === AIErrorType.API_KEY_MISSING && (
                      <Button
                        className="gap-2"
                        size="sm"
                        onClick={() => window.open('/settings', '_blank')}
                      >
                        <Settings className="h-4 w-4" />
                        Open Settings
                      </Button>
                    )}
                  </div>

                  {/* Technical Details (Development) */}
                  {process.env.NODE_ENV === 'development' && (
                    <details className="mt-4">
                      <summary className="cursor-pointer text-sm font-medium">
                        Technical Details
                      </summary>
                      <div className="mt-2 p-2 bg-gray-100 rounded text-xs font-mono">
                        <div><strong>Type:</strong> {aiError.type}</div>
                        <div><strong>Message:</strong> {this.state.error instanceof Error ? this.state.error.message : String(this.state.error)}</div>
                        {aiError.statusCode !== undefined && (
                          <div><strong>Status:</strong> {aiError.statusCode}</div>
                        )}
                        <div><strong>Retryable:</strong> {aiError.retryable === true ? 'Yes' : 'No'}</div>
                        {this.state.errorInfo !== undefined && (
                          <details className="mt-2">
                            <summary>Component Stack</summary>
                            <pre className="whitespace-pre-wrap text-xs mt-1">
                              {this.state.errorInfo.componentStack}
                            </pre>
                          </details>
                        )}
                      </div>
                    </details>
                  )}
                </div>
              </div>
            </Alert>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

// Hook for handling AI errors in functional components
export function useAIErrorHandler(): { handleAIError: (error: unknown, context?: string) => void } {
  const handleAIError = (error: unknown, context?: string): void => {
    logger.error(`AI Error${context !== undefined && context !== '' ? ` in ${context}` : ''}:`, error);

    // Report to monitoring
    if (window.gtag !== undefined) {
      window.gtag('event', 'ai_error', {
        event_category: 'AI Integration',
        event_label: context !== undefined && context !== '' ? context : 'Unknown',
        value: 1,
      });
    }
  };

  return { handleAIError };
}

// Utility function to check if an error is AI-related
export function isAIError(error: unknown): error is AIError {
  if (!(error instanceof Error)) {
return false;
}

  const message = (error instanceof Error ? error.message : String(error)).toLowerCase();
  return (
    message.includes('openai') ||
    message.includes('api key') ||
    message.includes('gpt') ||
    message.includes('ai') ||
    message.includes('model') ||
    message.includes('completion')
  );
}

// Component wrapper for automatic AI error handling
interface WithAIErrorBoundaryProps {
  children: ReactNode;
  onRetry?: () => void;
  enableManualFallback?: boolean;
}

export function WithAIErrorBoundary({
  children,
  onRetry,
  enableManualFallback = true,
}: WithAIErrorBoundaryProps): React.ReactElement {
  return (
    <AIErrorBoundary enableManualFallback={enableManualFallback} onRetry={onRetry}>
      {children}
    </AIErrorBoundary>
  );
}

