import { 
  Sparkles, 
  RefreshCw, 
  Copy, 
  Check, 
  Plus, 
  BookOpen, 
  Target, 
  Lightbulb,
  CheckCircle,
  AlertCircle,
  Clock
} from 'lucide-react';
import React, { useState, useCallback } from 'react';

import { useAIPlanningAssistant } from '../../hooks/useAIPlanningAssistant';
import { useAIStatus, useAIFeature } from '../../hooks/useAIStatus';
import logger from '../../utils/logger';
import { getErrorMessage } from "../../utils/typeGuards";
import { Badge } from '../ui/Badge';
import { Button } from '../ui/Button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '../ui/card';
import { Input } from '../ui/Input';
import { Label } from '../ui/Label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '../ui/select';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '../ui/tabs';
import { Textarea } from '../ui/Textarea';
import { useToast } from '../ui/use-toast';

import { WithAIErrorBoundary } from './AIErrorBoundary';
import { AILoadingIndicator, AI_LOADING_PRESETS } from './AILoadingIndicator';

interface UnitPlanSuggestion {
  type: 'bigIdeas' | 'learningGoals' | 'activities' | 'assessments' | 'materials' | 'vocabulary';
  content: string[];
  rationale?: string;
}

interface AIUnitPlanPanelProps {
  unitTitle?: string;
  subject?: string;
  grade?: number;
  duration?: number;
  curriculumExpectations?: {
    id: string;
    code: string;
    description: string;
    strand: string;
  }[];
  onSuggestionAccepted?: (type: string, content: string[]) => void;
  onUnitGenerated?: (unitPlan: {
    title: string;
    subject: string;
    grade: number;
    duration: number;
    bigIdeas: string[];
    learningGoals: string[];
    focusAreas: string[];
    generatedAt: Date;
  }) => void;
  className?: string;
}

export function AIUnitPlanPanel({
  unitTitle = '',
  subject = '',
  grade = 1,
  duration = 2,
  curriculumExpectations = [],
  onSuggestionAccepted,
  onUnitGenerated,
  className = '',
}: AIUnitPlanPanelProps): React.ReactElement {
  const { toast } = useToast();
  const { canUseAI, aiDisabledReason } = useAIStatus();
  const { available: _planGenerationAvailable } = useAIFeature('planGeneration');

  // Local state for form inputs
  const [formData, setFormData] = useState({
    unitTitle,
    subject,
    grade: grade.toString(),
    duration: duration.toString(),
    focusAreas: [] as string[],
    teachingApproach: 'balanced' as 'inquiry' | 'direct' | 'balanced',
    additionalContext: '',
  });

  // AI suggestion states
  const [suggestions, setSuggestions] = useState<UnitPlanSuggestion[]>([]);
  const [acceptedSuggestions, setAcceptedSuggestions] = useState<Set<string>>(new Set());
  const [isGenerating, setIsGenerating] = useState(false);
  const [activeTab, setActiveTab] = useState('input');
  const [showLoadingModal, setShowLoadingModal] = useState(false);
  const [loadingStep, setLoadingStep] = useState('');

  // AI hooks
  const { generateUnitBigIdeas } = useAIPlanningAssistant();

  const handleInputChange = (field: string, value: string | string[]): void => {
    setFormData(prev => ({
      ...prev,
      [field]: value,
    }));
  };

  const addFocusArea = (): void => {
    const newArea = (document.getElementById('newFocusArea') as HTMLInputElement).value.trim();
    if (newArea && !formData.focusAreas.includes(newArea)) {
      handleInputChange('focusAreas', [...formData.focusAreas, newArea]);
      (document.getElementById('newFocusArea') as HTMLInputElement).value = '';
    }
  };

  const removeFocusArea = (area: string): void => {
    handleInputChange('focusAreas', formData.focusAreas.filter(a => a !== area));
  };

  const generateSuggestions = useCallback(async (type: UnitPlanSuggestion['type']): Promise<void> => {
    if (!canUseAI) {
      toast({
        title: 'AI Unavailable',
        description: aiDisabledReason !== null && aiDisabledReason !== undefined && aiDisabledReason !== '' ? aiDisabledReason : 'AI features are currently unavailable.',
        variant: 'destructive',
      });
      return;
    }

    if (!formData.unitTitle || !formData.subject) {
      toast({
        title: 'Missing Information',
        description: 'Please provide a unit title and subject before generating suggestions.',
        variant: 'destructive',
      });
      return;
    }

    setIsGenerating(true);
    setShowLoadingModal(true);
    setLoadingStep('analyze');

    try {
      let result: { suggestions: string[]; rationale?: string };

      switch (type) {
        case 'bigIdeas':
          result = await generateUnitBigIdeas.mutateAsync({
            unitTitle: formData.unitTitle,
            subject: formData.subject,
            grade: parseInt(formData.grade),
            curriculumExpectations: curriculumExpectations.map(exp => exp.description),
            duration: parseInt(formData.duration),
          });
          break;
        // Add other types as needed
        default:
          throw new Error(`Suggestion type ${type} not implemented`);
      }

      setSuggestions(prev => [
        ...prev.filter(s => s.type !== type),
        {
          type,
          content: result.suggestions,
          rationale: result.rationale ?? '',
        }
      ]);

      setActiveTab('suggestions');

      toast({
        title: 'Suggestions Generated',
        description: `Generated ${result.suggestions.length} ${type} suggestions.`,
      });

    } catch (_error) {
      logger.error('Error generating suggestions:', _error);
      toast({
        title: 'Generation Failed',
        description: getErrorMessage(_error) || 'Failed to generate suggestions. Please try again.',
        variant: 'destructive',
      });
    } finally {
      setIsGenerating(false);
      setShowLoadingModal(false);
    }
  }, [formData, curriculumExpectations, canUseAI, aiDisabledReason, generateUnitBigIdeas, toast]);

  const generateCompleteUnit = useCallback(async (): Promise<void> => {
    if (!canUseAI) {
      toast({
        title: 'AI Unavailable',
        description: aiDisabledReason !== null && aiDisabledReason !== undefined && aiDisabledReason !== '' ? aiDisabledReason : 'AI features are currently unavailable.',
        variant: 'destructive',
      });
      return;
    }

    setIsGenerating(true);
    setShowLoadingModal(true);

    try {
      // Generate all components sequentially
      const {steps} = AI_LOADING_PRESETS.GENERATING_UNIT_PLAN;

      for (let i = 0; i < steps.length; i++) {
        setLoadingStep(steps[i].id);

        switch (steps[i].id) {
          case 'analyze':
            // Analyze curriculum expectations
            await new Promise(resolve => setTimeout(resolve, 1000));
            break;
          case 'generate':
            // Generate big ideas
            await generateSuggestions('bigIdeas');
            break;
          case 'structure':
            // Generate learning goals and activities
            await generateSuggestions('learningGoals');
            await generateSuggestions('activities');
            break;
          case 'finalize':
            // Generate assessments and materials
            await generateSuggestions('assessments');
            await generateSuggestions('materials');
            break;
        }
      }

      // Construct complete unit plan
      const unitPlan = {
        title: formData.unitTitle,
        subject: formData.subject,
        grade: parseInt(formData.grade),
        duration: parseInt(formData.duration),
        focusAreas: formData.focusAreas,
        teachingApproach: formData.teachingApproach,
        curriculumExpectations,
        bigIdeas: suggestions.find(s => s.type === 'bigIdeas')?.content ?? [],
        learningGoals: suggestions.find(s => s.type === 'learningGoals')?.content ?? [],
        activities: suggestions.find(s => s.type === 'activities')?.content ?? [],
        assessments: suggestions.find(s => s.type === 'assessments')?.content ?? [],
        materials: suggestions.find(s => s.type === 'materials')?.content ?? [],
        generatedAt: new Date(),
      };

      if (onUnitGenerated) {
        onUnitGenerated(unitPlan);
      }

      toast({
        title: 'Unit Plan Generated',
        description: 'Complete unit plan has been generated successfully.',
      });

      setActiveTab('review');

    } catch (_error) {
      logger.error('Error generating complete unit:', _error);
      toast({
        title: 'Generation Failed',
        description: getErrorMessage(_error) || 'Failed to generate complete unit plan.',
        variant: 'destructive',
      });
    } finally {
      setIsGenerating(false);
      setShowLoadingModal(false);
    }
  }, [formData, curriculumExpectations, suggestions, canUseAI, aiDisabledReason, generateSuggestions, onUnitGenerated, toast]);

  const acceptSuggestion = (suggestionType: string, content: string): void => {
    const key = `${suggestionType}-${content}`;
    setAcceptedSuggestions(prev => new Set([...prev, key]));

    if (onSuggestionAccepted) {
      onSuggestionAccepted(suggestionType, [content]);
    }

    toast({
      title: 'Suggestion Accepted',
      description: 'The suggestion has been added to your unit plan.',
    });
  };

  const copySuggestion = (content: string): void => {
    void navigator.clipboard.writeText(content);
    toast({
      title: 'Copied',
      description: 'Suggestion copied to clipboard.',
    });
  };

  if (!canUseAI) {
    return (
      <Card className={className}>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Sparkles className="h-5 w-5 text-gray-400" />
            AI Unit Plan Assistant
          </CardTitle>
          <CardDescription>
            AI features are currently unavailable. {aiDisabledReason}
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="text-center py-8 text-gray-500">
            <AlertCircle className="h-8 w-8 mx-auto mb-2" />
            <p>Continue creating your unit plan manually using the form fields above.</p>
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <WithAIErrorBoundary>
      <Card className={className}>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Sparkles className="h-5 w-5 text-purple-500" />
            AI Unit Plan Assistant
          </CardTitle>
          <CardDescription>
            Generate comprehensive unit plans with AI assistance
          </CardDescription>
        </CardHeader>
        <CardContent>
          <Tabs className="w-full" value={activeTab} onValueChange={setActiveTab}>
            <TabsList className="grid w-full grid-cols-3">
              <TabsTrigger value="input">Setup</TabsTrigger>
              <TabsTrigger value="suggestions">Suggestions</TabsTrigger>
              <TabsTrigger value="review">Review</TabsTrigger>
            </TabsList>

            <TabsContent className="space-y-4" value="input">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label htmlFor="unitTitle">Unit Title</Label>
                  <Input
                    id="unitTitle"
                    placeholder="e.g., Forces and Motion"
                    value={formData.unitTitle}
                    onChange={(e) => {
 handleInputChange('unitTitle', e.target.value); 
}}
                  />
                </div>
                <div>
                  <Label htmlFor="subject">Subject</Label>
                  <Select value={formData.subject} onValueChange={(value) => {
 handleInputChange('subject', value); 
}}>
                    <SelectTrigger>
                      <SelectValue placeholder="Select subject" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="Science">Science</SelectItem>
                      <SelectItem value="Mathematics">Mathematics</SelectItem>
                      <SelectItem value="Language Arts">Language Arts</SelectItem>
                      <SelectItem value="Social Studies">Social Studies</SelectItem>
                      <SelectItem value="French">French</SelectItem>
                      <SelectItem value="Health and Physical Education">Health and Physical Education</SelectItem>
                      <SelectItem value="The Arts">The Arts</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label htmlFor="grade">Grade</Label>
                  <Select value={formData.grade} onValueChange={(value) => {
 handleInputChange('grade', value); 
}}>
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {[1, 2, 3, 4, 5, 6, 7, 8].map(grade => (
                        <SelectItem key={grade} value={grade.toString()}>Grade {grade}</SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div>
                  <Label htmlFor="duration">Duration (weeks)</Label>
                  <Input
                    id="duration"
                    max="20"
                    min="1"
                    type="number"
                    value={formData.duration}
                    onChange={(e) => {
 handleInputChange('duration', e.target.value); 
}}
                  />
                </div>
              </div>

              <div>
                <Label htmlFor="teachingApproach">Teaching Approach</Label>
                <Select 
                  value={formData.teachingApproach} 
                  onValueChange={(value: 'inquiry' | 'direct' | 'balanced') => {
 handleInputChange('teachingApproach', value); 
}}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="inquiry">Inquiry-Based Learning</SelectItem>
                    <SelectItem value="direct">Direct Instruction</SelectItem>
                    <SelectItem value="balanced">Balanced Approach</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              <div>
                <Label htmlFor="focusAreas">Focus Areas</Label>
                <div className="flex gap-2 mb-2">
                  <Input
                    id="newFocusArea"
                    placeholder="Add focus area (e.g., Scientific Method)"
                    onKeyPress={(e) => e.key === 'Enter' && addFocusArea()}
                  />
                  <Button aria-label="Click button" onClick={addFocusArea}>
                    <Plus className="h-4 w-4" />
                  </Button>
                </div>
                <div className="flex flex-wrap gap-2">
                  {formData.focusAreas.map((area, index) => (
                    <Badge key={index} className="gap-1" variant="secondary">
                      {area}
                      <button
                        className="text-xs hover:text-red-500"
                        onClick={() => {
 removeFocusArea(area); 
}}
                      >
                        ×
                      </button>
                    </Badge>
                  ))}
                </div>
              </div>

              <div>
                <Label htmlFor="additionalContext">Additional Context</Label>
                <Textarea
                  id="additionalContext"
                  placeholder="Any additional context, special considerations, or requirements..."
                  rows={3}
                  value={formData.additionalContext}
                  onChange={(e) => {
 handleInputChange('additionalContext', e.target.value); 
}}
                />
              </div>

              {curriculumExpectations.length > 0 && (
                <div>
                  <Label htmlFor="input">Curriculum Expectations ({curriculumExpectations.length})</Label>
                  <div className="mt-2 space-y-1 max-h-32 overflow-y-auto">
                    {curriculumExpectations.map((exp, _index) => (
                      <div key={exp.id} className="text-sm p-2 bg-gray-50 rounded">
                        <span className="font-medium">{exp.code}:</span> {exp.description}
                      </div>
                    ))}
                  </div>
                </div>
              )}

              <div className="flex gap-2 pt-4">
                <Button 
                  className="flex-1" 
                  disabled={isGenerating || !formData.unitTitle || !formData.subject}
                  onClick={(): void => { void generateCompleteUnit(); }}
                >
                  {isGenerating ? (
                    <>
                      <RefreshCw className="h-4 w-4 mr-2 animate-spin" />
                      Generating...
                    </>
                  ) : (
                    <>
                      <Sparkles className="h-4 w-4 mr-2" />
                      Generate Complete Unit Plan
                    </>
                  )}
                </Button>
              </div>

              <div className="grid grid-cols-2 gap-2">
                <Button 
                  disabled={isGenerating} 
                  variant="outline"
                  onClick={() => {
 void generateSuggestions('bigIdeas'); 
}}
                >
                  <Lightbulb className="h-4 w-4 mr-2" />
                  Big Ideas
                </Button>
                <Button 
                  disabled={isGenerating} 
                  variant="outline"
                  onClick={() => {
 void generateSuggestions('activities'); 
}}
                >
                  <BookOpen className="h-4 w-4 mr-2" />
                  Activities
                </Button>
              </div>
            </TabsContent>

            <TabsContent className="space-y-4" value="suggestions">
              {suggestions.length === 0 ? (
                <div className="text-center py-8 text-gray-500">
                  <Sparkles className="h-8 w-8 mx-auto mb-2 opacity-20" />
                  <p>No suggestions generated yet. Use the Setup tab to generate AI suggestions.</p>
                </div>
              ) : (
                <div className="space-y-4">
                  {suggestions.map((suggestion, index) => (
                    <Card key={`${suggestion.type}-${index}`}>
                      <CardHeader>
                        <CardTitle className="text-base capitalize flex items-center gap-2">
                          {suggestion.type === 'bigIdeas' && <Lightbulb className="h-4 w-4" />}
                          {suggestion.type === 'activities' && <BookOpen className="h-4 w-4" />}
                          {suggestion.type === 'assessments' && <Target className="h-4 w-4" />}
                          {suggestion.type.replace(/([A-Z])/g, ' $1').trim()}
                        </CardTitle>
                        {suggestion.rationale !== null && suggestion.rationale !== undefined && suggestion.rationale !== '' && (
                          <CardDescription>{suggestion.rationale}</CardDescription>
                        )}
                      </CardHeader>
                      <CardContent>
                        <div className="space-y-2">
                          {suggestion.content.map((item, itemIndex) => {
                            const key = `${suggestion.type}-${item}`;
                            const isAccepted = acceptedSuggestions.has(key);

                            return (
                              <div
                                key={itemIndex}
                                className={`p-3 rounded-lg border transition-colors ${
                                  isAccepted
                                    ? 'bg-green-50 border-green-300'
                                    : 'bg-gray-50 hover:bg-gray-100'
                                }`}
                              >
                                <div className="flex items-start justify-between gap-2">
                                  <p className="text-sm flex-1">{item}</p>
                                  <div className="flex gap-1">
                                    <Button
                                      className="h-8 w-8 p-0"
                                      size="sm"
                                      variant="ghost"
                                      onClick={() => {
 copySuggestion(item); 
}}
                                    >
                                      <Copy className="h-4 w-4" />
                                    </Button>
                                    {!isAccepted ? (
                                      <Button
                                        className="h-8 w-8 p-0"
                                        size="sm"
                                        variant="ghost"
                                        onClick={() => {
 acceptSuggestion(suggestion.type, item); 
}}
                                      >
                                        <Check className="h-4 w-4 text-green-500" />
                                      </Button>
                                    ) : (
                                      <div className="h-8 w-8 flex items-center justify-center">
                                        <CheckCircle className="h-4 w-4 text-green-500" />
                                      </div>
                                    )}
                                  </div>
                                </div>
                              </div>
                            );
                          })}
                        </div>
                      </CardContent>
                    </Card>
                  ))}
                </div>
              )}
            </TabsContent>

            <TabsContent className="space-y-4" value="review">
              <div className="text-center py-8 text-gray-500">
                <Clock className="h-8 w-8 mx-auto mb-2" />
                <p>Review tab will show the complete generated unit plan.</p>
                <p className="text-sm">Generate suggestions first to see the full plan here.</p>
              </div>
            </TabsContent>
          </Tabs>
        </CardContent>
      </Card>

      {/* Loading Modal */}
      <AILoadingIndicator
        currentStepId={loadingStep}
        isOpen={showLoadingModal}
        state={isGenerating ? 'processing' : 'waiting'}
        onCancel={() => {
          setShowLoadingModal(false);
          setIsGenerating(false);
        }}
        {...AI_LOADING_PRESETS.GENERATING_UNIT_PLAN}
        canCancel
      />
    </WithAIErrorBoundary>
  );
}

import { useMutation } from '@tanstack/react-query';
import { Calendar, Clock, AlertCircle, CheckCircle, Sparkles } from 'lucide-react';
import { useState } from 'react';
import { toast } from 'sonner';

import { api } from '../../api';
import { Dialog } from '../Dialog';

interface AIWeeklyPlanModalProps {
  isOpen: boolean;
  onClose: () => void;
  weekStart: string;
  onPlanApplied?: () => void;
}

interface PlanActivity {
  time: string;
  subject: string;
  activityTitle: string;
  activityDescription: string;
  duration: number;
  expectationIds: string[]; // Updated for ETFO alignment
  materials?: string[];
}

interface QualityMetrics {
  coverageScore: number;
  balanceScore: number;
  pacingScore: number;
  overallScore: number;
}

interface GeneratedPlan {
  planId: number;
  plan: {
    monday: PlanActivity[];
    tuesday: PlanActivity[];
    wednesday: PlanActivity[];
    thursday: PlanActivity[];
    friday: PlanActivity[];
    qualityMetrics: QualityMetrics;
    gapsCovered: string[];
  };
  metrics: QualityMetrics;
  availableSlots: number;
  gapsCovered: string[];
}

export function AIWeeklyPlanModal({
  isOpen,
  onClose,
  weekStart,
  onPlanApplied,
}: AIWeeklyPlanModalProps): React.ReactElement {
  const [preferences, setPreferences] = useState({
    preferredComplexity: 'moderate' as 'simple' | 'moderate' | 'complex',
    includeAssessments: false,
    bufferTime: 5,
    subjectHours: {} as Record<string, number>,
  });
  const [generatedPlan, setGeneratedPlan] = useState<GeneratedPlan | null>(null);
  const [selectedDay, setSelectedDay] = useState<keyof GeneratedPlan['plan']>('monday');

  // Generate plan mutation
  const generateMutation = useMutation({
    mutationFn: async () => {
      const response = await api.post('/api/ai/plans/generate', {
        weekStart,
        preferences,
      });
      return (response.data as { data: GeneratedPlan }).data;
    },
    onSuccess: (_data: GeneratedPlan) => {
      setGeneratedPlan(_data);
      toast.success('Weekly plan generated successfully!');
    },
    onError: () => {
      toast.error('Failed to generate weekly plan');
    },
  });

  // Apply plan mutation
  const applyMutation = useMutation({
    mutationFn: async (planId: number) => {
      const response = await api.post(`/api/ai/plans/${planId}/apply`);
      return (response.data as { data: { success: boolean } }).data;
    },
    onSuccess: () => {
      toast.success('Plan applied to calendar!');
      onPlanApplied?.();
      onClose();
    },
    onError: (error: unknown) => {
      interface ApiError extends Error {
        response?: {
          data?: {
            error?: string;
          };
        };
      }
      const errorMessage =
        error instanceof Error && 'response' in error
          ? (error as ApiError).response?.data?.error !== null && (error as ApiError).response?.data?.error !== undefined && (error as ApiError).response?.data?.error !== '' ? (error as ApiError).response?.data?.error : 'Failed to apply plan'
          : 'Failed to apply plan';
      toast.error(errorMessage);
    },
  });

  const handleGenerate = (): void => {
    generateMutation.mutate();
  };

  const handleApply = (): void => {
    if (generatedPlan) {
      applyMutation.mutate(generatedPlan.planId);
    }
  };

  const getMetricColor = (score: number): string => {
    if (score >= 0.8) {
return 'text-green-600';
}
    if (score >= 0.6) {
return 'text-yellow-600';
}
    return 'text-red-600';
  };

  const formatTime = (time: string): string => {
    const [hours, minutes] = time.split(':');
    const hour = parseInt(hours);
    const ampm = hour >= 12 ? 'PM' : 'AM';
    const displayHour = hour > 12 ? hour - 12 : hour === 0 ? 12 : hour;
    return `${displayHour}:${minutes} ${ampm}`;
  };

  return (
    <Dialog open={isOpen} title="AI Weekly Plan Generator" onClose={onClose}>
      <div className="space-y-6">
        {!generatedPlan ? (
          <>
            {/* Preferences Form */}
            <div className="space-y-4">
              <div>
                <h3 className="text-lg font-medium text-gray-900 mb-3">Planning Preferences</h3>

                <div className="space-y-3">
                  <div>
                    <label className="block text-sm font-medium text-gray-700">
                      Activity Complexity
                    </label>
                    <select
                      className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-purple-500 focus:ring-purple-500"
                      value={preferences.preferredComplexity}
                      onChange={(e) => {
 setPreferences({
                          ...preferences,
                          preferredComplexity: e.target.value as 'simple' | 'moderate' | 'complex',
                        }); 
}
                      }
                    >
                      <option value="simple">Simple</option>
                      <option value="moderate">Moderate</option>
                      <option value="complex">Complex</option>
                    </select>
                  </div>

                  <div>
                    <label className="flex items-center">
                      <input
                        checked={preferences.includeAssessments}
                        className="mr-2 rounded border-gray-300 text-purple-600 focus:ring-purple-500"
                        type="checkbox"
                        onChange={(e) => {
 setPreferences({
                            ...preferences,
                            includeAssessments: e.target.checked,
                          }); 
}
                        }
                      />
                      <span className="text-sm text-gray-700">Include assessment activities</span>
                    </label>
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700">
                      Buffer time between activities (minutes)
                    </label>
                    <input
                      className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-purple-500 focus:ring-purple-500"
                      max="30"
                      min="0"
                      type="number"
                      value={preferences.bufferTime}
                      onChange={(e) => {
 setPreferences({
                          ...preferences,
                          bufferTime: parseInt(e.target.value),
                        }); 
}
                      }
                    />
                  </div>
                </div>
              </div>

              <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
                <div className="flex">
                  <AlertCircle className="h-5 w-5 text-blue-600 mt-0.5" />
                  <div className="ml-3">
                    <h4 className="text-sm font-medium text-blue-800">AI Planning Assistant</h4>
                    <p className="text-sm text-blue-700 mt-1">
                      The AI will analyze your curriculum gaps, respect your timetable, and create a
                      balanced weekly plan optimized for student learning.
                    </p>
                  </div>
                </div>
              </div>
            </div>

            <div className="flex justify-end gap-3">
              <button
                className="px-4 py-2 text-gray-700 hover:bg-gray-100 rounded-md"
                onClick={onClose}
              >
                Cancel
              </button>
              <button
                className="px-4 py-2 bg-purple-600 text-white rounded-md hover:bg-purple-700 disabled:opacity-50 flex items-center gap-2"
                disabled={generateMutation.isPending}
                onClick={handleGenerate}
              >
                <Sparkles className="h-4 w-4" />
                {generateMutation.isPending ? 'Generating...' : 'Generate Plan'}
              </button>
            </div>
          </>
        ) : (
          <>
            {/* Generated Plan Preview */}
            <div>
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-lg font-medium text-gray-900">Generated Plan Preview</h3>
                <button
                  className="text-sm text-purple-600 hover:text-purple-700"
                  onClick={() => {
 setGeneratedPlan(null); 
}}
                >
                  Generate New Plan
                </button>
              </div>

              {/* Quality Metrics */}
              <div className="grid grid-cols-4 gap-4 mb-6">
                <div className="text-center">
                  <div
                    className={`text-2xl font-bold ${getMetricColor(generatedPlan.plan.qualityMetrics.coverageScore)}`}
                  >
                    {(generatedPlan.plan.qualityMetrics.coverageScore * 100).toFixed(0)}%
                  </div>
                  <div className="text-sm text-gray-600">Coverage</div>
                </div>
                <div className="text-center">
                  <div
                    className={`text-2xl font-bold ${getMetricColor(generatedPlan.plan.qualityMetrics.balanceScore)}`}
                  >
                    {(generatedPlan.plan.qualityMetrics.balanceScore * 100).toFixed(0)}%
                  </div>
                  <div className="text-sm text-gray-600">Balance</div>
                </div>
                <div className="text-center">
                  <div
                    className={`text-2xl font-bold ${getMetricColor(generatedPlan.plan.qualityMetrics.pacingScore)}`}
                  >
                    {(generatedPlan.plan.qualityMetrics.pacingScore * 100).toFixed(0)}%
                  </div>
                  <div className="text-sm text-gray-600">Pacing</div>
                </div>
                <div className="text-center">
                  <div
                    className={`text-2xl font-bold ${getMetricColor(generatedPlan.plan.qualityMetrics.overallScore)}`}
                  >
                    {(generatedPlan.plan.qualityMetrics.overallScore * 100).toFixed(0)}%
                  </div>
                  <div className="text-sm text-gray-600">Overall</div>
                </div>
              </div>

              {/* Day Selector */}
              <div className="flex gap-2 mb-4">
                {(['monday', 'tuesday', 'wednesday', 'thursday', 'friday'] as const).map((day, _index) => (
                  <button
                    key={day}
                    className={`px-3 py-1 rounded-md text-sm font-medium capitalize ${
                      selectedDay === day
                        ? 'bg-purple-600 text-white'
                        : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                    }`}
                    onClick={() => {
 setSelectedDay(day); 
}}
                  >
                    {day}
                  </button>
                ))}
              </div>

              {/* Day Activities */}
              <div className="border border-gray-200 rounded-lg p-4 max-h-96 overflow-y-auto">
                {!Array.isArray(generatedPlan.plan[selectedDay]) ||
                generatedPlan.plan[selectedDay].length === 0 ? (
                  <p className="text-gray-500 text-center py-4">
                    No activities scheduled for {selectedDay}
                  </p>
                ) : (
                  <div className="space-y-3">
                    {(generatedPlan.plan[selectedDay] as PlanActivity[]).map(
                      (activity: PlanActivity, index: number) => (
                        <div
                          key={index}
                          className="border border-gray-200 rounded-lg p-3 hover:bg-gray-50"
                        >
                          <div className="flex items-start justify-between mb-2">
                            <div>
                              <div className="flex items-center gap-2">
                                <Clock className="h-4 w-4 text-gray-400" />
