                <Calendar className="h-4 w-4" />
                {applyMutation.isPending ? 'Applying...' : 'Apply to Calendar'}
              </button>
            </div>
          </>
        )}
      </div>
    </Dialog>
  );
}

import { useMutation, useQuery } from '@tanstack/react-query';
import { Send, MessageSquare, X, Sparkles, Mic, MicOff } from 'lucide-react';
import { useState, useRef, useEffect } from 'react';
import { toast } from 'sonner';

import { api } from '../../api';
import type { SpeechRecognition, SpeechRecognitionEvent } from '../../types/speech-recognition';

interface Action {
  type: string;
  data: unknown;
}

interface ActivityGeneratedResult {
  type: 'activities_generated';
  data: Activity[];
}

interface PlanGeneratedResult {
  type: 'plan_generated';
  data: Plan;
}

interface CoverageAnalysisResult {
  type: 'coverage_analysis';
  data: {
    coveragePercentage: number;
    [key: string]: unknown;
  };
}

type ActionResult = ActivityGeneratedResult | PlanGeneratedResult | CoverageAnalysisResult;

interface Message {
  role: 'user' | 'assistant' | 'system';
  content: string;
  timestamp: Date;
  actions?: Action[];
  actionResults?: ActionResult[];
}

interface Activity {
  id?: string | number;
  title: string;
  description: string;
  subject?: string;
  duration?: number;
  materials?: string[];
  expectationIds?: string[];
  [key: string]: unknown;
}

interface Plan {
  id?: string | number;
  weekStart?: string;
  activities?: Activity[];
  qualityMetrics?: {
    coverageScore: number;
    balanceScore: number;
    pacingScore: number;
    overallScore: number;
  };
  [key: string]: unknown;
}

interface GPTPlanningAgentProps {
  isOpen: boolean;
  onClose: () => void;
  onActivityGenerated?: (activities: Activity[]) => void;
  onPlanGenerated?: (plan: Plan) => void;
}

export function GPTPlanningAgent({
  isOpen,
  onClose,
  onActivityGenerated,
  onPlanGenerated,
}: GPTPlanningAgentProps): React.ReactElement | null {
  const [sessionId, setSessionId] = useState<string | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [isListening, setIsListening] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const recognitionRef = useRef<SpeechRecognition | null>(null);

  interface SessionResponse {
    sessionId: string;
    message: string;
  }

  // Start session
  const startSessionMutation = useMutation({
    mutationFn: async () => {
      const response = await api.post<{ data: SessionResponse }>('/api/ai/agent/sessions');
      return response.data.data;
    },
    onSuccess: (data) => {
      setSessionId(data.sessionId);
      setMessages([
        {
          role: 'assistant',
          content: data.message,
          timestamp: new Date(),
        },
      ]);
    },
  });

  interface MessageResponse {
    message: string;
    actions?: Action[];
    actionResults?: ActionResult[];
  }

  // Send message
  const sendMessageMutation = useMutation({
    mutationFn: async (message: string) => {
      if (sessionId === null || sessionId === undefined || sessionId === '') {
throw new Error('No session');
}
      const response = await api.post<{ data: MessageResponse }>('/api/ai/agent/messages', {
        sessionId,
        message,
      });
      return response.data.data;
    },
    onSuccess: (data) => {
      setMessages((prev) => [
        ...prev,
        {
          role: 'assistant',
          content: data.message,
          timestamp: new Date(),
          actions: data.actions,
          actionResults: data.actionResults,
        },
      ]);

      // Handle action results
      if (data.actionResults !== null && data.actionResults !== undefined && Array.isArray(data.actionResults)) {
        data.actionResults.forEach((result: ActionResult) => {
          switch (result.type) {
            case 'activities_generated':
              if (onActivityGenerated) {
                onActivityGenerated(result.data);
              }
              break;
            case 'plan_generated':
              if (onPlanGenerated) {
                onPlanGenerated(result.data);
              }
              break;
            // coverage_analysis doesn't need special handling
          }
        });
      }
    },
    onError: () => {
      toast.error('Failed to send message');
    },
  });

  // Get quick actions
  interface QuickAction {
    label: string;
    value?: string;
    description?: string;
  }

  const { data: quickActions } = useQuery<QuickAction[]>({
    queryKey: ['quick-actions'],
    queryFn: async () => {
      const response = await api.get('/api/ai/agent/quick-actions');
      return (response.data as { data: QuickAction[] }).data;
    },
  });

  // Initialize session when opened
  useEffect(() => {
    return () => { // Cleanup
    };

    if (isOpen && (sessionId === null || sessionId === undefined || sessionId === '')) {
      startSessionMutation.mutate();
    }
  }, [isOpen, sessionId, startSessionMutation]);

  // Scroll to bottom when messages change
  useEffect(() => {
    return () => { // Cleanup
    };

    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // Initialize speech recognition
  useEffect(() => {
    return () => { // Cleanup
    };

    if ('webkitSpeechRecognition' in window || 'SpeechRecognition' in window) {
      const SpeechRecognitionConstructor =
        window.SpeechRecognition !== null && window.SpeechRecognition !== undefined ? window.SpeechRecognition : window.webkitSpeechRecognition;
      const recognition = new SpeechRecognitionConstructor();
      recognitionRef.current = recognition;

      recognition.continuous = false;
      recognition.interimResults = false;
      recognition.lang = 'en-US';

      recognition.onresult = (event: SpeechRecognitionEvent): void => {
        const {transcript} = event.results[0][0];
        setInputValue(transcript);
        setIsListening(false);
      };

      recognition.onerror = (): void => {
        setIsListening(false);
        toast.error('Voice recognition failed');
      };

      recognition.onend = (): void => {
        setIsListening(false);
      };
    }
  }, []) // eslint-disable-line react-hooks/exhaustive-deps

  const handleSend = (): void => {
    if (!inputValue.trim() || sendMessageMutation.isPending) {
return;
}

    const userMessage = inputValue.trim();
    setInputValue('');

    setMessages((prev) => [
      ...prev,
      {
        role: 'user',
        content: userMessage,
        timestamp: new Date(),
      },
    ]);

    sendMessageMutation.mutate(userMessage);
  };

  const handleQuickAction = (action: QuickAction): void => {
    const message = action.label;
    setMessages((prev) => [
      ...prev,
      {
        role: 'user',
        content: message,
        timestamp: new Date(),
      },
    ]);
    sendMessageMutation.mutate(message);
  };

  const toggleVoiceRecognition = (): void => {
    if (!recognitionRef.current) {
      toast.error('Voice recognition not supported');
      return;
    }

    if (isListening) {
      recognitionRef.current.stop();
    } else {
      recognitionRef.current.start();
      setIsListening(true);
    }
  };

  if (!isOpen) {
return null;
}

  return (
    <div className="fixed bottom-4 right-4 w-96 h-[600px] bg-white rounded-lg shadow-xl border border-gray-200 flex flex-col z-50">
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-gray-200">
        <div className="flex items-center gap-2">
          <MessageSquare className="h-5 w-5 text-purple-600" />
          <h3 className="font-semibold text-gray-900">Planning Assistant</h3>
        </div>
        <button className="p-1 hover:bg-gray-100 rounded" onClick={onClose}>
          <X className="h-5 w-5 text-gray-500" />
        </button>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {messages.map((message, _index) => (
          <div
            key={_index}
            className={`flex ${message.role === 'user' ? 'justify-end' : 'justify-start'}`}
          >
            <div
              className={`max-w-[80%] rounded-lg p-3 ${
                message.role === 'user' ? 'bg-purple-600 text-white' : 'bg-gray-100 text-gray-900'
              }`}
            >
              <p className="text-sm whitespace-pre-wrap">{message.content}</p>

              {/* Action Results */}
              {message.actionResults && message.actionResults.length > 0 && (
                <div className="mt-2 pt-2 border-t border-gray-200">
                  {message.actionResults.map((result: ActionResult, idx: number) => (
                    <div key={idx} className="text-xs">
                      {result.type === 'activities_generated' && (
                        <span className="flex items-center gap-1">
                          <Sparkles className="h-3 w-3" />
                          Generated {result.data.length} activities
                        </span>
                      )}
                      {result.type === 'plan_generated' && (
                        <span className="flex items-center gap-1">
                          <Sparkles className="h-3 w-3" />
                          Generated weekly plan
                        </span>
                      )}
                      {result.type === 'coverage_analysis' && (
                        <span>Coverage: {result.data.coveragePercentage.toFixed(0)}%</span>
                      )}
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        ))}
        <div ref={messagesEndRef} />
      </div>

      {/* Quick Actions */}
      {quickActions && quickActions.length > 0 && messages.length === 1 && (
        <div className="px-4 pb-2">
          <p className="text-xs text-gray-500 mb-2">Quick actions:</p>
          <div className="flex flex-wrap gap-2">
            {quickActions.map((action: QuickAction, index: number) => (
              <button
                key={index}
                className="text-xs px-3 py-1 bg-purple-100 text-purple-700 rounded-full hover:bg-purple-200"
                onClick={() => {
 handleQuickAction(action); 
}}
              >
                {action.label}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Input */}
      <div className="border-t border-gray-200 p-4">
        <div className="flex gap-2">
          <input
            className="flex-1 px-3 py-2 border border-gray-300 rounded-md focus:ring-purple-500 focus:border-purple-500"
            disabled={sendMessageMutation.isPending}
            placeholder="Ask me anything about planning..."
            type="text"
            value={inputValue}
            onChange={(e) => {
 setInputValue(e.target.value); 
}}
            onKeyPress={(e) => e.key === 'Enter' && handleSend()}
          />
          <button
            className={`p-2 rounded-md ${
              isListening
                ? 'bg-red-100 text-red-600 hover:bg-red-200'
                : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
            }`}
            title={isListening ? 'Stop recording' : 'Start voice input'}
            onClick={toggleVoiceRecognition}
          >
            {isListening ? <MicOff className="h-5 w-5" /> : <Mic className="h-5 w-5" />}
          </button>
          <button
            className="p-2 bg-purple-600 text-white rounded-md hover:bg-purple-700 disabled:opacity-50"
            disabled={!inputValue.trim() || sendMessageMutation.isPending}
            onClick={handleSend}
          >
            <Send className="h-5 w-5" />
          </button>
        </div>
      </div>
    </div>
  );
}

import { useMutation, useQueryClient } from '@tanstack/react-query';
import { format } from 'date-fns';
import { X, Edit, Trash2, Calendar, Clock, Book } from 'lucide-react';
import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'sonner';

import { apiClient } from '../../api/core/client';
import { Button } from '../ui/Button';

interface CalendarViewEvent {
  id: string;
  title: string;
  start: Date;
  end: Date;
  type: string;
  metadata?: {
    subject?: string;
    unitId?: string;
    lessonId?: string;
    color: string;
    isEditable: boolean;
  };
  originalData?: {
    id: string;
    [key: string]: unknown;
  };
}

interface CalendarEventDetailsProps {
  event: CalendarViewEvent;
  onClose: () => void;
  onUpdate?: () => void;
}

export default function CalendarEventDetails({
  event,
  onClose,
  onUpdate,
}: CalendarEventDetailsProps): React.ReactElement {
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const [isEditing, setIsEditing] = useState(false);
  const [editedTitle, setEditedTitle] = useState(event.title);

  // Delete mutation
  const deleteMutation = useMutation({
    mutationFn: async () => {
      if (event.type === 'lesson' && event.metadata?.lessonId !== null && event.metadata?.lessonId !== undefined && event.metadata.lessonId !== '') {
        return apiClient.delete(`/api/etfo-lesson-plans/${event.metadata.lessonId}`);
      } else if (event.originalData?.id) {
        return apiClient.delete(`/api/calendar-events/${event.originalData.id}`);
      }
    },
    onSuccess: () => {
      toast.success('Event deleted successfully');
      void queryClient.invalidateQueries({ queryKey: ['calendar-events'] });
      void queryClient.invalidateQueries({ queryKey: ['lessons'] });
      onUpdate?.();
      onClose();
    },
    onError: () => {
      toast.error('Failed to delete event');
    },
  });

  // Update title mutation
  const updateTitleMutation = useMutation({
    mutationFn: async (newTitle: string) => {
      if (event.type === 'lesson' && event.metadata?.lessonId !== null && event.metadata?.lessonId !== undefined && event.metadata.lessonId !== '') {
        return apiClient.patch(`/api/etfo-lesson-plans/${event.metadata.lessonId}`, {
          title: newTitle,
        });
      } else if (event.originalData?.id) {
        return apiClient.patch(`/api/calendar-events/${event.originalData.id}`, {
          title: newTitle,
        });
      }
    },
    onSuccess: () => {
      toast.success('Event updated successfully');
      void queryClient.invalidateQueries({ queryKey: ['calendar-events'] });
      void queryClient.invalidateQueries({ queryKey: ['lessons'] });
      setIsEditing(false);
      onUpdate?.();
    },
    onError: () => {
      toast.error('Failed to update event');
    },
  });

  const handleSaveTitle = (): void => {
    if (editedTitle.trim() && editedTitle !== event.title) {
      updateTitleMutation.mutate(editedTitle.trim());
    } else {
      setIsEditing(false);
    }
  };

  const handleDelete = (): void => {
    if (window.confirm('Are you sure you want to delete this event?')) {
      deleteMutation.mutate();
    }
  };

  const handleViewDetails = (): void => {
    if (event.type === 'lesson' && event.metadata?.lessonId !== null && event.metadata?.lessonId !== undefined && event.metadata.lessonId !== '') {
      navigate(`/planner/lessons/${event.metadata.lessonId}`);
    } else if (event.type === 'unit-boundary' && event.metadata?.unitId) {
      navigate(`/planner/units/${event.metadata.unitId}`);
    }
  };

  const getEventTypeLabel = (): string => {
    const typeLabels: Record<string, string> = {
      lesson: 'Lesson',
      'unit-boundary': 'Unit Milestone',
      holiday: 'Holiday',
      'pd-day': 'PD Day',
      assessment: 'Assessment',
      'school-event': 'School Event',
    };
    return typeLabels[event.type] ?? 'Event';
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-lg shadow-xl max-w-md w-full">
        <div
          className="p-4 rounded-t-lg flex justify-between items-center"
          style={{ backgroundColor: event.metadata?.color ?? '#6B7280' }}
        >
          <h3 className="text-white font-semibold flex items-center gap-2">
            <Calendar className="h-5 w-5" />
            {getEventTypeLabel()}
          </h3>
          <button
            className="text-white hover:text-gray-200 transition-colors"
            onClick={onClose}
          >
            <X className="h-5 w-5" />
          </button>
        </div>

        <div className="p-6">
          {/* Title */}
          <div className="mb-4">
            {isEditing ? (
              <div className="flex gap-2">
                <input
                  autoFocus
                  className="flex-1 px-2 py-1 border rounded focus:outline-none focus:ring-2 focus:ring-blue-500"
                  type="text"
                  value={editedTitle}
                  onChange={(e) => {
 setEditedTitle(e.target.value); 
}}
                  onKeyPress={(e) => e.key === 'Enter' && handleSaveTitle()}
                />
                <Button
                  disabled={updateTitleMutation.isPending}
                  size="sm"
                  onClick={handleSaveTitle}
                >
                  Save
                </Button>
                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => {
                    setIsEditing(false);
                    setEditedTitle(event.title);
                  }}
                >
                  Cancel
                </Button>
              </div>
            ) : (
              <div className="flex justify-between items-start">
                <h2 className="text-xl font-semibold">{event.title}</h2>
                {event.metadata?.isEditable && (
                  <button
                    className="text-gray-500 hover:text-gray-700"
                    onClick={() => {
 setIsEditing(true); 
}}
                  >
                    <Edit className="h-4 w-4" />
                  </button>
                )}
              </div>
            )}
          </div>

          {/* Details */}
          <div className="space-y-3">
            <div className="flex items-center gap-2 text-gray-600">
              <Calendar className="h-4 w-4" />
              <span>{format(event.start, 'EEEE, MMMM d, yyyy')}</span>
            </div>

            {!event.originalData?.allDay && event.start.getTime() !== event.end.getTime() && (
              <div className="flex items-center gap-2 text-gray-600">
                <Clock className="h-4 w-4" />
                <span>
                  {format(event.start, 'h:mm a')} - {format(event.end, 'h:mm a')}
                </span>
              </div>
            )}

            {event.metadata?.subject && (
              <div className="flex items-center gap-2 text-gray-600">
                <Book className="h-4 w-4" />
                <span className="capitalize">{event.metadata.subject}</span>
              </div>
            )}

            {event.originalData?.description ? (
              <div className="mt-4">
                <h4 className="font-medium text-gray-700 mb-1">Description</h4>
                <p className="text-gray-600 text-sm">{String(event.originalData.description ?? '')}</p>
              </div>
            ) : null}
          </div>

          {/* Actions */}
          <div className="mt-6 flex gap-2">
            {(event.type === 'lesson' || event.type === 'unit-boundary') && (
              <Button aria-label="Click button" onClick={handleViewDetails}>
                View Details
              </Button>
            )}
            {event.metadata?.isEditable && (
              <Button
                className="flex items-center gap-2"
                disabled={deleteMutation.isPending}
                variant="danger"
                onClick={handleDelete}
              >
                <Trash2 className="h-4 w-4" />
                Delete
              </Button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

import { useMutation, useQueryClient } from '@tanstack/react-query';
import { format } from 'date-fns';
import { Calendar, Clock } from 'lucide-react';
import { useState } from 'react';
import { toast } from 'sonner';

import { apiClient } from '../../api/core';
import { Button } from '../ui/Button';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from '../ui/Dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '../ui/select';

interface CalendarEventModalProps {
  isOpen: boolean;
  onClose: () => void;
  selectedDate?: Date;
  onEventCreated?: () => void;
}

type EventType = 'lesson' | 'assessment' | 'pd-day' | 'school-event' | 'holiday';

const EVENT_TYPE_OPTIONS: { value: EventType; label: string }[] = [
  { value: 'lesson', label: 'Lesson' },
  { value: 'assessment', label: 'Assessment' },
  { value: 'pd-day', label: 'PD Day' },
  { value: 'school-event', label: 'School Event' },
  { value: 'holiday', label: 'Holiday' },
];

export default function CalendarEventModal({
  isOpen,
  onClose,
  selectedDate = new Date(),
  onEventCreated,
}: CalendarEventModalProps): React.ReactElement {
  const queryClient = useQueryClient();
  const [eventType, setEventType] = useState<EventType>('lesson');
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    date: format(selectedDate, 'yyyy-MM-dd'),
    startTime: '09:00',
    endTime: '10:00',
    allDay: false,
    subject: '',
  });

  // Create event mutation
  const createEventMutation = useMutation({
    mutationFn: async (data: typeof formData) => {
      if (eventType === 'lesson') {
        // Create a lesson plan
        return apiClient.post('/api/etfo-lesson-plans', {
          title: data.title,
          description: data.description,
          date: data.date,
          subject: data.subject,
          duration: 60, // Default duration
        });
      } 
        // Create a calendar event
        const eventTypeMap: Record<EventType, string> = {
          'assessment': 'CUSTOM',
          'pd-day': 'PD_DAY',
          'school-event': 'CUSTOM',
          'holiday': 'HOLIDAY',
          'lesson': 'CUSTOM',
        };

        return apiClient.post('/api/calendar-events', {
          title: data.title,
          description: data.description,
          start: data.allDay ? `${data.date}T00:00:00Z` : `${data.date}T${data.startTime}:00Z`,
          end: data.allDay ? `${data.date}T23:59:59Z` : `${data.date}T${data.endTime}:00Z`,
          allDay: data.allDay,
          eventType: eventTypeMap[eventType],
        });

    },
    onSuccess: () => {
      toast.success(`${eventType === 'lesson' ? 'Lesson' : 'Event'} created successfully`);
      void queryClient.invalidateQueries({ queryKey: ['calendar-events'] });
      void queryClient.invalidateQueries({ queryKey: ['lessons'] });
      onEventCreated?.();
      onClose();
    },
    onError: () => {
      toast.error('Failed to create event');
    },
  });

  const handleSubmit = (e: React.FormEvent): void => {
    e.preventDefault();
    createEventMutation.mutate(formData);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>): void => {
    const { name, value, type } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? (e.target as HTMLInputElement).checked : value,
    }));
  };

  return (
    <Dialog open={isOpen} onOpenChange={() => {
 onClose(); 
}}>
      <DialogContent className="sm:max-w-[500px]">
        <DialogHeader>
          <DialogTitle>Create New Event</DialogTitle>
        </DialogHeader>
        <form className="space-y-4" onSubmit={handleSubmit}>
          <div>
            <label className="block text-sm font-medium mb-1">Event Type</label>
            <Select value={eventType} onValueChange={(value) => {
 setEventType(value as EventType); 
}}>
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {EVENT_TYPE_OPTIONS.map(option => (
                  <SelectItem key={option.value} value={option.value}>
                    {option.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div>
            <label className="block text-sm font-medium mb-1" htmlFor="title">
              Title
            </label>
            <input
              required
              className="w-full px-3 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
              id="title"
              name="title"
              type="text"
              value={formData.title}
              onChange={handleInputChange}
            />
          </div>

          <div>
            <label className="block text-sm font-medium mb-1" htmlFor="description">
              Description
            </label>
            <textarea
              className="w-full px-3 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
              id="description"
              name="description"
              rows={3}
              value={formData.description}
              onChange={handleInputChange}
            />
          </div>

          {eventType === 'lesson' && (
            <div>
              <label className="block text-sm font-medium mb-1" htmlFor="subject">
                Subject
              </label>
              <input
                className="w-full px-3 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                id="subject"
                name="subject"
                placeholder="e.g., Math, Language, Science"
                type="text"
                value={formData.subject}
                onChange={handleInputChange}
              />
            </div>
          )}

          <div>
            <label className="block text-sm font-medium mb-1" htmlFor="date">
              <Calendar className="inline h-4 w-4 mr-1" />
              Date
            </label>
            <input
              required
              className="w-full px-3 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
              id="date"
              name="date"
              type="date"
              value={formData.date}
              onChange={handleInputChange}
            />
          </div>

          {eventType !== 'lesson' && (
            <>
              <div>
                <label className="flex items-center space-x-2">
                  <input
                    checked={formData.allDay}
                    className="rounded border-gray-300"
                    name="allDay"
                    type="checkbox"
                    onChange={handleInputChange}
                  />
                  <span className="text-sm font-medium">All Day Event</span>
                </label>
              </div>

              {!formData.allDay && (
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium mb-1" htmlFor="startTime">
                      <Clock className="inline h-4 w-4 mr-1" />
                      Start Time
                    </label>
                    <input
                      className="w-full px-3 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                      id="startTime"
                      name="startTime"
                      type="time"
                      value={formData.startTime}
                      onChange={handleInputChange}
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium mb-1" htmlFor="endTime">
                      <Clock className="inline h-4 w-4 mr-1" />
                      End Time
                    </label>
                    <input
                      className="w-full px-3 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                      id="endTime"
                      name="endTime"
                      type="time"
                      value={formData.endTime}
                      onChange={handleInputChange}
                    />
                  </div>
                </div>
              )}
            </>
          )}

          <div className="flex justify-end gap-2 pt-4">
            <Button aria-label="Click button" onClick={onClose}>
              Cancel
            </Button>
            <Button disabled={createEventMutation.isPending} type="submit">
              {createEventMutation.isPending ? 'Creating...' : 'Create Event'}
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import { X } from 'lucide-react';

import { Button } from '../ui/Button';

interface CalendarFilter {
  subjects: string[];
  eventTypes: string[];
  showWeekends: boolean;
}

interface CalendarFiltersProps {
  filters: CalendarFilter;
  onFiltersChange: (filters: CalendarFilter) => void;
  availableSubjects: string[];
}

const EVENT_TYPE_OPTIONS = [
  { value: 'lesson', label: 'Lessons' },
  { value: 'unit-boundary', label: 'Unit Milestones' },
  { value: 'holiday', label: 'Holidays' },
  { value: 'pd-day', label: 'PD Days' },
  { value: 'assessment', label: 'Assessments' },
  { value: 'school-event', label: 'School Events' },
];

export default function CalendarFilters({
  filters,
  onFiltersChange,
  availableSubjects,
}: CalendarFiltersProps): React.ReactElement {
  const handleSubjectToggle = (subject: string): void => {
    const newSubjects = filters.subjects.includes(subject)
      ? filters.subjects.filter(s => s !== subject)
      : [...filters.subjects, subject];
    onFiltersChange({ ...filters, subjects: newSubjects });
  };

  const handleEventTypeToggle = (eventType: string): void => {
    const newEventTypes = filters.eventTypes.includes(eventType)
      ? filters.eventTypes.filter(t => t !== eventType)
      : [...filters.eventTypes, eventType];
    onFiltersChange({ ...filters, eventTypes: newEventTypes });
  };

  const handleClearFilters = (): void => {
    onFiltersChange({
      subjects: [],
      eventTypes: [],
      showWeekends: true,
    });
  };

  const hasActiveFilters = filters.subjects.length > 0 || filters.eventTypes.length > 0 || !filters.showWeekends;

  return (
    <div className="bg-gray-50 rounded-lg p-4 mb-4">
      <div className="flex justify-between items-center mb-3">
        <h3 className="font-semibold text-gray-700">Filter Calendar</h3>
        {hasActiveFilters && (
          <Button
            className="text-gray-500 hover:text-gray-700"
            size="sm"
            variant="ghost"
            onClick={handleClearFilters}
          >
            <X className="h-4 w-4 mr-1" />
            Clear All
          </Button>
        )}
      </div>

      {/* Subject Filters */}
      {availableSubjects.length > 0 && (
        <div className="mb-4">
          <h4 className="text-sm font-medium text-gray-600 mb-2">Subjects</h4>
          <div className="flex flex-wrap gap-2">
            {availableSubjects.map(subject => (
              <button
                key={subject}
                className={`px-3 py-1 rounded-full text-sm transition-colors ${
                  filters.subjects.includes(subject)
                    ? 'bg-blue-500 text-white'
                    : 'bg-white text-gray-700 border border-gray-300 hover:bg-gray-100'
                }`}
                onClick={() => {
 handleSubjectToggle(subject); 
}}
              >
                {subject}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Event Type Filters */}
      <div className="mb-4">
        <h4 className="text-sm font-medium text-gray-600 mb-2">Event Types</h4>
        <div className="flex flex-wrap gap-2">
          {EVENT_TYPE_OPTIONS.map(option => (
            <button
              key={option.value}
              className={`px-3 py-1 rounded-full text-sm transition-colors ${
                filters.eventTypes.includes(option.value)
                  ? 'bg-blue-500 text-white'
                  : 'bg-white text-gray-700 border border-gray-300 hover:bg-gray-100'
              }`}
              onClick={() => {
 handleEventTypeToggle(option.value); 
}}
            >
              {option.label}
            </button>
          ))}
        </div>
      </div>

      {/* Other Options */}
      <div>
        <label className="flex items-center space-x-2 text-sm">
          <input
            checked={filters.showWeekends}
            className="rounded border-gray-300"
            type="checkbox"
            onChange={(e) => {
 onFiltersChange({ ...filters, showWeekends: e.target.checked }); 
}}
          />
          <span className="text-gray-700">Show Weekends</span>
        </label>
      </div>
    </div>
  );
}

import { lazy, Suspense } from 'react';

// Lazy load chart components to reduce initial bundle size
const CurriculumExpectationCoverage = lazy(() => import('../CurriculumExpectationCoverage'));

// Loading fallback for charts
const ChartLoadingFallback = (): JSX.Element => (
  <div className="animate-pulse space-y-4">
    <div className="h-8 bg-gray-200 rounded w-1/3" />
    <div className="h-64 bg-gray-200 rounded" />
    <div className="grid grid-cols-2 gap-4">
      <div className="h-32 bg-gray-200 rounded" />
      <div className="h-32 bg-gray-200 rounded" />
    </div>
  </div>
);

