interface FormTemplatesProps {
  onTemplateGenerate: (templateId: string, config: Record<string, unknown>) => void;
  onTemplateDownload: (templateId: string, data: Record<string, unknown>) => void;
}

export default function FormTemplates({
  onTemplateGenerate,
  onTemplateDownload,
}: FormTemplatesProps): React.ReactElement {
  const [selectedTemplate, setSelectedTemplate] = useState<TemplateConfig | null>(null);
  const [customConfig, setCustomConfig] = useState({
    quantity: 1,
    prefix: '',
    dateRange: {
      start: '',
      end: '',
    },
    includeFields: [] as string[],
  });

  const generateBasicUnitTemplate = (quantity = 1): Record<string, unknown>[] => Array.from({ length: quantity }, (_, index): Record<string, unknown> => ({
      title: `${customConfig.prefix}Unit ${index + 1}`,
      description: '',
      bigIdeas: '',
      essentialQuestions: [''],
      startDate: customConfig.dateRange.start ?? '',
      endDate: customConfig.dateRange.end ?? '',
      estimatedHours: 20,
      assessmentPlan: '',
      successCriteria: [''],
      expectationIds: [],
      longRangePlanId: '',
      crossCurricularConnections: '',
      learningSkills: [],
      culminatingTask: '',
      keyVocabulary: [''],
      priorKnowledge: '',
      parentCommunicationPlan: '',
      fieldTripsAndGuestSpeakers: '',
      differentiationStrategies: {
        forStruggling: [''],
        forAdvanced: [''],
        forELL: [''],
        forIEP: [''],
      },
      indigenousPerspectives: '',
      environmentalEducation: '',
      socialJusticeConnections: '',
      technologyIntegration: '',
      communityConnections: '',
    }));

  const generateBasicLessonTemplate = (quantity = 1): Record<string, unknown>[] => Array.from({ length: quantity }, (_, index): Record<string, unknown> => ({
      title: `${customConfig.prefix}Lesson ${index + 1}`,
      titleFr: '',
      unitPlanId: '',
      date: customConfig.dateRange.start || new Date().toISOString().split('T')[0],
      duration: 60,
      mindsOn: '',
      mindsOnFr: '',
      action: '',
      actionFr: '',
      consolidation: '',
      consolidationFr: '',
      learningGoals: '',
      learningGoalsFr: '',
      materials: [''],
      grouping: 'whole class',
      accommodations: [''],
      modifications: [''],
      extensions: [''],
      assessmentType: 'formative' as const,
      assessmentNotes: '',
      isSubFriendly: true,
      subNotes: '',
      expectationIds: [],
    }));

  const generateSubFriendlyLessonTemplate = (quantity = 1): Record<string, unknown>[] => Array.from({ length: quantity }, (_, index): Record<string, unknown> => ({
      title: `${customConfig.prefix}Sub Plan ${index + 1}`,
      titleFr: '',
      unitPlanId: '',
      date: customConfig.dateRange.start || new Date().toISOString().split('T')[0],
      duration: 60,
      mindsOn: 'Simple review activity that requires minimal setup',
      mindsOnFr: '',
      action: 'Independent work or structured activity with clear instructions',
      actionFr: '',
      consolidation: 'Quick reflection or closure activity',
      consolidationFr: '',
      learningGoals: 'Continue learning in teacher\'s absence',
      learningGoalsFr: '',
      materials: ['Student textbook', 'Worksheets (prepared)', 'Basic supplies available in class'],
      grouping: 'individual',
      accommodations: ['Clear written instructions', 'Visual aids available'],
      modifications: ['Simplified tasks available'],
      extensions: ['Additional practice available'],
      assessmentType: 'formative' as const,
      assessmentNotes: 'Collect completed work for review',
      isSubFriendly: true,
      subNotes: 'All materials are pre-arranged. Students know routine. Contact office for any issues.',
      expectationIds: [],
    }));

  const handleTemplateGenerate = (): void => {
    if (!selectedTemplate) {
return;
}

    let templateData: Record<string, unknown>[] = [];

    switch (selectedTemplate.id) {
      case 'basic-unit':
      case 'comprehensive-unit':
        templateData = generateBasicUnitTemplate(customConfig.quantity);
        break;
      case 'basic-lesson':
      case 'detailed-lesson':
        templateData = generateBasicLessonTemplate(customConfig.quantity);
        break;
      case 'sub-friendly-lesson':
        templateData = generateSubFriendlyLessonTemplate(customConfig.quantity);
        break;
    }

    onTemplateGenerate(selectedTemplate.id, {
      template: selectedTemplate,
      data: templateData,
      config: customConfig,
    });
  };

  const handleTemplateDownload = (): void => {
    if (!selectedTemplate) {
return;
}

    let templateData: Record<string, unknown>[] = [];

    switch (selectedTemplate.id) {
      case 'basic-unit':
      case 'comprehensive-unit':
        templateData = generateBasicUnitTemplate(customConfig.quantity);
        break;
      case 'basic-lesson':
      case 'detailed-lesson':
        templateData = generateBasicLessonTemplate(customConfig.quantity);
        break;
      case 'sub-friendly-lesson':
        templateData = generateSubFriendlyLessonTemplate(customConfig.quantity);
        break;
    }

    const filename = `${selectedTemplate.id}-template.json`;
    const data = JSON.stringify(templateData, null, 2);

    const blob = new Blob([data], { type: 'application/json' });
    const url = URL.createObjectURL(blob);

    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);

    URL.revokeObjectURL(url);

    onTemplateDownload(selectedTemplate.id, { data: templateData });
  };

  const getDifficultyColor = (difficulty: string): string => {
    switch (difficulty) {
      case 'beginner':
        return 'bg-green-100 text-green-800';
      case 'intermediate':
        return 'bg-yellow-100 text-yellow-800';
      case 'advanced':
        return 'bg-red-100 text-red-800';
      default:
        return 'bg-gray-100 text-gray-800';
    }
  };

  return (
    <div className="space-y-6">
      {/* Template Library */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <FileText className="h-5 w-5" />
            Template Library
          </CardTitle>
          <CardDescription>
            Choose from pre-built templates for common curriculum planning scenarios
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
            {TEMPLATE_LIBRARY.map((template, _index) => (
              <div
                key={template.id}
                className={`p-4 border rounded-lg cursor-pointer transition-all ${
                  selectedTemplate?.id === template.id
                    ? 'border-indigo-500 bg-indigo-50'
                    : 'border-gray-200 hover:border-gray-300'
                }`}
                onClick={() => {
 setSelectedTemplate(template); 
}}
              >
                <div className="flex items-start gap-3">
                  <div className="flex-shrink-0 text-indigo-600">
                    {template.icon}
                  </div>
                  <div className="flex-1 min-w-0">
                    <h3 className="font-medium text-sm">{template.name}</h3>
                    <p className="text-xs text-gray-600 mt-1">{template.description}</p>
                    <div className="flex gap-2 mt-2">
                      <Badge className="text-xs" variant="outline">
                        {template.type}
                      </Badge>
                      <Badge className={`text-xs ${getDifficultyColor(template.difficulty)}`}>
                        {template.difficulty}
                      </Badge>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Template Configuration */}
      {selectedTemplate && (
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Wand2 className="h-5 w-5" />
              Configure {selectedTemplate.name}
            </CardTitle>
            <CardDescription>
              Customize the template generation settings
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="grid gap-4 md:grid-cols-2">
              <div>
                <Label htmlFor="quantity">Number of entries</Label>
                <Input
                  id="quantity"
                  max="50"
                  min="1"
                  type="number"
                  value={customConfig.quantity}
                  onChange={(e) => {
 setCustomConfig({
                      ...customConfig,
                      quantity: parseInt(e.target.value) || 1,
                    }); 
}
                  }
                />
              </div>
              <div>
                <Label htmlFor="prefix">Title prefix</Label>
                <Input
                  id="prefix"
                  placeholder="e.g., Grade 3 - "
                  value={customConfig.prefix}
                  onChange={(e) => {
 setCustomConfig({ ...customConfig, prefix: e.target.value }); 
}
                  }
                />
              </div>
            </div>

            <div className="grid gap-4 md:grid-cols-2">
              <div>
                <Label htmlFor="start-date">Start date</Label>
                <Input
                  id="start-date"
                  type="date"
                  value={customConfig.dateRange.start}
                  onChange={(e) => {
 setCustomConfig({
                      ...customConfig,
                      dateRange: { ...customConfig.dateRange, start: e.target.value },
                    }); 
}
                  }
                />
              </div>
              <div>
                <Label htmlFor="end-date">End date</Label>
                <Input
                  id="end-date"
                  type="date"
                  value={customConfig.dateRange.end}
                  onChange={(e) => {
 setCustomConfig({
                      ...customConfig,
                      dateRange: { ...customConfig.dateRange, end: e.target.value },
                    }); 
}
                  }
                />
              </div>
            </div>

            <div className="flex gap-2">
              <Button aria-label="Click button" onClick={handleTemplateGenerate}>
                <Wand2 className="h-4 w-4" />
                Generate Template
              </Button>
              <Button
                className="flex items-center gap-2"
                variant="outline"
                onClick={handleTemplateDownload}
              >
                <Download className="h-4 w-4" />
                Download Template
              </Button>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Template Preview */}
      {selectedTemplate && (
        <Card>
          <CardHeader>
            <CardTitle>Template Preview</CardTitle>
            <CardDescription>
              Preview of the fields included in this template
            </CardDescription>
          </CardHeader>
          <CardContent>
            <div className="text-sm space-y-2">
              <div className="font-medium">Included fields:</div>
              <div className="flex flex-wrap gap-1">
                {selectedTemplate.fields.includes('all') ? (
                  <Badge variant="outline">All available fields</Badge>
                ) : (
                  selectedTemplate.fields.map((field, _index) => (
                    <Badge key={field} className="text-xs" variant="outline">
                      {field}
                    </Badge>
                  ))
                )}
              </div>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

import {
  Database,
  FileUp,
  // FileDown,
  RotateCcw,
  CheckCircle,
  AlertCircle,
  Copy,
  // Upload,
  Download,
  ListPlus,
  Wand2,
} from 'lucide-react';
import React, { useState } from 'react';

import type { LongRangePlan, UnitPlan } from '../../hooks/useETFOPlanning';
import { validateUnitPlan, validateLessonPlan } from '../../utils/formValidation';
import logger from '../../utils/logger';
import { safeJsonParse } from "../../utils/typeGuards";
import { Badge } from '../ui/Badge';
import { Button } from '../ui/Button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '../ui/card';
import { Input } from '../ui/Input';
import { Label } from '../ui/Label';
import { Progress } from '../ui/Progress';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '../ui/tabs';

// import { Textarea } from '../ui/Textarea';
import type { LessonPlanFormData } from './LessonPlanForm';
import LessonPlanForm from './LessonPlanForm';
import type { UnitPlanFormData } from './UnitPlanForm';
import UnitPlanForm from './UnitPlanForm';

interface BatchOperation {
  id: string;
  type: 'unit' | 'lesson';
  status: 'pending' | 'processing' | 'completed' | 'error';
  data: UnitPlanFormData | LessonPlanFormData;
  errors?: string[];
  progress?: number;
}

interface FormsDataAgentProps {
  longRangePlans?: LongRangePlan[];
  unitPlans?: UnitPlan[];
  onBatchUnitCreate?: (units: UnitPlanFormData[]) => Promise<void>;
  onBatchLessonCreate?: (lessons: LessonPlanFormData[]) => Promise<void>;
  onTemplateExport?: (
    type: 'unit' | 'lesson',
    template: UnitPlanFormData | LessonPlanFormData,
  ) => void;
  onDataImport?: (type: 'unit' | 'lesson', data: (UnitPlanFormData | LessonPlanFormData)[]) => void;
}

export default function FormsDataAgent({
  longRangePlans = [],
  unitPlans = [],
  onBatchUnitCreate,
  onBatchLessonCreate,
  onTemplateExport,
  onDataImport,
}: FormsDataAgentProps): React.ReactElement {
  const [activeTab, setActiveTab] = useState<'batch' | 'templates' | 'import' | 'wizard'>('batch');
  const [batchOperations, setBatchOperations] = useState<BatchOperation[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [_selectedTemplate, _setSelectedTemplate] = useState<'unit' | 'lesson' | null>(null);

  // Batch operations management
  const addBatchOperation = (
    type: 'unit' | 'lesson',
    data: UnitPlanFormData | LessonPlanFormData,
  ): void => {
    const operation: BatchOperation = {
      id: `${type}-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      type,
      status: 'pending',
      data,
      progress: 0,
    };

    setBatchOperations((prev) => [...prev, operation]);
  };

  const removeBatchOperation = (id: string): void => {
    setBatchOperations((prev) => prev.filter((op) => op.id !== id));
  };

  const clearAllOperations = (): void => {
    setBatchOperations([]);
  };

  const validateBatchOperation = (operation: BatchOperation): string[] => {
    const errors: string[] = [];

    if (operation.type === 'unit') {
      const result = validateUnitPlan(operation.data as UnitPlanFormData);
      if (!result.isValid) {
        errors.push(...Object.values(result.errors));
      }
    } else if (operation.type === 'lesson') {
      const result = validateLessonPlan(operation.data as LessonPlanFormData);
      if (!result.isValid) {
        errors.push(...Object.values(result.errors));
      }
    }

    return errors;
  };

  const processBatchOperations = async (): Promise<void> => {
    if (batchOperations.length === 0) {
return;
}

    setIsProcessing(true);

    try {
      // Validate all operations first
      const validatedOps = batchOperations.map((op, _index) => ({
        ...op,
        errors: validateBatchOperation(op),
        status: 'processing' as const,
      }));

      setBatchOperations(validatedOps);

      // Separate units and lessons
      const unitOps = validatedOps.filter((op) => op.type === 'unit' && op.errors.length === 0);
      const lessonOps = validatedOps.filter(
        (op) => op.type === 'lesson' && op.errors.length === 0,
      );

      // Process units in batch
      if (unitOps.length > 0 && onBatchUnitCreate) {
        const unitData = unitOps.map((op, _index) => op.data as UnitPlanFormData);
        await onBatchUnitCreate(unitData);

        // Mark units as completed
        setBatchOperations((prev) =>
          prev.map((op, _index) =>
            unitOps.some((validOp) => validOp.id === op.id)
              ? { ...op, status: 'completed', progress: 100 }
              : op,
          ),
        );
      }

      // Process lessons in batch
      if (lessonOps.length > 0 && onBatchLessonCreate) {
        const lessonData = lessonOps.map((op, _index) => op.data as LessonPlanFormData);
        await onBatchLessonCreate(lessonData);

        // Mark lessons as completed
        setBatchOperations((prev) =>
          prev.map((op, _index) =>
            lessonOps.some((validOp) => validOp.id === op.id)
              ? { ...op, status: 'completed', progress: 100 }
              : op,
          ),
        );
      }

      // Mark operations with errors
      setBatchOperations((prev) =>
        prev.map((op, _index) => (op.errors && op.errors.length > 0 ? { ...op, status: 'error' } : op)),
      );
    } catch (_error) {
      logger.error('Batch processing error:', _error);
      setBatchOperations((prev) =>
        prev.map((op, _index) => ({
          ...op,
          status: 'error',
          errors: [`Processing failed: ${  (_error as Error).message}`],
        })),
      );
    } finally {
      setIsProcessing(false);
    }
  };

  // Template generation
  const generateTemplate = (type: 'unit' | 'lesson'): void => {
    const template =
      type === 'unit'
        ? ({
            title: '',
            description: '',
            bigIdeas: '',
            essentialQuestions: [''],
            startDate: '',
            endDate: '',
            estimatedHours: 20,
            assessmentPlan: '',
            successCriteria: [''],
            expectationIds: [],
            longRangePlanId: '',
            crossCurricularConnections: '',
            learningSkills: [],
            culminatingTask: '',
            keyVocabulary: [''],
            priorKnowledge: '',
            parentCommunicationPlan: '',
            fieldTripsAndGuestSpeakers: '',
            differentiationStrategies: {
              forStruggling: [''],
              forAdvanced: [''],
              forELL: [''],
              forIEP: [''],
            },
            indigenousPerspectives: '',
            environmentalEducation: '',
            socialJusticeConnections: '',
            technologyIntegration: '',
            communityConnections: '',
          } as UnitPlanFormData)
        : ({
            title: '',
            titleFr: '',
            unitPlanId: '',
            date: '',
            duration: 60,
            mindsOn: '',
            mindsOnFr: '',
            action: '',
            actionFr: '',
            consolidation: '',
            consolidationFr: '',
            learningGoals: '',
            learningGoalsFr: '',
            materials: [''],
            grouping: 'whole class',
            accommodations: [''],
            modifications: [''],
            extensions: [''],
            assessmentType: 'formative' as const,
            assessmentNotes: '',
            isSubFriendly: true,
            subNotes: '',
            expectationIds: [],
          } as LessonPlanFormData);

    onTemplateExport?.(type, template);
  };

  // Import handling
  const handleFileImport = async (event: React.ChangeEvent<HTMLInputElement>): Promise<void> => {
    const file = event.target.files?.[0];
    if (!file) {
return;
}

    try {
      const text = await file.text();
      const data = safeJsonParse<(UnitPlanFormData | LessonPlanFormData)[]>(text, []);

      if (Array.isArray(data)) {
        // Determine type based on data structure
        const type = (data[0] && 'unitPlanId' in data[0]) ? 'lesson' : 'unit';
        onDataImport?.(type, data);
      }
    } catch (_error) {
      logger.error('Import error:', _error);
    }
  };

  const completedOperations = batchOperations.filter((op) => op.status === 'completed').length;
  const errorOperations = batchOperations.filter((op) => op.status === 'error').length;
  const processingOperations = batchOperations.filter((op) => op.status === 'processing').length;
  const totalOperations = batchOperations.length;

  return (
    <div className="max-w-7xl mx-auto p-6">
      <div className="mb-8">
        <h1 className="text-3xl font-bold text-gray-900 mb-2">Forms & Data Agent</h1>
        <p className="text-gray-600">
          Comprehensive data entry management system for curriculum planning
        </p>
      </div>

      <Tabs
        className="space-y-6"
        value={activeTab}
        onValueChange={(value) => {
 setActiveTab(value as 'batch' | 'templates' | 'import' | 'wizard'); 
}
        }
      >
        <TabsList className="grid w-full grid-cols-4">
          <TabsTrigger className="flex items-center gap-2" value="batch">
            <ListPlus className="h-4 w-4" />
            Batch Operations
          </TabsTrigger>
          <TabsTrigger className="flex items-center gap-2" value="templates">
            <Copy className="h-4 w-4" />
            Templates
          </TabsTrigger>
          <TabsTrigger className="flex items-center gap-2" value="import">
            <FileUp className="h-4 w-4" />
            Import/Export
          </TabsTrigger>
          <TabsTrigger className="flex items-center gap-2" value="wizard">
            <Wand2 className="h-4 w-4" />
            Setup Wizard
          </TabsTrigger>
        </TabsList>

        <TabsContent className="space-y-6" value="batch">
          {/* Batch Operations Overview */}
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Database className="h-5 w-5" />
                Batch Operations Queue
              </CardTitle>
              <CardDescription>
                Manage multiple curriculum planning entries with validation and bulk processing
              </CardDescription>
            </CardHeader>
            <CardContent>
              {totalOperations > 0 && (
                <div className="mb-4">
                  <div className="flex justify-between items-center mb-2">
                    <span className="text-sm font-medium">Progress</span>
                    <span className="text-sm text-gray-600">
                      {completedOperations} / {totalOperations} completed
                    </span>
                  </div>
                  <Progress
                    className="mb-2"
                    value={(completedOperations / totalOperations) * 100}
                  />
                  <div className="flex gap-4 text-sm">
                    <span className="flex items-center gap-1 text-green-600">
                      <CheckCircle className="h-4 w-4" />
                      {completedOperations} completed
                    </span>
                    <span className="flex items-center gap-1 text-red-600">
                      <AlertCircle className="h-4 w-4" />
                      {errorOperations} errors
                    </span>
                    <span className="flex items-center gap-1 text-blue-600">
                      <RotateCcw className="h-4 w-4" />
                      {processingOperations} processing
                    </span>
                  </div>
                </div>
              )}

              <div className="flex gap-2 mb-4">
                <Button
                  className="bg-indigo-600 hover:bg-indigo-700"
                  disabled={isProcessing || totalOperations === 0}
                  onClick={(): void => { void processBatchOperations(); }}
                >
                  {isProcessing ? 'Processing...' : 'Process All'}
                </Button>
                <Button aria-label="Click button" onClick={clearAllOperations}>
                  Clear All
                </Button>
              </div>

              {/* Operations List */}
              {batchOperations.length === 0 ? (
                <div className="text-center py-8 text-gray-500">
                  No batch operations queued. Use the forms below to add entries.
                </div>
              ) : (
                <div className="space-y-2 max-h-96 overflow-y-auto">
                  {batchOperations.map((operation, _index) => (
                    <div
                      key={operation.id}
                      className="flex items-center justify-between p-3 border rounded-lg"
                    >
                      <div className="flex items-center gap-3">
                        <Badge variant={operation.type === 'unit' ? 'default' : 'secondary'}>
                          {operation.type}
                        </Badge>
                        <div>
                          <p className="font-medium">{operation.data.title || 'Untitled'}</p>
                          {operation.errors && operation.errors.length > 0 && (
                            <p className="text-sm text-red-600">
                              {operation.errors.length} validation error(s)
                            </p>
                          )}
                        </div>
                      </div>
                      <div className="flex items-center gap-2">
                        <Badge
                          variant={
                            operation.status === 'completed'
                              ? 'default'
                              : operation.status === 'error'
                                ? 'destructive'
                                : 'secondary'
                          }
                        >
                          {operation.status}
                        </Badge>
                        <Button
                          size="sm"
                          variant="ghost"
                          onClick={() => {
 removeBatchOperation(operation.id); 
}}
                        >
                          Remove
                        </Button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </CardContent>
          </Card>

          {/* Quick Add Forms */}
          <div className="grid gap-6 md:grid-cols-2">
            <Card>
              <CardHeader>
                <CardTitle>Quick Add Unit Plan</CardTitle>
                <CardDescription>Add a unit plan to the batch queue</CardDescription>
              </CardHeader>
              <CardContent>
                <UnitPlanForm
                  showLongRangePlanSelector
                  allLongRangePlans={longRangePlans}
                  longRangePlan={null}
                  onCancel={() => {}}
                  onSubmit={(data) => {
                    addBatchOperation('unit', data);
                  }}
                />
              </CardContent>
            </Card>

            <Card>
              <CardHeader>
                <CardTitle>Quick Add Lesson Plan</CardTitle>
                <CardDescription>Add a lesson plan to the batch queue</CardDescription>
              </CardHeader>
              <CardContent>
                <LessonPlanForm
                  showUnitPlanSelector
                  allUnitPlans={unitPlans}
                  unitPlan={null}
                  onCancel={() => {}}
                  onSubmit={(data) => {
                    addBatchOperation('lesson', data);
                  }}
                />
              </CardContent>
            </Card>
          </div>
        </TabsContent>

        <TabsContent className="space-y-6" value="templates">
          <Card>
            <CardHeader>
              <CardTitle>Form Templates</CardTitle>
              <CardDescription>
                Generate and download template files for bulk data entry
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid gap-4 md:grid-cols-2">
                <div className="p-4 border rounded-lg">
                  <h3 className="font-medium mb-2">Unit Plan Template</h3>
                  <p className="text-sm text-gray-600 mb-4">
                    Download a JSON template for creating multiple unit plans
                  </p>
                  <Button
                    className="w-full"
                    variant="outline"
                    onClick={() => {
 generateTemplate('unit'); 
}}
                  >
                    <Download className="h-4 w-4 mr-2" />
                    Download Unit Template
                  </Button>
                </div>

                <div className="p-4 border rounded-lg">
                  <h3 className="font-medium mb-2">Lesson Plan Template</h3>
                  <p className="text-sm text-gray-600 mb-4">
                    Download a JSON template for creating multiple lesson plans
                  </p>
                  <Button
                    className="w-full"
                    variant="outline"
                    onClick={() => {
 generateTemplate('lesson'); 
}}
                  >
                    <Download className="h-4 w-4 mr-2" />
                    Download Lesson Template
                  </Button>
                </div>
              </div>

              <div className="border-t pt-4">
                <h3 className="font-medium mb-2">Template Instructions</h3>
                <div className="text-sm text-gray-600 space-y-2">
                  <p>1. Download the appropriate template file</p>
                  <p>2. Edit the JSON file with your planning data</p>
                  <p>3. Use the Import tab to upload your completed file</p>
                  <p>4. All entries will be validated before processing</p>
                </div>
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent className="space-y-6" value="import">
          <Card>
            <CardHeader>
              <CardTitle>Import & Export Data</CardTitle>
              <CardDescription>
                Import curriculum planning data from external sources
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div>
                <Label htmlFor="file-import">Import JSON File</Label>
                <Input
                  accept=".json"
                  className="mt-2"
                  id="file-import"
                  type="file"
                  onChange={(e): void => { void handleFileImport(e); }}
                />
                <p className="text-sm text-gray-600 mt-1">
                  Upload a JSON file containing unit plans or lesson plans
                </p>
              </div>

              <div className="border-t pt-4">
                <h3 className="font-medium mb-2">Supported Formats</h3>
                <div className="text-sm text-gray-600 space-y-1">
                  <p>• JSON files with array of unit plan or lesson plan objects</p>
                  <p>• Files must match the expected schema structure</p>
                  <p>• All imported data will be validated before processing</p>
                  <p>• Invalid entries will be flagged for review</p>
                </div>
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent className="space-y-6" value="wizard">
          <Card>
            <CardHeader>
              <CardTitle>Curriculum Setup Wizard</CardTitle>
              <CardDescription>Guided setup for comprehensive curriculum planning</CardDescription>
            </CardHeader>
            <CardContent>
              <div className="text-center py-8">
                <Wand2 className="h-12 w-12 mx-auto text-gray-400 mb-4" />
                <h3 className="text-lg font-medium text-gray-900 mb-2">Setup Wizard Coming Soon</h3>
                <p className="text-gray-600 mb-4">
                  The curriculum setup wizard will guide you through creating a complete year-long
                  planning structure with automated workflows.
                </p>
                <Button disabled variant="outline">
                  Launch Wizard
                </Button>
              </div>
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
}

import { Plus, Trash2 } from 'lucide-react';
import React, { useState, useEffect } from 'react';

import { useLanguage } from '../../contexts/LanguageContext';
import type { UnitPlan, CurriculumExpectation } from '../../hooks/useETFOPlanning';
import { BilingualTextInput } from '../BilingualTextInput';
import ExpectationSelector from '../planning/ExpectationSelector';
import RichTextEditor from '../RichTextEditor';
import { Button } from '../ui/Button';
import { Input } from '../ui/Input';
import { Label } from '../ui/Label';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '../ui/tabs';
// import { Textarea } from '../ui/Textarea';
import { InfoTooltip } from '../ui/Tooltip';

export interface LessonPlanFormData {
  title: string;
  titleFr?: string;
  unitPlanId: string;
  date: string;
  duration: number;
  // Three-part lesson structure (ETFO standard)
  mindsOn?: string;
  mindsOnFr?: string;
  action?: string;
  actionFr?: string;
  consolidation?: string;
  consolidationFr?: string;
  // Planning details
  learningGoals?: string;
  learningGoalsFr?: string;
  materials: string[];
  grouping?: string;
  // Differentiation
  accommodations: string[];
  modifications: string[];
  extensions: string[];
  // Assessment
  assessmentType?: 'diagnostic' | 'formative' | 'summative';
  assessmentNotes?: string;
  assessmentNotesFr?: string;
  // Substitute teacher friendly
  isSubFriendly: boolean;
  subNotes?: string;
  subNotesFr?: string;
  // Expectations
  expectationIds: string[];
}

interface LessonPlanFormProps {
  initialData?: Partial<LessonPlanFormData>;
  unitPlan?: UnitPlan | null;
  allUnitPlans?: UnitPlan[];
  unitExpectations?: CurriculumExpectation[];
  onSubmit: (data: LessonPlanFormData) => void;
  onCancel?: () => void;
  isSubmitting?: boolean;
  showUnitPlanSelector?: boolean;
}

export default function LessonPlanForm({
  initialData,
  unitPlan,
  allUnitPlans = [],
  unitExpectations: _unitExpectations = [],
  onSubmit,
  onCancel,
  isSubmitting = false,
  showUnitPlanSelector = false,
}: LessonPlanFormProps): React.ReactElement {
  const { t } = useLanguage();
  const [formData, setFormData] = useState<LessonPlanFormData>({
    title: '',
    titleFr: '',
    unitPlanId: unitPlan?.id ?? '',
    date: new Date().toISOString().split('T')[0],
    duration: 60,
    mindsOn: '',
    mindsOnFr: '',
    action: '',
    actionFr: '',
    consolidation: '',
    consolidationFr: '',
    learningGoals: '',
    learningGoalsFr: '',
    materials: [''],
    grouping: 'whole class',
    accommodations: [''],
    modifications: [''],
    extensions: [''],
    assessmentType: 'formative',
    assessmentNotes: '',
    assessmentNotesFr: '',
    isSubFriendly: true,
    subNotes: '',
    subNotesFr: '',
    expectationIds: [],
    ...initialData,
  });

  // Validation state
  const [errors, setErrors] = useState<Record<string, string>>({});

  // Update form data when initialData changes
  useEffect(() => {
    return () => { // Cleanup
    };

    if (initialData !== undefined) {
      setFormData((prev) => ({ ...prev, ...initialData }));
    }
  }, [initialData]);

  // Array manipulation helpers
  const addMaterial = (): void => {
    setFormData({ ...formData, materials: [...formData.materials, ''] });
  };

  const updateMaterial = (index: number, value: string): void => {
    const updated = [...formData.materials];
    updated[index] = value;
    setFormData({ ...formData, materials: updated });
  };

  const removeMaterial = (index: number): void => {
    if (formData.materials.length > 1) {
      setFormData({
        ...formData,
        materials: formData.materials.filter((_, i) => i !== index),
      });
    }
  };

  const addAccommodation = (): void => {
    setFormData({ ...formData, accommodations: [...formData.accommodations, ''] });
  };

  const updateAccommodation = (index: number, value: string): void => {
    const updated = [...formData.accommodations];
    updated[index] = value;
    setFormData({ ...formData, accommodations: updated });
  };

  const removeAccommodation = (index: number): void => {
    if (formData.accommodations.length > 1) {
      setFormData({
        ...formData,
        accommodations: formData.accommodations.filter((_, i) => i !== index),
      });
    }
  };

  const addModification = (): void => {
    setFormData({ ...formData, modifications: [...formData.modifications, ''] });
  };

  const updateModification = (index: number, value: string): void => {
    const updated = [...formData.modifications];
    updated[index] = value;
    setFormData({ ...formData, modifications: updated });
  };

  const removeModification = (index: number): void => {
    if (formData.modifications.length > 1) {
      setFormData({
        ...formData,
        modifications: formData.modifications.filter((_, i) => i !== index),
      });
    }
  };

  const addExtension = (): void => {
    setFormData({ ...formData, extensions: [...formData.extensions, ''] });
  };

  const updateExtension = (index: number, value: string): void => {
    const updated = [...formData.extensions];
    updated[index] = value;
    setFormData({ ...formData, extensions: updated });
  };

  const removeExtension = (index: number): void => {
    if (formData.extensions.length > 1) {
      setFormData({
        ...formData,
        extensions: formData.extensions.filter((_, i) => i !== index),
      });
    }
  };

  // Form validation
  const validateForm = (): boolean => {
    const newErrors: Record<string, string> = {};

    if (formData.title.trim() === '') {
      newErrors.title = 'Lesson title is required';
    }

    if (formData.unitPlanId === '') {
      newErrors.unitPlanId = 'Unit plan selection is required';
    }

    if (formData.date === '') {
      newErrors.date = 'Date is required';
    }

    if (formData.duration <= 0) {
      newErrors.duration = 'Duration must be greater than 0';
    }

    if (formData.expectationIds.length === 0) {
      newErrors.expectationIds = 'At least one curriculum expectation must be selected';
    }

    // Validate that at least one of the three lesson parts has content
    if ((formData.mindsOn?.trim() === '' || formData.mindsOn === undefined) && (formData.action?.trim() === '' || formData.action === undefined) && (formData.consolidation?.trim() === '' || formData.consolidation === undefined)) {
      newErrors.lessonStructure =
        'At least one lesson component (Minds On, Action, or Consolidation) must have content';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e: React.FormEvent): void => {
    e.preventDefault();

    if (validateForm()) {
      // Clean up empty array entries before submitting
      const cleanedData = {
        ...formData,
        materials: formData.materials.filter((m) => m.trim() !== ''),
        accommodations: formData.accommodations.filter((a) => a.trim() !== ''),
        modifications: formData.modifications.filter((m) => m.trim() !== ''),
        extensions: formData.extensions.filter((_e) => _e.trim() !== ''),
      };

      onSubmit(cleanedData);
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <Tabs className="space-y-4" defaultValue="overview">
        <TabsList className="grid w-full grid-cols-4">
          <TabsTrigger value="overview">Overview</TabsTrigger>
          <TabsTrigger value="lesson-structure">Lesson Structure</TabsTrigger>
          <TabsTrigger value="differentiation">Differentiation</TabsTrigger>
          <TabsTrigger value="assessment">Assessment</TabsTrigger>
        </TabsList>

        <TabsContent className="space-y-6 mt-4" value="overview">
          {/* Basic Information */}
          <div>
            <h4 className="text-md font-medium text-gray-900 mb-3">Basic Information</h4>
            <div className="space-y-4">
              {showUnitPlanSelector && (
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Unit Plan *
                  </label>
                  <select
                    required
                    className={`w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 ${
                      errors.unitPlanId ? 'border-red-500' : ''
                    }`}
                    value={formData.unitPlanId}
                    onChange={(e) => {
 setFormData({ ...formData, unitPlanId: e.target.value }); 
}}
                  >
                    <option value="">Select a unit plan...</option>
                    {allUnitPlans.map((plan, _index) => (
                      <option key={plan.id} value={plan.id}>
                        {plan.title}
                      </option>
                    ))}
                  </select>
                  {errors.unitPlanId && (
                    <p className="mt-1 text-sm text-red-600">{errors.unitPlanId}</p>
                  )}
                </div>
              )}

              <div>
                <BilingualTextInput
                  required
                  label={`${t('lesson_plan')  } ${  t('title')}`}
                  placeholderEn="Enter lesson title..."
                  placeholderFr="Entrez le titre de la leçon..."
                  valueEn={formData.title}
                  valueFr={formData.titleFr ?? ''}
                  onChangeEn={(value: string) => {
 setFormData({ ...formData, title: value }); 
}}
                  onChangeFr={(value: string) => {
 setFormData({ ...formData, titleFr: value }); 
}}
                />
                {errors.title && <p className="mt-1 text-sm text-red-600">{errors.title}</p>}
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div>
                  <Label htmlFor="date">Date *</Label>
                  <Input
                    required
                    className={errors.date ? 'border-red-500' : ''}
                    id="date"
                    type="date"
                    value={formData.date}
                    onChange={(e) => {
 setFormData({ ...formData, date: e.target.value }); 
}}
                  />
                  {errors.date && <p className="mt-1 text-sm text-red-600">{errors.date}</p>}
                </div>
                <div>
                  <Label htmlFor="duration">Duration (minutes) *</Label>
                  <Input
                    required
                    className={errors.duration ? 'border-red-500' : ''}
                    id="duration"
                    min="1"
                    type="number"
                    value={formData.duration}
                    onChange={(e) => {
 setFormData({ ...formData, duration: parseInt(e.target.value, 10) || 0 }); 
}
                    }
                  />
                  {errors.duration && (
                    <p className="mt-1 text-sm text-red-600">{errors.duration}</p>
                  )}
                </div>
                <div>
                  <Label htmlFor="grouping">Grouping Strategy</Label>
                  <select
                    className="w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500"
                    id="grouping"
                    value={formData.grouping ?? ''}
                    onChange={(e) => {
 setFormData({ ...formData, grouping: e.target.value }); 
}}
                  >
                    <option value="whole class">Whole Class</option>
                    <option value="small group">Small Group</option>
                    <option value="pairs">Pairs</option>
                    <option value="individual">Individual</option>
                    <option value="mixed">Mixed</option>
                  </select>
                </div>
              </div>

              <div>
                <BilingualTextInput
                  multiline
                  label={t('learning_goals')}
                  placeholderEn="What will students learn in this lesson?"
                  placeholderFr="Que vont apprendre les élèves dans cette leçon?"
                  rows={3}
                  valueEn={formData.learningGoals ?? ''}
                  valueFr={formData.learningGoalsFr ?? ''}
                  onChangeEn={(value) => {
 setFormData({ ...formData, learningGoals: value }); 
}}
                  onChangeFr={(value) => {
 setFormData({ ...formData, learningGoalsFr: value }); 
}}
                />
              </div>

              <div>
                <Label htmlFor="input">Materials & Resources</Label>
                <div className="space-y-2 mt-2">
                  {formData.materials.map((material, index) => (
                    <div key={index} className="flex gap-2">
                      <Input
                        placeholder="Required material or resource..."
                        type="text"
                        value={material}
                        onChange={(e) => {
 updateMaterial(index, e.target.value); 
}}
                      />
                      <Button
                        disabled={formData.materials.length === 1}
                        size="sm"
                        type="button"
                        variant="ghost"
                        onClick={() => {
 removeMaterial(index); 
}}
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    </div>
                  ))}
                  <Button
                    className="w-full"
                    size="sm"
                    type="button"
                    variant="outline"
                    onClick={addMaterial}
                  >
                    <Plus className="h-4 w-4 mr-2" />
                    Add Material
                  </Button>
                </div>
              </div>

              <div>
                <ExpectationSelector
                  className={errors.expectationIds ? 'border-red-500' : ''}
                  grade={unitPlan?.longRangePlan?.grade}
                  label="Curriculum Expectations *"
                  placeholder="Select expectations for this lesson..."
                  selectedIds={formData.expectationIds}
                  subject={unitPlan?.longRangePlan?.subject}
                  onChange={(ids) => {
 setFormData({ ...formData, expectationIds: ids }); 
}}
                />
                {errors.expectationIds && (
                  <p className="mt-1 text-sm text-red-600">{errors.expectationIds}</p>
                )}
                {errors.lessonStructure && (
                  <p className="mt-1 text-sm text-red-600">{errors.lessonStructure}</p>
                )}
              </div>
            </div>
          </div>
        </TabsContent>

        <TabsContent className="space-y-6 mt-4" value="lesson-structure">
          <div className="space-y-6">
            <div>
              <Label htmlFor="input">Minds On (Introduction/Hook)</Label>
              <RichTextEditor
                value={formData.mindsOn ?? ''}
                onChange={(value) => {
 setFormData({ ...formData, mindsOn: value }); 
}}
              />
            </div>

            <div>
              <Label htmlFor="input">Minds On (French)</Label>
              <RichTextEditor
                value={formData.mindsOnFr ?? ''}
                onChange={(value) => {
 setFormData({ ...formData, mindsOnFr: value }); 
}}
              />
            </div>

            <div>
              <Label htmlFor="input">Action (Main Learning Activities)</Label>
              <RichTextEditor
                value={formData.action ?? ''}
                onChange={(value) => {
 setFormData({ ...formData, action: value }); 
}}
              />
            </div>

            <div>
              <Label htmlFor="input">Action (French)</Label>
              <RichTextEditor
                value={formData.actionFr ?? ''}
                onChange={(value) => {
 setFormData({ ...formData, actionFr: value }); 
}}
              />
            </div>

            <div>
              <Label htmlFor="input">Consolidation (Closure/Assessment)</Label>
              <RichTextEditor
                value={formData.consolidation ?? ''}
                onChange={(value) => {
 setFormData({ ...formData, consolidation: value }); 
}}
              />
            </div>

            <div>
              <Label htmlFor="input">Consolidation (French)</Label>
              <RichTextEditor
                value={formData.consolidationFr ?? ''}
                onChange={(value) => {
 setFormData({ ...formData, consolidationFr: value }); 
}}
              />
            </div>
          </div>
        </TabsContent>

        <TabsContent className="space-y-6 mt-4" value="differentiation">
          <div>
            <Label htmlFor="input">Accommodations</Label>
            <p className="text-sm text-gray-600 mb-2">
              Changes to how students access learning (without changing expectations)
            </p>
            <div className="space-y-2">
              {formData.accommodations.map((accommodation, index) => (
                <div key={index} className="flex gap-2">
                  <Input
                    placeholder="Accommodation strategy..."
                    type="text"
                    value={accommodation}
                    onChange={(e) => {
 updateAccommodation(index, e.target.value); 
}}
                  />
                  <Button
                    disabled={formData.accommodations.length === 1}
                    size="sm"
                    type="button"
                    variant="ghost"
                    onClick={() => {
 removeAccommodation(index); 
}}
                  >
                    <Trash2 className="h-4 w-4" />
                  </Button>
                </div>
              ))}
              <Button
                className="w-full"
                size="sm"
                type="button"
                variant="outline"
                onClick={addAccommodation}
              >
                <Plus className="h-4 w-4 mr-2" />
                Add Accommodation
              </Button>
            </div>
          </div>

          <div>
            <Label htmlFor="input">Modifications</Label>
            <p className="text-sm text-gray-600 mb-2">
              Changes to curriculum expectations or learning goals
            </p>
            <div className="space-y-2">
              {formData.modifications.map((modification, index) => (
                <div key={index} className="flex gap-2">
                  <Input
                    placeholder="Modification strategy..."
                    type="text"
                    value={modification}
                    onChange={(e) => {
 updateModification(index, e.target.value); 
}}
                  />
                  <Button
                    disabled={formData.modifications.length === 1}
                    size="sm"
                    type="button"
                    variant="ghost"
                    onClick={() => {
 removeModification(index); 
}}
                  >
                    <Trash2 className="h-4 w-4" />
                  </Button>
                </div>
              ))}
              <Button
                className="w-full"
                size="sm"
                type="button"
                variant="outline"
                onClick={addModification}
              >
                <Plus className="h-4 w-4 mr-2" />
                Add Modification
              </Button>
            </div>
          </div>

          <div>
            <Label htmlFor="input">Extensions</Label>
            <p className="text-sm text-gray-600 mb-2">
              Additional challenges for students who finish early or need enrichment
            </p>
            <div className="space-y-2">
              {formData.extensions.map((extension, index) => (
                <div key={index} className="flex gap-2">
                  <Input
                    placeholder="Extension activity..."
                    type="text"
                    value={extension}
                    onChange={(e) => {
 updateExtension(index, e.target.value); 
}}
                  />
                  <Button
                    disabled={formData.extensions.length === 1}
                    size="sm"
                    type="button"
                    variant="ghost"
                    onClick={() => {
 removeExtension(index); 
}}
                  >
                    <Trash2 className="h-4 w-4" />
                  </Button>
                </div>
              ))}
              <Button
                className="w-full"
                size="sm"
                type="button"
                variant="outline"
                onClick={addExtension}
              >
                <Plus className="h-4 w-4 mr-2" />
                Add Extension
              </Button>
            </div>
          </div>
        </TabsContent>

        <TabsContent className="space-y-6 mt-4" value="assessment">
          <div>
            <div className="flex items-center">
              <Label htmlFor="assessmentType">Assessment Type</Label>
              <InfoTooltip content="Choose the primary purpose of assessment for this lesson. You can use multiple types throughout the lesson." />
            </div>
            <select
              className="w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 mt-2"
              id="assessmentType"
              value={formData.assessmentType || ''}
              onChange={(e) => {
 setFormData({
                  ...formData,
                  assessmentType: e.target.value as 'diagnostic' | 'formative' | 'summative',
                }); 
}
              }
            >
              <option value="diagnostic">
                Diagnostic - Assessment FOR Learning (Before/Beginning)
              </option>
              <option value="formative">Formative - Assessment AS Learning (During)</option>
              <option value="summative">Summative - Assessment OF Learning (After/End)</option>
            </select>
            <div className="mt-2 text-sm text-gray-600">
              {formData.assessmentType === 'diagnostic' && (
                <p className="bg-blue-50 p-3 rounded-md border border-blue-200">
                  <strong>Diagnostic Assessment:</strong> Used at the beginning to determine what
                  students already know and identify learning needs.
                  <br />
                  <strong>Examples:</strong> KWL charts, pre-tests, class discussions, entrance
                  tickets, thumbs up/down checks
                </p>
              )}
              {formData.assessmentType === 'formative' && (
                <p className="bg-green-50 p-3 rounded-md border border-green-200">
                  <strong>Formative Assessment:</strong> Ongoing assessment during learning to
                  provide feedback and adjust teaching. Students actively assess their own learning.
                  <br />
                  <strong>Examples:</strong> Exit tickets, peer feedback, self-reflection journals,
                  mini-whiteboards, think-pair-share, observation checklists
                </p>
              )}
              {formData.assessmentType === 'summative' && (
                <p className="bg-purple-50 p-3 rounded-md border border-purple-200">
                  <strong>Summative Assessment:</strong> Used at the end to evaluate student
                  achievement of learning goals and assign grades.
                  <br />
                  <strong>Examples:</strong> Unit tests, final projects, presentations, portfolios,
                  performance tasks, end-of-term assignments
                </p>
              )}
            </div>
          </div>

          <div>
            <div className="flex items-center">
              <Label htmlFor="input">Success Criteria & Assessment Strategies</Label>
              <InfoTooltip content="Clear, specific statements that describe what success looks like. Written in student-friendly language starting with 'I can...'" />
            </div>
            <BilingualTextInput
              multiline
              className="mt-2"
              label=""
              placeholderEn="Success Criteria (I can statements):
• I can identify the main idea of a text
• I can use evidence from the text to support my answer
• I can work cooperatively with my group

Assessment Strategies:
• Observation during group work
• Exit ticket with key question
• Self-assessment checklist"
              placeholderFr="Critères de réussite (Je peux...):
• Je peux identifier l'idée principale d'un texte
• Je peux utiliser des preuves du texte
• Je peux travailler en coopération

Stratégies d'évaluation:
• Observation pendant le travail de groupe
• Billet de sortie avec question clé
• Liste d'auto-évaluation"
              rows={6}
              valueEn={formData.assessmentNotes ?? ''}
              valueFr={formData.assessmentNotesFr ?? ''}
              onChangeEn={(value) => {
 setFormData({ ...formData, assessmentNotes: value }); 
}}
              onChangeFr={(value) => {
 setFormData({ ...formData, assessmentNotesFr: value }); 
}}
            />
            <p className="mt-1 text-xs text-gray-500">
              Include both success criteria and the specific assessment strategies you&apos;ll use
              to gather evidence of learning.
            </p>
          </div>

          <div>
            <Label htmlFor="input">Substitute Teacher Ready</Label>
            <div className="mt-2 space-y-4">
              <label className="flex items-center space-x-2">
                <input
                  checked={formData.isSubFriendly}
                  className="rounded"
                  type="checkbox"
                  onChange={(e) => {
 setFormData({ ...formData, isSubFriendly: e.target.checked }); 
}}
                />
                <span className="text-sm">This lesson is suitable for a substitute teacher</span>
              </label>

              {formData.isSubFriendly && (
                <div>
                  <BilingualTextInput
                    multiline
                    className="mt-2"
                    label="Notes for Substitute Teacher"
                    placeholderEn="Special instructions, classroom management tips, or additional context for a substitute teacher..."
                    placeholderFr="Instructions spéciales, conseils de gestion de classe, ou contexte additionnel pour un suppléant..."
                    rows={3}
                    valueEn={formData.subNotes ?? ''}
                    valueFr={formData.subNotesFr ?? ''}
                    onChangeEn={(value) => {
 setFormData({ ...formData, subNotes: value }); 
}}
                    onChangeFr={(value) => {
 setFormData({ ...formData, subNotesFr: value }); 
}}
                  />
                </div>
              )}
            </div>
          </div>
        </TabsContent>
      </Tabs>

      <div className="flex justify-end space-x-3 mt-6 pt-6 border-t">
        {onCancel && (
          <Button aria-label="Click button" onClick={onCancel}>
            Cancel
          </Button>
        )}
        <Button disabled={isSubmitting} type="submit">
          {isSubmitting ? 'Saving...' : initialData !== undefined ? 'Update Lesson Plan' : 'Create Lesson Plan'}
        </Button>
      </div>
    </form>
  );
}

import { Plus, Trash2, Sparkles } from 'lucide-react';
import React, { useState, useEffect } from 'react';

import { useLanguage } from '../../contexts/LanguageContext';
import type { LongRangePlan, CurriculumExpectation } from '../../hooks/useETFOPlanning';
import { AIUnitPlanPanel } from '../ai/AIUnitPlanPanel';
import { BilingualTextInput } from '../BilingualTextInput';
import ExpectationSelector from '../planning/ExpectationSelector';
import RichTextEditor from '../RichTextEditor';
import { Button } from '../ui/Button';
import { Input } from '../ui/Input';
import { Label } from '../ui/Label';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '../ui/tabs';
import { Textarea } from '../ui/Textarea';
import { InfoTooltip } from '../ui/Tooltip';

// Extended UnitPlan type with all ETFO fields including bilingual support
export interface UnitPlanFormData {
  title: string;
  titleFr?: string;
  description: string;
  descriptionFr?: string;
  bigIdeas: string;
  bigIdeasFr?: string;
  essentialQuestions: string[];
  essentialQuestionsFr?: string[];
  startDate: string;
  endDate: string;
  estimatedHours: number;
  assessmentPlan: string;
  assessmentPlanFr?: string;
  successCriteria: string[];
  successCriteriaFr?: string[];
  expectationIds: string[];
  longRangePlanId: string;
  // Additional ETFO fields
  crossCurricularConnections: string;
  crossCurricularConnectionsFr?: string;
  learningSkills: string[];
  learningSkillsFr?: string[];
  culminatingTask: string;
  culminatingTaskFr?: string;
  keyVocabulary: string[];
  keyVocabularyFr?: string[];
  priorKnowledge: string;
  priorKnowledgeFr?: string;
  parentCommunicationPlan: string;
  parentCommunicationPlanFr?: string;
  fieldTripsAndGuestSpeakers: string;
  fieldTripsAndGuestSpeakersFr?: string;
  differentiationStrategies: {
    forStruggling: string[];
    forAdvanced: string[];
    forELL: string[];
    forIEP: string[];
  };
  differentiationStrategiesFr?: {
    forStruggling: string[];
    forAdvanced: string[];
    forELL: string[];
    forIEP: string[];
  };
  indigenousPerspectives: string;
  indigenousPerspectivesFr?: string;
  environmentalEducation: string;
  environmentalEducationFr?: string;
  socialJusticeConnections: string;
  socialJusticeConnectionsFr?: string;
  technologyIntegration: string;
  technologyIntegrationFr?: string;
  communityConnections: string;
  communityConnectionsFr?: string;
}

interface UnitPlanFormProps {
  initialData?: Partial<UnitPlanFormData>;
  longRangePlan?: LongRangePlan | null;
  allLongRangePlans?: LongRangePlan[];
  curriculumExpectations?: CurriculumExpectation[];
  onSubmit: (data: UnitPlanFormData) => void;
  onCancel?: () => void;
  isSubmitting?: boolean;
  showLongRangePlanSelector?: boolean;
}

export default function UnitPlanForm({
  initialData,
  longRangePlan,
  allLongRangePlans = [],
  curriculumExpectations = [],
  onSubmit,
  onCancel,
  isSubmitting = false,
  showLongRangePlanSelector = false,
}: UnitPlanFormProps): React.ReactElement {
  const { t } = useLanguage();
  const [_showBilingualFields, _setShowBilingualFields] = useState(false);

  const [formData, setFormData] = useState<UnitPlanFormData>({
    title: '',
    titleFr: '',
    description: '',
    descriptionFr: '',
    bigIdeas: '',
    bigIdeasFr: '',
    essentialQuestions: [''],
    essentialQuestionsFr: [''],
    startDate: '',
    endDate: '',
    estimatedHours: 20,
    assessmentPlan: '',
    assessmentPlanFr: '',
    successCriteria: [''],
    successCriteriaFr: [''],
    expectationIds: [],
    longRangePlanId: longRangePlan?.id ?? '',
    // Additional ETFO fields
    crossCurricularConnections: '',
    crossCurricularConnectionsFr: '',
    learningSkills: [],
    learningSkillsFr: [],
    culminatingTask: '',
    culminatingTaskFr: '',
    keyVocabulary: [''],
    keyVocabularyFr: [''],
    priorKnowledge: '',
    priorKnowledgeFr: '',
    parentCommunicationPlan: '',
    parentCommunicationPlanFr: '',
    fieldTripsAndGuestSpeakers: '',
    fieldTripsAndGuestSpeakersFr: '',
    differentiationStrategies: {
      forStruggling: [''],
      forAdvanced: [''],
      forELL: [''],
      forIEP: [''],
    },
    differentiationStrategiesFr: {
      forStruggling: [''],
      forAdvanced: [''],
      forELL: [''],
      forIEP: [''],
    },
    indigenousPerspectives: '',
    indigenousPerspectivesFr: '',
    environmentalEducation: '',
    environmentalEducationFr: '',
    socialJusticeConnections: '',
    socialJusticeConnectionsFr: '',
    technologyIntegration: '',
    technologyIntegrationFr: '',
    communityConnections: '',
    communityConnectionsFr: '',
    ...initialData,
  });

  // Validation state
  const [errors, setErrors] = useState<Record<string, string>>({});

  // Update form data when initialData changes
  useEffect(() => {
    return () => { // Cleanup
    };

    if (initialData) {
      setFormData(prev => ({ ...prev, ...initialData }));
    }
  }, [initialData]);

  // Array manipulation helpers
  const addEssentialQuestion = (): void => {
    setFormData({ ...formData, essentialQuestions: [...formData.essentialQuestions, ''] });
  };

  const updateEssentialQuestion = (index: number, value: string): void => {
    const updated = [...formData.essentialQuestions];
    updated[index] = value;
    setFormData({ ...formData, essentialQuestions: updated });
  };

  const removeEssentialQuestion = (index: number): void => {
    if (formData.essentialQuestions.length > 1) {
      setFormData({
        ...formData,
        essentialQuestions: formData.essentialQuestions.filter((_, i) => i !== index),
      });
    }
  };

  const addSuccessCriteria = (): void => {
    setFormData({ ...formData, successCriteria: [...formData.successCriteria, ''] });
  };

  const updateSuccessCriteria = (index: number, value: string): void => {
    const updated = [...formData.successCriteria];
    updated[index] = value;
    setFormData({ ...formData, successCriteria: updated });
  };

  const removeSuccessCriteria = (index: number): void => {
    if (formData.successCriteria.length > 1) {
      setFormData({
        ...formData,
        successCriteria: formData.successCriteria.filter((_, i) => i !== index),
      });
    }
  };

  const addKeyVocabulary = (): void => {
    setFormData({ ...formData, keyVocabulary: [...formData.keyVocabulary, ''] });
  };

  const updateKeyVocabulary = (index: number, value: string): void => {
    const updated = [...formData.keyVocabulary];
    updated[index] = value;
    setFormData({ ...formData, keyVocabulary: updated });
  };

  const removeKeyVocabulary = (index: number): void => {
    if (formData.keyVocabulary.length > 1) {
      setFormData({
        ...formData,
        keyVocabulary: formData.keyVocabulary.filter((_, i) => i !== index),
      });
    }
  };

  // Differentiation strategy helpers
  const addDifferentiationStrategy = (category: keyof typeof formData.differentiationStrategies): void => {
    setFormData({
      ...formData,
      differentiationStrategies: {
        ...formData.differentiationStrategies,
        [category]: [...formData.differentiationStrategies[category], ''],
      },
    });
  };

  const updateDifferentiationStrategy = (
    category: keyof typeof formData.differentiationStrategies,
    index: number,
    value: string
  ): void => {
    const updated = [...formData.differentiationStrategies[category]];
    updated[index] = value;
    setFormData({
      ...formData,
      differentiationStrategies: {
        ...formData.differentiationStrategies,
        [category]: updated,
      },
    });
  };

  const removeDifferentiationStrategy = (
    category: keyof typeof formData.differentiationStrategies,
    index: number
  ): void => {
    if (formData.differentiationStrategies[category].length > 1) {
      setFormData({
        ...formData,
        differentiationStrategies: {
          ...formData.differentiationStrategies,
          [category]: formData.differentiationStrategies[category].filter((_, i) => i !== index),
        },
      });
    }
  };

  // Form validation
  const validateForm = (): boolean => {
    const newErrors: Record<string, string> = {};

    if (!formData.title.trim()) {
      newErrors.title = 'Unit title is required';
    }

    if (!formData.longRangePlanId) {
      newErrors.longRangePlanId = 'Long-range plan selection is required';
    }

    if (!formData.startDate) {
      newErrors.startDate = 'Start date is required';
    }

    if (!formData.endDate) {
      newErrors.endDate = 'End date is required';
    }

    if (formData.startDate && formData.endDate && formData.startDate >= formData.endDate) {
      newErrors.endDate = 'End date must be after start date';
    }

    if (formData.expectationIds.length === 0) {
      newErrors.expectationIds = 'At least one curriculum expectation must be selected';
    }

    if (formData.estimatedHours <= 0) {
      newErrors.estimatedHours = 'Estimated hours must be greater than 0';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e: React.FormEvent): void => {
    e.preventDefault();

    if (validateForm()) {
      // Clean up empty array entries before submitting
      const cleanedData = {
        ...formData,
        essentialQuestions: formData.essentialQuestions.filter(q => q.trim() !== ''),
        successCriteria: formData.successCriteria.filter(c => c.trim() !== ''),
        keyVocabulary: formData.keyVocabulary.filter(v => v.trim() !== ''),
        differentiationStrategies: {
          forStruggling: formData.differentiationStrategies.forStruggling.filter(s => s.trim() !== ''),
          forAdvanced: formData.differentiationStrategies.forAdvanced.filter(s => s.trim() !== ''),
          forELL: formData.differentiationStrategies.forELL.filter(s => s.trim() !== ''),
          forIEP: formData.differentiationStrategies.forIEP.filter(s => s.trim() !== ''),
        },
      };

      onSubmit(cleanedData);
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <Tabs className="space-y-4" defaultValue="overview">
        <TabsList className="grid w-full grid-cols-6">
          <TabsTrigger value="overview">Overview</TabsTrigger>
          <TabsTrigger className="gap-2" value="ai-assistant">
            <Sparkles className="h-4 w-4" />
            AI Assistant
          </TabsTrigger>
          <TabsTrigger value="planning">Planning</TabsTrigger>
          <TabsTrigger value="assessment">Assessment</TabsTrigger>
          <TabsTrigger value="differentiation">Differentiation</TabsTrigger>
          <TabsTrigger value="connections">Connections</TabsTrigger>
        </TabsList>

        <TabsContent className="space-y-6 mt-4" value="overview">
          {/* Basic Information */}
          <div>
            <h4 className="text-md font-medium text-gray-900 mb-3">Basic Information</h4>
            <div className="space-y-4">
              {showLongRangePlanSelector && (
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Long-Range Plan *
                  </label>
                  <select
                    required
                    className={`w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 ${
                      errors.longRangePlanId ? 'border-red-500' : ''
                    }`}
                    value={formData.longRangePlanId}
                    onChange={(e) => {
 setFormData({ ...formData, longRangePlanId: e.target.value }); 
}
                    }
                  >
                    <option value="">Select a long-range plan...</option>
                    {allLongRangePlans.map((plan, _index) => (
                      <option key={plan.id} value={plan.id}>
                        {plan.title} - {plan.subject} Grade {plan.grade}
                      </option>
                    ))}
                  </select>
                  {errors.longRangePlanId && (
                    <p className="mt-1 text-sm text-red-600">{errors.longRangePlanId}</p>
                  )}
                </div>
              )}

              <div>
                <BilingualTextInput
                  required
                  label={`${t('unit_plan')  } ${  t('title')}`}
                  placeholderEn="Enter unit title..."
                  placeholderFr="Entrez le titre de l'unité..."
                  valueEn={formData.title}
                  valueFr={formData.titleFr ?? ''}
                  onChangeEn={(value) => {
 setFormData({ ...formData, title: value }); 
}}
                  onChangeFr={(value) => {
 setFormData({ ...formData, titleFr: value }); 
}}
                />
                {errors.title && (
                  <p className="mt-1 text-sm text-red-600">{errors.title}</p>
                )}
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div>
                  <Label htmlFor="startDate">Start Date *</Label>
                  <Input
                    required
                    className={errors.startDate ? 'border-red-500' : ''}
                    id="startDate"
                    type="date"
                    value={formData.startDate}
                    onChange={(e) => {
 setFormData({ ...formData, startDate: e.target.value }); 
}}
                  />
                  {errors.startDate && (
                    <p className="mt-1 text-sm text-red-600">{errors.startDate}</p>
                  )}
                </div>
                <div>
                  <Label htmlFor="endDate">End Date *</Label>
                  <Input
                    required
                    className={errors.endDate ? 'border-red-500' : ''}
                    id="endDate"
                    type="date"
                    value={formData.endDate}
                    onChange={(e) => {
 setFormData({ ...formData, endDate: e.target.value }); 
}}
                  />
                  {errors.endDate && (
                    <p className="mt-1 text-sm text-red-600">{errors.endDate}</p>
                  )}
                </div>
                <div>
                  <Label htmlFor="estimatedHours">Estimated Hours</Label>
                  <Input
                    className={errors.estimatedHours ? 'border-red-500' : ''}
                    id="estimatedHours"
                    min="1"
                    type="number"
                    value={formData.estimatedHours}
                    onChange={(e) => {
 setFormData({ ...formData, estimatedHours: parseInt(e.target.value, 10) || 0 }); 
}
                    }
                  />
                  {errors.estimatedHours && (
                    <p className="mt-1 text-sm text-red-600">{errors.estimatedHours}</p>
                  )}
                </div>
              </div>

              <div>
                <BilingualTextInput
                  multiline
                  label={t('description')}
                  placeholderEn="Provide an overview of what this unit will cover..."
                  placeholderFr="Fournissez un aperçu de ce que cette unité couvrira..."
                  rows={3}
                  valueEn={formData.description}
                  valueFr={formData.descriptionFr ?? ''}
                  onChangeEn={(value) => {
 setFormData({ ...formData, description: value }); 
}}
                  onChangeFr={(value) => {
 setFormData({ ...formData, descriptionFr: value }); 
}}
                />
              </div>
            </div>
          </div>

          {/* Big Ideas */}
          <div>
            <Label htmlFor="input">Big Ideas & Enduring Understandings</Label>
            <RichTextEditor
              value={formData.bigIdeas}
              onChange={(value) => {
 setFormData({ ...formData, bigIdeas: value }); 
}}
            />
          </div>

          {/* Essential Questions */}
          <div>
            <Label htmlFor="input">Essential Questions</Label>
            <div className="space-y-2 mt-2">
              {formData.essentialQuestions.map((question, index) => (
                <div key={index} className="flex gap-2">
                  <Input
                    placeholder="What is an essential question that will guide learning?"
                    type="text"
                    value={question}
                    onChange={(e) => {
 updateEssentialQuestion(index, e.target.value); 
}}
                  />
                  <Button
                    disabled={formData.essentialQuestions.length === 1}
                    size="sm"
                    type="button"
                    variant="ghost"
                    onClick={() => {
 removeEssentialQuestion(index); 
}}
                  >
                    <Trash2 className="h-4 w-4" />
                  </Button>
                </div>
              ))}
              <Button
                className="w-full"
                size="sm"
                type="button"
                variant="outline"
                onClick={addEssentialQuestion}
              >
                <Plus className="h-4 w-4 mr-2" />
                Add Question
              </Button>
            </div>
          </div>
        </TabsContent>

        <TabsContent className="space-y-6 mt-4" value="ai-assistant">
          <AIUnitPlanPanel
            className="w-full"
            curriculumExpectations={curriculumExpectations
              .filter(exp => formData.expectationIds.includes(exp.id))
              .map(exp => ({
                id: exp.id,
                code: exp.code,
                description: exp.description,
                strand: exp.strand,
              }))}
            duration={2}
            grade={longRangePlan?.grade || 1}
            subject={longRangePlan?.subject ?? ''}
            unitTitle={formData.title}
            onSuggestionAccepted={(type, content) => {
              // Handle AI suggestions
              switch (type) {
                case 'bigIdeas':
                  setFormData({ ...formData, bigIdeas: content.join('\n\n') });
                  break;
                case 'essentialQuestions':
                  setFormData({ ...formData, essentialQuestions: content });
                  break;
                case 'vocabulary': {
                  const existingVocab = formData.keyVocabulary.filter(v => v.trim());
                  setFormData({ ...formData, keyVocabulary: [...existingVocab, ...content] });
                  break;
                }
              }
            }}
            onUnitGenerated={(plan) => {
              setFormData({
                ...formData,
                title: plan.title || formData.title,
                bigIdeas: plan.bigIdeas.join('\n\n') || formData.bigIdeas,
                essentialQuestions: plan.learningGoals || formData.essentialQuestions,
              });
            }}
          />
        </TabsContent>

        <TabsContent className="space-y-6 mt-4" value="planning">
          <div>
            <Label htmlFor="input">Key Vocabulary</Label>
            <div className="space-y-2 mt-2">
              {formData.keyVocabulary.map((term, index) => (
                <div key={index} className="flex gap-2">
                  <Input
                    placeholder="Important term or concept..."
                    type="text"
                    value={term}
                    onChange={(e) => {
 updateKeyVocabulary(index, e.target.value); 
}}
                  />
                  <Button
                    disabled={formData.keyVocabulary.length === 1}
                    size="sm"
                    type="button"
                    variant="ghost"
                    onClick={() => {
 removeKeyVocabulary(index); 
}}
                  >
                    <Trash2 className="h-4 w-4" />
                  </Button>
                </div>
              ))}
              <Button
                className="w-full"
                size="sm"
                type="button"
                variant="outline"
                onClick={addKeyVocabulary}
              >
                <Plus className="h-4 w-4 mr-2" />
                Add Term
              </Button>
            </div>
          </div>

          <div>
            <Label htmlFor="input">Prior Knowledge Requirements</Label>
            <Textarea
              className="mt-2"
              placeholder="What should students already know before starting this unit?"
              rows={3}
              value={formData.priorKnowledge}
              onChange={(e) => {
 setFormData({ ...formData, priorKnowledge: e.target.value }); 
}}
            />
          </div>

          <div>
            <ExpectationSelector
              className={errors.expectationIds ? 'border-red-500' : ''}
              grade={longRangePlan?.grade}
              label="Curriculum Expectations *"
              placeholder="Select curriculum expectations for this unit..."
              selectedIds={formData.expectationIds}
              subject={longRangePlan?.subject}
              onChange={(ids) => {
 setFormData({ ...formData, expectationIds: ids }); 
}}
            />
            {errors.expectationIds && (
              <p className="mt-1 text-sm text-red-600">{errors.expectationIds}</p>
            )}
          </div>

          <div>
            <Label htmlFor="input">Culminating Task Description</Label>
            <RichTextEditor
              value={formData.culminatingTask}
              onChange={(value) => {
 setFormData({ ...formData, culminatingTask: value }); 
}}
            />
          </div>
        </TabsContent>

        <TabsContent className="space-y-6 mt-4" value="assessment">
          <div>
            <div className="flex items-center">
              <Label htmlFor="input">Assessment Plan</Label>
              <InfoTooltip content="Describe how you will assess student learning throughout the unit. Include diagnostic, formative, and summative assessments." />
            </div>
            <RichTextEditor
              placeholder="Include a mix of assessment types:

Diagnostic Assessment (Beginning of Unit):
• Pre-assessment activity to gauge prior knowledge
• Student self-assessment survey
• Class discussion to identify misconceptions

Formative Assessment (Throughout Unit):
• Daily exit tickets
• Peer feedback on draft work
• Teacher observations with anecdotal notes
• Student reflection journals
• Mini-quizzes for understanding checks

Summative Assessment (End of Unit):
• Culminating project with rubric
• Unit test covering key concepts
• Performance task demonstrating skills
• Portfolio of student work"
              value={formData.assessmentPlan}
              onChange={(value) => {
 setFormData({ ...formData, assessmentPlan: value }); 
}}
            />
          </div>

          <div>
            <Label htmlFor="input">Learning Skills & Work Habits Focus</Label>
            <div className="grid grid-cols-2 gap-4 mt-2">
              {[
                'Responsibility',
                'Organization',
                'Independent Work',
                'Collaboration',
                'Initiative',
                'Self-Regulation',
              ].map((skill, _index) => (
                <label key={skill} className="flex items-center space-x-2">
                  <input
                    checked={formData.learningSkills.includes(skill)}
                    className="rounded"
                    type="checkbox"
                    onChange={(e) => {
                      if (e.target.checked) {
                        setFormData({
                          ...formData,
                          learningSkills: [...formData.learningSkills, skill],
                        });
                      } else {
                        setFormData({
                          ...formData,
                          learningSkills: formData.learningSkills.filter((s) => s !== skill),
                        });
                      }
                    }}
                  />
                  <span className="text-sm">{skill}</span>
                </label>
              ))}
            </div>
          </div>

          <div>
            <div className="flex items-center">
              <Label htmlFor="input">Success Criteria</Label>
              <InfoTooltip content="Clear statements that describe what students will know and be able to do by the end of the unit. Use student-friendly 'I can' statements." />
            </div>
            <p className="text-sm text-gray-600 mb-2">
              Write success criteria as &quot;I can&quot; statements that students can understand and use for self-assessment.
            </p>
            <div className="space-y-2 mt-2">
              {formData.successCriteria.map((criteria, index) => (
                <div key={index} className="flex gap-2">
                  <Input
                    placeholder="I can explain how ecosystems work together..."
                    type="text"
                    value={criteria}
                    onChange={(e) => {
 updateSuccessCriteria(index, e.target.value); 
}}
                  />
                  <Button
                    disabled={formData.successCriteria.length === 1}
                    size="sm"
                    type="button"
                    variant="ghost"
                    onClick={() => {
 removeSuccessCriteria(index); 
}}
                  >
                    <Trash2 className="h-4 w-4" />
                  </Button>
                </div>
              ))}
              <Button
                className="w-full"
                size="sm"
                type="button"
                variant="outline"
                onClick={addSuccessCriteria}
              >
                <Plus className="h-4 w-4 mr-2" />
                Add Success Criteria
              </Button>
            </div>
            <div className="mt-3 p-3 bg-gray-50 rounded-md border border-gray-200">
              <p className="text-xs text-gray-600">
                <strong>Examples of good success criteria:</strong><br />
                • I can identify the parts of an ecosystem<br />
                • I can explain how energy flows through a food chain<br />
                • I can create a diagram showing relationships in an ecosystem<br />
                • I can use scientific vocabulary when discussing ecosystems
              </p>
            </div>
          </div>
        </TabsContent>

