import { clsx } from 'clsx';
import React, { useState, useRef, useEffect, useCallback } from 'react';
import { createPortal } from 'react-dom';

import type { HelpTooltipProps } from '../../types/help';

export const HelpTooltip: React.FC<HelpTooltipProps> = ({
  content,
  position = 'top',
  trigger = 'hover',
  delay = 200,
  maxWidth = 300,
  children,
}): React.ReactElement => {
  const [isVisible, setIsVisible] = useState(false);
  const [tooltipPosition, setTooltipPosition] = useState({ top: 0, left: 0 });
  const triggerRef = useRef<HTMLElement>(null);
  const tooltipRef = useRef<HTMLDivElement>(null);
  const timeoutRef = useRef<NodeJS.Timeout>();

  // Calculate tooltip position
  const calculatePosition = useCallback((): void => {
    if (!triggerRef.current || !tooltipRef.current) {
return;
}

    const triggerRect = triggerRef.current.getBoundingClientRect();
    const tooltipRect = tooltipRef.current.getBoundingClientRect();
    const viewportWidth = window.innerWidth;
    const viewportHeight = window.innerHeight;

    let top = 0;
    let left = 0;

    switch (position) {
      case 'top':
        top = triggerRect.top - tooltipRect.height - 8;
        left = triggerRect.left + (triggerRect.width - tooltipRect.width) / 2;
        break;
      case 'bottom':
        top = triggerRect.bottom + 8;
        left = triggerRect.left + (triggerRect.width - tooltipRect.width) / 2;
        break;
      case 'left':
        top = triggerRect.top + (triggerRect.height - tooltipRect.height) / 2;
        left = triggerRect.left - tooltipRect.width - 8;
        break;
      case 'right':
        top = triggerRect.top + (triggerRect.height - tooltipRect.height) / 2;
        left = triggerRect.right + 8;
        break;
    }

    // Ensure tooltip stays within viewport
    if (left < 8) {
left = 8;
}
    if (left + tooltipRect.width > viewportWidth - 8) {
      left = viewportWidth - tooltipRect.width - 8;
    }
    if (top < 8) {
top = 8;
}
    if (top + tooltipRect.height > viewportHeight - 8) {
      top = viewportHeight - tooltipRect.height - 8;
    }

    setTooltipPosition({ top, left });
  }, [position]);

  const showTooltip = (): void => {
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
    }
    timeoutRef.current = setTimeout(() => {
      setIsVisible(true);
    }, delay);
  };

  const hideTooltip = (): void => {
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
    }
    setIsVisible(false);
  };

  useEffect((): void => {
    if (isVisible) {
      calculatePosition();
    }
  }, [isVisible, position, calculatePosition]);

  useEffect((): (() => void) => () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
    }, []) // eslint-disable-line react-hooks/exhaustive-deps

  // Clone the child element and add event handlers
  const triggerElement = React.cloneElement(children, {
    ref: triggerRef,
    ...(trigger === 'hover'
      ? {
          onMouseEnter: showTooltip,
          onMouseLeave: hideTooltip,
        }
      : {
          onClick: (): void => {
            if (isVisible) {
              hideTooltip();
            } else {
              showTooltip();
            }
          },
        }),
  });

  const getArrowClasses = (): string => {
    const base = 'absolute w-2 h-2 bg-gray-900 transform rotate-45';
    switch (position) {
      case 'top':
        return `${base} top-full left-1/2 -translate-x-1/2 -translate-y-1/2`;
      case 'bottom':
        return `${base} bottom-full left-1/2 -translate-x-1/2 translate-y-1/2`;
      case 'left':
        return `${base} left-full top-1/2 -translate-y-1/2 -translate-x-1/2`;
      case 'right':
        return `${base} right-full top-1/2 -translate-y-1/2 translate-x-1/2`;
      default:
        return base;
    }
  };

  return (
    <>
      {triggerElement}
      {isVisible &&
        createPortal(
          <div
            ref={tooltipRef}
            className={clsx(
              'fixed z-50 px-3 py-2 text-sm text-white bg-gray-900 rounded-lg shadow-lg',
              'transition-opacity duration-200',
            )}
            role="tooltip"
            style={{
              top: tooltipPosition.top,
              left: tooltipPosition.left,
              maxWidth,
            }}
          >
            {content}
            <div className={getArrowClasses()} />
          </div>,
          document.body,
        )}
    </>
  );
};

import React, { useState, useEffect, useCallback } from 'react';

import { useHelp } from '../../contexts/HelpContext';
import { useTutorials } from '../../hooks/useHelp';
import { Button } from '../ui/Button';
import { Modal } from '../ui/Modal';

import { TutorialOverlay } from './TutorialOverlay';

interface TutorialManagerProps {
  children: React.ReactNode;
}

export const TutorialManager: React.FC<TutorialManagerProps> = ({ children }): React.ReactElement => {
  const { state, startTutorial, nextTutorialStep, completeTutorial } = useHelp();
  const { getTutorial, getTutorialProgress } = useTutorials();
  const [showTutorialMenu, setShowTutorialMenu] = useState(false);

  // Get currently active tutorial
  const activeTutorialId = Object.keys(state.tutorialProgress)[0];
  const activeTutorial = activeTutorialId ? getTutorial(activeTutorialId) : null;
  const currentStepIndex = activeTutorialId ? state.tutorialProgress[activeTutorialId] : 0;
  const currentStep = activeTutorial?.steps[currentStepIndex] ?? null;
  const progress = activeTutorialId ? getTutorialProgress(activeTutorialId) : 0;

  // Handle tutorial completion
  const handleCompleteTutorial = useCallback((): void => {
    if (activeTutorialId) {
      completeTutorial(activeTutorialId);

      // Show completion message
      if (activeTutorial?.completionMessage) {
        alert(activeTutorial.completionMessage); // In production, use a proper notification system
      }
    }
  }, [activeTutorialId, completeTutorial, activeTutorial?.completionMessage]);

  // Handle skipping tutorial
  const handleSkipTutorial = (): void => {
    if (activeTutorialId) {
      completeTutorial(activeTutorialId);
    }
  };

  // Handle next step
  const handleNextStep = useCallback((): void => {
    if (activeTutorialId) {
      if (currentStepIndex >= (activeTutorial?.steps.length ?? 0) - 1) {
        handleCompleteTutorial();
      } else {
        nextTutorialStep(activeTutorialId);
      }
    }
  }, [
    activeTutorialId,
    currentStepIndex,
    activeTutorial?.steps.length,
    nextTutorialStep,
    handleCompleteTutorial,
  ]);

  // Handle previous step
  const handlePreviousStep = (): void => {
    if (activeTutorialId && currentStepIndex > 0) {
      // For simplicity, we'll just skip to previous step
      // In a real implementation, you might want to track step history
      nextTutorialStep(activeTutorialId);
    }
  };

  // Auto-advance tutorial based on user actions
  useEffect((): void => {
    if (currentStep?.validation && currentStep.validation()) {
      // Auto-advance if validation passes
      setTimeout((): void => {
        handleNextStep();
      }, 1000);
    }
  }, [currentStep, handleNextStep]);

  const TutorialMenuModal = (): React.ReactElement => {
    const { availableTutorials, completedTutorials } = useTutorials();

    return (
      <Modal
        isOpen={showTutorialMenu}
        size="lg"
        title="Interactive Tutorials"
        onClose={(): void => {
 setShowTutorialMenu(false); 
}}
      >
        <div className="space-y-6">
          <p className="text-gray-600">
            Learn Teaching Engine 2.0 features through hands-on, interactive tutorials.
          </p>

          {/* Available Tutorials */}
          <div>
            <h3 className="text-lg font-medium text-gray-900 mb-4">Available Tutorials</h3>
            <div className="space-y-3">
              {availableTutorials.map((tutorial, _index) => {
                const isCompleted = completedTutorials.includes(tutorial.id);
                const isActive = activeTutorialId === tutorial.id;

                return (
                  <div
                    key={tutorial.id}
                    className="border border-gray-200 rounded-lg p-4 hover:border-blue-300 transition-colors"
                  >
                    <div className="flex items-start justify-between">
                      <div className="flex-1">
                        <div className="flex items-center space-x-2">
                          <h4 className="font-medium text-gray-900">{tutorial.title}</h4>
                          {isCompleted && (
                            <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-green-100 text-green-800">
                              Completed
                            </span>
                          )}
                          {isActive && (
                            <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-blue-100 text-blue-800">
                              In Progress
                            </span>
                          )}
                        </div>
                        <p className="text-sm text-gray-600 mt-1">{tutorial.description}</p>
                        <div className="flex items-center mt-2 space-x-4 text-xs text-gray-500">
                          <span>📊 {tutorial.difficulty}</span>
                          <span>⏱️ {tutorial.estimatedTime} min</span>
                          <span>🎯 {tutorial.category}</span>
                        </div>
                        {tutorial.prerequisites.length > 0 && (
                          <div className="mt-2">
                            <span className="text-xs text-gray-500">
                              Prerequisites: {tutorial.prerequisites.join(', ')}
                            </span>
                          </div>
                        )}
                      </div>
                      <div className="ml-4">
                        {isCompleted ? (
                          <Button disabled size="sm" variant="secondary">
                            ✓ Completed
                          </Button>
                        ) : isActive ? (
                          <Button
                            size="sm"
                            variant="primary"
                            onClick={(): void => {
                              setShowTutorialMenu(false);
                              // Resume tutorial - overlay will show automatically
                            }}
                          >
                            Resume
                          </Button>
                        ) : (
                          <Button
                            size="sm"
                            variant="primary"
                            onClick={(): void => {
                              startTutorial(tutorial.id);
                              setShowTutorialMenu(false);
                            }}
                          >
                            Start
                          </Button>
                        )}
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>

          {/* Completed Tutorials */}
          {completedTutorials.length > 0 && (
            <div>
              <h3 className="text-lg font-medium text-gray-900 mb-4">
                Completed Tutorials ({completedTutorials.length})
              </h3>
              <div className="text-sm text-gray-600">
                <p>Great job! You&apos;ve completed {completedTutorials.length} tutorial(s).</p>
                {completedTutorials.length >= availableTutorials.length && (
                  <p className="mt-2 text-green-600 font-medium">
                    🎉 You&apos;ve completed all available tutorials! You&apos;re a Teaching Engine
                    2.0 expert.
                  </p>
                )}
              </div>
            </div>
          )}
        </div>
      </Modal>
    );
  };

  return (
    <>
      {children}

      {/* Tutorial Overlay */}
      <TutorialOverlay
        currentStep={currentStep}
        isActive={!!activeTutorial}
        progress={progress}
        tutorial={activeTutorial ?? null}
        onComplete={handleCompleteTutorial}
        onNext={handleNextStep}
        onPrevious={handlePreviousStep}
        onSkip={handleSkipTutorial}
      />

      {/* Floating Tutorial Button */}
      {!activeTutorial && (
        <button
          className="fixed bottom-20 right-6 bg-green-600 text-white rounded-full p-3 shadow-lg hover:bg-green-700 transition-colors z-40"
          title="Start Interactive Tutorial"
          onClick={(): void => {
 setShowTutorialMenu(true); 
}}
        >
          <svg className="h-6 w-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path
              d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.246 18 16.5 18c-1.746 0-3.332.477-4.5 1.253"
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
            />
          </svg>
        </button>
      )}

      {/* Tutorial Menu Modal */}
      <TutorialMenuModal />
    </>
  );
};

import React, { useEffect, useRef } from 'react';
import { createPortal } from 'react-dom';

import type { TutorialOverlayProps } from '../../types/help';
import { Button } from '../ui/Button';
// import { clsx } from 'clsx';

export const TutorialOverlay: React.FC<TutorialOverlayProps> = ({
  isActive,
  currentStep,
  tutorial,
  onNext,
  onPrevious,
  onSkip,
  onComplete,
  progress
}): React.ReactElement | null => {
  const _highlightRef = useRef<HTMLDivElement>(null);

  // Highlight target element
  useEffect((): (() => void) | void => {
    if (!isActive || !currentStep?.targetElement) {
return;
}

    const targetElement = document.querySelector(currentStep.targetElement);
    if (targetElement) {
      targetElement.scrollIntoView({ behavior: 'smooth', block: 'center' });

      // Add highlight class
      targetElement.classList.add('tutorial-highlight');

      return (): void => {
        targetElement.classList.remove('tutorial-highlight');
      };
    }
  }, [isActive, currentStep]);

  if (!isActive || !currentStep || !tutorial) {
    return null;
  }

  const isLastStep = progress >= 100;
  const isFirstStep = progress === 0;

  return createPortal(
    <>
      {/* Overlay backdrop */}
      <div className="fixed inset-0 bg-black bg-opacity-50 z-40" />

      {/* Tutorial card */}
      <div className="fixed top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 z-50 bg-white rounded-lg shadow-xl max-w-md w-full mx-4">
        {/* Header */}
        <div className="p-6 border-b border-gray-200">
          <div className="flex items-center justify-between">
            <div>
              <h3 className="text-lg font-semibold text-gray-900">
                {tutorial.title}
              </h3>
              <p className="text-sm text-gray-600 mt-1">
                Step {Math.floor(progress / (100 / tutorial.steps.length)) + 1} of {tutorial.steps.length}
              </p>
            </div>
            <button
              className="text-gray-400 hover:text-gray-600 focus:outline-none"
              onClick={onSkip}
            >
              <span className="sr-only">Skip tutorial</span>
              <svg className="h-6 w-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path d="M6 18L18 6M6 6l12 12" strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} />
              </svg>
            </button>
          </div>

          {/* Progress bar */}
          <div className="mt-4">
            <div className="w-full bg-gray-200 rounded-full h-2">
              <div
                className="bg-blue-600 h-2 rounded-full transition-all duration-300"
                style={{ width: `${progress}%` }}
              />
            </div>
          </div>
        </div>

        {/* Content */}
        <div className="p-6">
          <h4 className="text-base font-medium text-gray-900 mb-2">
            {currentStep.title}
          </h4>
          <p className="text-sm text-gray-600 mb-4">
            {currentStep.description}
