            </div>
          )}
        </div>

        {/* Footer */}
        <div className="px-6 py-4 bg-gray-50 rounded-b-lg">
          <div className="flex items-center justify-between">
            <Button
              size="sm"
              variant="ghost"
              onClick={onSkip}
            >
              Skip Tutorial
            </Button>

            <div className="flex space-x-2">
              <Button
                disabled={isFirstStep}
                size="sm"
                variant="secondary"
                onClick={onPrevious}
              >
                Previous
              </Button>

              {isLastStep ? (
                <Button
                  size="sm"
                  variant="primary"
                  onClick={onComplete}
                >
                  Complete
                </Button>
              ) : (
                <Button
                  size="sm"
                  variant="primary"
                  onClick={onNext}
                >
                  Next
                </Button>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* Add tutorial highlight styles if not already present */}
      <style>{`
        .tutorial-highlight {
          position: relative;
          z-index: 45;
          box-shadow: 0 0 0 4px rgba(59, 130, 246, 0.5);
          border-radius: 4px;
          animation: tutorial-pulse 2s infinite;
        }

        @keyframes tutorial-pulse {
          0%, 100% {
            box-shadow: 0 0 0 4px rgba(59, 130, 246, 0.5);
          }
          50% {
            box-shadow: 0 0 0 8px rgba(59, 130, 246, 0.3);
          }
        }
      `}</style>
    </>,
    document.body
  );
};

