// Original hover tooltip interface
interface HoverTooltipProps {
  id: string;
  title: string;
  content: string;
  children: ReactElement;
  position?: 'top' | 'bottom' | 'left' | 'right';
  showOnce?: boolean;
  delay?: number;
  actionText?: string;
  onAction?: () => void;
}

// Flow tooltip interface (for OnboardingFlow)
interface FlowTooltipProps {
  currentStep: OnboardingStep;
  state: OnboardingState;
  progress: number;
  canGoBack: boolean;
  canGoForward: boolean;
  skipOnboarding: () => void;
  previousStep: () => void;
  nextStep: () => void;
  tooltipPosition: { top: number; left: number };
  isCenter: boolean;
}

// Combined props type
type OnboardingTooltipProps = HoverTooltipProps | FlowTooltipProps;

// Type guard to check which props type we have
function isFlowTooltipProps(props: OnboardingTooltipProps): props is FlowTooltipProps {
  return 'currentStep' in props;
}

export function OnboardingTooltip(props: OnboardingTooltipProps): React.ReactElement {
  // If this is being used in the flow, render the flow tooltip
  if (isFlowTooltipProps(props)) {
    return <FlowTooltip {...props} />;
  }

  // Otherwise, render the hover tooltip
  return <HoverTooltip {...props} />;
}

// Flow tooltip component
function FlowTooltip({
  currentStep,
  state,
  progress,
  canGoBack,
  canGoForward,
  skipOnboarding,
  previousStep,
  nextStep,
  tooltipPosition,
  isCenter,
}: FlowTooltipProps): JSX.Element {
  return (
    <motion.div
      animate={{ opacity: 1, y: 0 }}
      className={`absolute bg-white rounded-lg shadow-2xl p-6 max-w-md ${
        isCenter ? 'fixed top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2' : ''
      }`}
      exit={{ opacity: 0, y: 20 }}
      initial={{ opacity: 0, y: 20 }}
      style={
        isCenter
          ? {}
          : {
              top: tooltipPosition.top,
              left: tooltipPosition.left,
              width: '400px',
            }
      }
      transition={{ delay: 0.2 }}
    >
      {/* Close button */}
      {currentStep.showSkip === true ? (
        <button
          aria-label="Skip onboarding"
          className="absolute top-2 right-2 p-1 text-gray-400 hover:text-gray-600 transition-colors"
          onClick={skipOnboarding}
        >
          <X className="h-5 w-5" />
        </button>
      ) : null}

      {/* Progress indicator */}
      <div className="mb-4">
        <div className="flex items-center justify-between mb-2">
          <span className="text-sm text-gray-500">
            Step {state.currentStepIndex + 1} of {state.currentFlow?.steps.length ?? 0}
          </span>
          {state.currentFlow?.estimatedTime !== null && state.currentFlow?.estimatedTime !== undefined ? (
            <span className="text-sm text-gray-500">
              ~{state.currentFlow.estimatedTime} min
            </span>
          ) : null}
        </div>
        <Progress className="h-2" value={progress} />
      </div>

      {/* Content */}
      <div className="space-y-4">
        <div className="flex items-start gap-3">
          <div className="p-2 bg-blue-100 rounded-full flex-shrink-0">
            <Sparkles className="h-5 w-5 text-blue-600" />
          </div>
          <div className="flex-1">
            <h3 className="text-lg font-semibold text-gray-900 mb-2">{currentStep.title}</h3>
            <p className="text-gray-600 leading-relaxed">{currentStep.description}</p>
          </div>
        </div>

        {/* Action hint */}
        {currentStep.requiresAction === true ? (
          <div className="bg-blue-50 border border-blue-200 rounded-md p-3 text-sm text-blue-700">
            <p className="font-medium">Action required:</p>
            <p>
              {currentStep.action === 'click' && 'Click the highlighted element to continue'}
              {currentStep.action === 'input' && 'Fill in the required information'}
              {currentStep.action === 'hover' && 'Hover over the highlighted element'}
            </p>
          </div>
        ) : null}

        {/* Navigation buttons */}
        <div className="flex items-center justify-between pt-2">
          <div className="flex items-center gap-2">
            {canGoBack ? (
              <Button aria-label="Click button" onClick={previousStep}>
                <ChevronLeft className="h-4 w-4" />
                Previous
              </Button>
            ) : null}
            {currentStep.showSkip === true ? (
              <Button
                className="text-gray-500"
                size="sm"
                variant="ghost"
                onClick={skipOnboarding}
              >
                {currentStep.skipButtonText ?? 'Skip tour'}
              </Button>
            ) : null}
          </div>

          {currentStep.requiresAction !== true ? (
            <Button
              className="gap-1 bg-blue-600 hover:bg-blue-700"
              size="sm"
              onClick={nextStep}
            >
              {currentStep.nextButtonText ?? 'Next'}
              {canGoForward ? <ChevronRight className="h-4 w-4" /> : null}
            </Button>
          ) : null}
        </div>
      </div>
    </motion.div>
  );
}

// Hover tooltip component
function HoverTooltip({
  id: _id,
  title,
  content,
  children,
  position = 'top',
  showOnce = true,
  delay = 1000,
  actionText,
  onAction,
}: HoverTooltipProps): React.ReactElement {
  const { state } = useOnboarding();
  const [isVisible, setIsVisible] = useState(false);
  const [isDismissed, setIsDismissed] = useState(false);
  const [hasBeenShown, setHasBeenShown] = useState(false);

  // Don't show if onboarding is active or user isn't new
  if ((state.currentFlow !== null && state.currentFlow !== undefined) || !state.isFirstTimeUser) {
    return children;
  }

  // Don't show if already dismissed or shown (when showOnce is true)
  if (isDismissed || (showOnce && hasBeenShown)) {
    return children;
  }

  const handleMouseEnter = (): void => {
    if (hasBeenShown && showOnce) {
return;
}

    setTimeout(() => {
      setIsVisible(true);
      setHasBeenShown(true);
    }, delay);
  };

  const handleMouseLeave = (): void => {
    setIsVisible(false);
  };

  const handleDismiss = (): void => {
    setIsVisible(false);
    setIsDismissed(true);
  };

  const getTooltipStyles = (): string => {
    const base = 'absolute z-50 bg-white rounded-lg shadow-xl border border-gray-200 p-4 w-72';

    switch (position) {
      case 'top':
        return `${base} bottom-full left-1/2 transform -translate-x-1/2 mb-2`;
      case 'bottom':
        return `${base} top-full left-1/2 transform -translate-x-1/2 mt-2`;
      case 'left':
        return `${base} right-full top-1/2 transform -translate-y-1/2 mr-2`;
      case 'right':
        return `${base} left-full top-1/2 transform -translate-y-1/2 ml-2`;
      default:
        return base;
    }
  };

  const getArrowStyles = (): string => {
    const base = 'absolute w-3 h-3 bg-white border border-gray-200 transform rotate-45';

    switch (position) {
      case 'top':
        return `${base} -bottom-1.5 left-1/2 -translate-x-1/2 border-t-0 border-l-0`;
      case 'bottom':
        return `${base} -top-1.5 left-1/2 -translate-x-1/2 border-b-0 border-r-0`;
      case 'left':
        return `${base} -right-1.5 top-1/2 -translate-y-1/2 border-l-0 border-b-0`;
      case 'right':
        return `${base} -left-1.5 top-1/2 -translate-y-1/2 border-r-0 border-t-0`;
      default:
        return base;
    }
  };

  return (
    <div className="relative inline-block">
      {cloneElement(children, {
        onMouseEnter: handleMouseEnter,
        onMouseLeave: handleMouseLeave,
        className: `${(children.props as { className?: string }).className ?? ''} ${isVisible ? 'z-40' : ''}`,
      })}

      <AnimatePresence>
        {isVisible ? (
          <motion.div
            animate={{ opacity: 1, scale: 1 }}
            className={getTooltipStyles()}
            exit={{ opacity: 0, scale: 0.95 }}
            initial={{ opacity: 0, scale: 0.95 }}
            transition={{ duration: 0.2 }}
            onMouseEnter={(): void => {
 setIsVisible(true); 
}}
            onMouseLeave={handleMouseLeave}
          >
            {/* Arrow */}
            <div className={getArrowStyles()} />

            {/* Close button */}
            <button
              aria-label="Dismiss tooltip"
              className="absolute top-2 right-2 p-1 text-gray-400 hover:text-gray-600 transition-colors"
              onClick={handleDismiss}
            >
              <X className="h-4 w-4" />
            </button>

            {/* Content */}
            <div className="pr-6">
              <div className="flex items-start gap-3 mb-2">
                <div className="p-1 bg-blue-100 rounded flex-shrink-0">
                  <HelpCircle className="h-4 w-4 text-blue-600" />
                </div>
                <div>
                  <h4 className="font-medium text-gray-900 text-sm mb-1">{title}</h4>
                  <p className="text-sm text-gray-600 leading-relaxed">{content}</p>
                </div>
              </div>

              {actionText !== null && actionText !== undefined && actionText !== '' && onAction !== null && onAction !== undefined ? (
                <button
                  className="mt-3 text-sm font-medium text-blue-600 hover:text-blue-700 transition-colors"
                  onClick={() => {
                    onAction();
                    handleDismiss();
                  }}
                >
                  {actionText} →
                </button>
              ) : null}
            </div>
          </motion.div>
        ) : null}
      </AnimatePresence>
    </div>
  );
}

import { useState } from 'react';

import { Button } from '../ui/Button';
import { Card, CardContent, CardHeader, CardTitle } from '../ui/card';
import { Checkbox } from '../ui/checkbox';
import { Label } from '../ui/Label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '../ui/select';

interface PreferenceWizardProps {
  onComplete: (preferences: TeacherPreferences) => void;
  onSkip: () => void;
}

interface TeacherPreferences {
  grade: string;
  subjects: string[];
  planningStyle: string;
  aiAssistanceLevel: string;
  theme: string;
  notifications: {
    deadlineReminders: boolean;
    weeklyDigest: boolean;
    curriculumUpdates: boolean;
  };
}

export default function PreferenceWizard({ onComplete, onSkip }: PreferenceWizardProps): React.ReactElement {
  const [preferences, setPreferences] = useState<TeacherPreferences>({
    grade: '',
    subjects: [],
    planningStyle: 'detailed',
    aiAssistanceLevel: 'moderate',
    theme: 'light',
    notifications: {
      deadlineReminders: true,
      weeklyDigest: true,
      curriculumUpdates: false,
    },
  });

  const grades = [
    'Kindergarten',
    'Grade 1',
    'Grade 2',
    'Grade 3',
    'Grade 4',
    'Grade 5',
    'Grade 6',
    'Grade 7',
    'Grade 8',
  ];

  const subjects = [
    'Mathematics',
    'Language Arts',
    'Science',
    'Social Studies',
    'French',
    'Arts',
    'Physical Education',
    'Health',
    'Music',
  ];

  const handleSubjectChange = (subject: string, checked: boolean): void => {
    setPreferences(prev => ({
      ...prev,
      subjects: checked
        ? [...prev.subjects, subject]
        : prev.subjects.filter(s => s !== subject),
    }));
  };

  const handleNotificationChange = (key: keyof typeof preferences.notifications, checked: boolean): void => {
    setPreferences(prev => ({
      ...prev,
      notifications: {
        ...prev.notifications,
        [key]: checked,
      },
    }));
  };

  const handleComplete = (): void => {
    // Save preferences to localStorage for now
    localStorage.setItem('teacher-preferences', JSON.stringify(preferences));
    onComplete(preferences);
  };

  return (
    <div className="max-w-2xl mx-auto space-y-6">
      <div className="text-center mb-8">
        <h2 className="text-2xl font-bold text-gray-900 mb-2">Customize Your Experience</h2>
        <p className="text-gray-600">Help us tailor Teaching Engine 2.0 to your needs</p>
      </div>

      {/* Grade Selection */}
      <Card>
        <CardHeader>
          <CardTitle>What grade do you teach?</CardTitle>
        </CardHeader>
        <CardContent>
          <Select
            value={preferences.grade}
            onValueChange={(value) => {
 setPreferences(prev => ({ ...prev, grade: value })); 
}}
          >
            <SelectTrigger>
              <SelectValue placeholder="Select your grade" />
            </SelectTrigger>
            <SelectContent>
              {grades.map(grade => (
                <SelectItem key={grade} value={grade}>
                  {grade}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </CardContent>
      </Card>

      {/* Subject Selection */}
      <Card>
        <CardHeader>
          <CardTitle>Which subjects do you teach?</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
            {subjects.map(subject => (
              <div key={subject} className="flex items-center space-x-2">
                <Checkbox
                  checked={preferences.subjects.includes(subject)}
                  id={subject}
                  onCheckedChange={(checked) => {
 handleSubjectChange(subject, checked as boolean); 
}}
                />
                <Label className="text-sm font-medium" htmlFor={subject}>
                  {subject}
                </Label>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Planning Style */}
      <Card>
        <CardHeader>
          <CardTitle>How detailed do you like your lesson plans?</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-3">
            <div className="flex items-center space-x-2">
              <input
                checked={preferences.planningStyle === 'brief'}
                className="text-indigo-600"
                id="brief"
                name="planningStyle"
                type="radio"
                value="brief"
                onChange={(e) => {
 setPreferences(prev => ({ ...prev, planningStyle: e.target.value })); 
}}
              />
              <Label htmlFor="brief">Brief - Key points and activities only</Label>
            </div>
            <div className="flex items-center space-x-2">
              <input
                checked={preferences.planningStyle === 'detailed'}
                className="text-indigo-600"
                id="detailed"
                name="planningStyle"
                type="radio"
                value="detailed"
                onChange={(e) => {
 setPreferences(prev => ({ ...prev, planningStyle: e.target.value })); 
}}
              />
              <Label htmlFor="detailed">Detailed - Comprehensive plans with all sections</Label>
            </div>
            <div className="flex items-center space-x-2">
              <input
                checked={preferences.planningStyle === 'comprehensive'}
                className="text-indigo-600"
                id="comprehensive"
                name="planningStyle"
                type="radio"
                value="comprehensive"
                onChange={(e) => {
 setPreferences(prev => ({ ...prev, planningStyle: e.target.value })); 
}}
              />
              <Label htmlFor="comprehensive">Comprehensive - Everything including assessments and modifications</Label>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* AI Assistance Level */}
      <Card>
        <CardHeader>
          <CardTitle>How much AI assistance would you like?</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-3">
            <div className="flex items-center space-x-2">
              <input
                checked={preferences.aiAssistanceLevel === 'minimal'}
                className="text-indigo-600"
                id="minimal"
                name="aiAssistance"
                type="radio"
                value="minimal"
                onChange={(e) => {
 setPreferences(prev => ({ ...prev, aiAssistanceLevel: e.target.value })); 
}}
              />
              <Label htmlFor="minimal">Minimal - Only when I ask for help</Label>
            </div>
            <div className="flex items-center space-x-2">
              <input
                checked={preferences.aiAssistanceLevel === 'moderate'}
                className="text-indigo-600"
                id="moderate"
                name="aiAssistance"
                type="radio"
                value="moderate"
                onChange={(e) => {
 setPreferences(prev => ({ ...prev, aiAssistanceLevel: e.target.value })); 
}}
              />
              <Label htmlFor="moderate">Moderate - Smart suggestions and auto-completion</Label>
            </div>
            <div className="flex items-center space-x-2">
              <input
                checked={preferences.aiAssistanceLevel === 'high'}
                className="text-indigo-600"
                id="high"
                name="aiAssistance"
                type="radio"
                value="high"
                onChange={(e) => {
 setPreferences(prev => ({ ...prev, aiAssistanceLevel: e.target.value })); 
}}
              />
              <Label htmlFor="high">High - Proactive suggestions and automated planning</Label>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Notifications */}
      <Card>
        <CardHeader>
          <CardTitle>Notification Preferences</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            <div className="flex items-center space-x-2">
              <Checkbox
                checked={preferences.notifications.deadlineReminders}
                id="deadlineReminders"
                onCheckedChange={(checked) => {
 handleNotificationChange('deadlineReminders', checked as boolean); 
}}
              />
              <Label htmlFor="deadlineReminders">Deadline and task reminders</Label>
            </div>
            <div className="flex items-center space-x-2">
              <Checkbox
                checked={preferences.notifications.weeklyDigest}
                id="weeklyDigest"
                onCheckedChange={(checked) => {
 handleNotificationChange('weeklyDigest', checked as boolean); 
}}
              />
              <Label htmlFor="weeklyDigest">Weekly planning digest</Label>
            </div>
            <div className="flex items-center space-x-2">
              <Checkbox
                checked={preferences.notifications.curriculumUpdates}
                id="curriculumUpdates"
                onCheckedChange={(checked) => {
 handleNotificationChange('curriculumUpdates', checked as boolean); 
}}
              />
              <Label htmlFor="curriculumUpdates">Curriculum updates and new features</Label>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Theme Selection */}
      <Card>
        <CardHeader>
          <CardTitle>Interface Theme</CardTitle>
        </CardHeader>
        <CardContent>
          <Select
            value={preferences.theme}
            onValueChange={(value) => {
 setPreferences(prev => ({ ...prev, theme: value })); 
}}
          >
            <SelectTrigger>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="light">Light Theme</SelectItem>
              <SelectItem value="dark">Dark Theme</SelectItem>
              <SelectItem value="system">System Preference</SelectItem>
            </SelectContent>
          </Select>
        </CardContent>
      </Card>

      {/* Action Buttons */}
      <div className="flex justify-between items-center pt-6">
        <Button aria-label="Click button" onClick={onSkip}>
          Skip for Now
        </Button>
        <Button 
          disabled={preferences.grade === '' || preferences.subjects.length === 0}
          onClick={handleComplete}
        >
          Save Preferences
        </Button>
      </div>
    </div>
  );
}

