import React from 'react';

import { cn } from '../../lib/utils';

interface SkeletonLayoutItem {
  type: 'avatar' | 'text' | 'button' | 'image';
  size?: 'sm' | 'md' | 'lg';
  width?: string;
  lines?: number;
}

interface LoadingSkeletonProps {
  variant?: 'default' | 'card' | 'list' | 'table' | 'text' | 'avatar' | 'complex';
  size?: 'sm' | 'md' | 'lg';
  rows?: number;
  columns?: number;
  lines?: number;
  height?: string;
  width?: string;
  className?: string;
  animate?: boolean;
  layout?: SkeletonLayoutItem[];
  'aria-label'?: string;
}

export function LoadingSkeleton({
  variant = 'default',
  size = 'md',
  rows = 3,
  columns = 3,
  lines = 3,
  height,
  width,
  className,
  animate = true,
  layout = [],
  'aria-label': ariaLabel = 'Loading...',
}: LoadingSkeletonProps): React.ReactElement {
  const baseClasses = 'bg-gray-200 rounded';
  const animationClasses = animate ? 'animate-pulse' : '';

  const sizeClasses = {
    sm: 'h-4',
    md: 'h-6',
    lg: 'h-8',
  };

  const containerStyle: React.CSSProperties = {};
  if (height !== undefined && height !== null && height !== '') {
containerStyle.height = height;
}
  if (width !== undefined && width !== null && width !== '') {
containerStyle.width = width;
}

  const SkeletonBox = ({ 
    className: boxClassName = '', 
    style = {},
    'data-testid': testId,
    role,
    'aria-label': ariaLabelProp,
  }: { 
    className?: string; 
    style?: React.CSSProperties;
    'data-testid'?: string;
    role?: string;
    'aria-label'?: string;
  }): JSX.Element => (
    <div
      aria-label={ariaLabelProp}
      className={cn(baseClasses, animationClasses, boxClassName)}
      data-testid={testId}
      role={role}
      style={style}
    />
  );

  const renderComplexLayout = (): JSX.Element => (
    <div className="flex items-start space-x-3">
      {layout.map((item, index) => {
        switch (item.type) {
          case 'avatar':
            return (
              <SkeletonBox
                key={index}
                className={cn(
                  'rounded-full flex-shrink-0',
                  item.size === 'sm' ? 'h-8 w-8' : 
                  item.size === 'lg' ? 'h-16 w-16' : 'h-12 w-12'
                )}
                data-testid="skeleton-avatar"
              />
            );
          case 'text':
            return (
              <div key={index} className="flex-1 space-y-2" data-testid="skeleton-text">
                {Array.from({ length: item.lines ?? 2 }).map((_, lineIndex) => (
                  <SkeletonBox
                    key={lineIndex}
                    className={cn(
                      'h-4',
                      lineIndex === (item.lines ?? 2) - 1 ? 'w-3/4' : 'w-full'
                    )}
                  />
                ))}
              </div>
            );
          case 'button':
            return (
              <SkeletonBox
                key={index}
                className="h-9 rounded-md"
                data-testid="skeleton-button"
                style={{ width: item.width ?? '100px' }}
              />
            );
          case 'image':
            return (
              <SkeletonBox
                key={index}
                className={cn(
                  'rounded-lg',
                  item.size === 'sm' ? 'h-20 w-20' :
                  item.size === 'lg' ? 'h-48 w-48' : 'h-32 w-32'
                )}
              />
            );
          default:
            return null;
        }
      })}
    </div>
  );

  switch (variant) {
    case 'card':
      return (
        <div
          aria-label={ariaLabel}
          className={cn('p-4 border rounded-lg', className)}
          data-testid="loading-skeleton"
          role="status"
          style={containerStyle}
        >
          <div className="space-y-4">
            <SkeletonBox 
              className={cn('h-6', sizeClasses[size])} 
              data-testid="skeleton-title"
            />
            <div className="space-y-2">
              <SkeletonBox className="h-4 w-full" />
              <SkeletonBox className="h-4 w-4/5" />
              <SkeletonBox className="h-4 w-3/5" />
            </div>
            <div className="flex space-x-2">
              <SkeletonBox className="h-8 w-20 rounded-md" />
              <SkeletonBox className="h-8 w-16 rounded-md" />
            </div>
          </div>
          <SkeletonBox 
            className="h-4 mt-4" 
            data-testid="skeleton-content"
          />
        </div>
      );

    case 'list':
      return (
        <div
          aria-label={ariaLabel}
          className={cn('space-y-3', className)}
          data-testid="loading-skeleton"
          role="status"
          style={containerStyle}
        >
          {Array.from({ length: rows }).map((_, index) => (
            <div key={index} className="flex items-center space-x-3" data-testid={`skeleton-row-${index}`}>
              <SkeletonBox className="h-10 w-10 rounded-full flex-shrink-0" />
              <div className="flex-1 space-y-2">
                <SkeletonBox className="h-4 w-3/4" />
                <SkeletonBox className="h-3 w-1/2" />
              </div>
            </div>
          ))}
        </div>
      );

    case 'table':
      return (
        <div
          aria-label={ariaLabel}
          className={cn('w-full', className)}
          data-testid="loading-skeleton"
          role="status"
          style={containerStyle}
        >
          {/* Table Header */}
          <div className="flex space-x-4 mb-4" data-testid="skeleton-table-header">
            {Array.from({ length: columns }).map((_, index) => (
              <SkeletonBox key={index} className="h-4 flex-1" />
            ))}
          </div>

          {/* Table Rows */}
          <div className="space-y-3">
            {Array.from({ length: rows }).map((_, rowIndex) => (
              <div key={rowIndex} className="flex space-x-4" data-testid={`skeleton-table-row-${rowIndex}`}>
                {Array.from({ length: columns }).map((_, colIndex) => (
                  <SkeletonBox 
                    key={colIndex} 
                    className="h-4 flex-1" 
                    data-testid={`skeleton-table-cell-${rowIndex}-${colIndex}`}
                  />
                ))}
              </div>
            ))}
          </div>
        </div>
      );

    case 'text':
      return (
        <div
          aria-label={ariaLabel}
          className={cn('space-y-2', className)}
          data-testid="loading-skeleton"
          role="status"
          style={containerStyle}
        >
          {Array.from({ length: lines }).map((_, index) => (
            <SkeletonBox
              key={index}
              className={cn(
                'h-4',
                index === lines - 1 ? 'w-3/4' : 'w-full'
              )}
              data-testid={`skeleton-text-line-${index}`}
            />
          ))}
        </div>
      );

    case 'avatar':
      return (
        <SkeletonBox
          aria-label={ariaLabel}
          className={cn(
            'rounded-full',
            size === 'sm' ? 'h-8 w-8' :
            size === 'lg' ? 'h-16 w-16' : 'h-12 w-12',
            className
          )}
          data-testid="loading-skeleton"
          role="status"
          style={containerStyle}
        />
      );

    case 'complex':
      return (
        <div
          aria-label={ariaLabel}
          className={cn('p-4', className)}
          data-testid="loading-skeleton"
          role="status"
          style={containerStyle}
        >
          {renderComplexLayout()}
        </div>
      );

    default:
      return (
        <SkeletonBox
          aria-label={ariaLabel}
          className={cn(sizeClasses[size], 'w-full', className)}
          data-testid="loading-skeleton"
          role="status"
          style={containerStyle}
        />
      );
  }
}

import { startOfMonth, endOfMonth, eachDayOfInterval, format, isSameMonth } from 'date-fns';
import React, { useState, memo, useMemo, useCallback } from 'react';

import { useCalendarEvents } from '../../api/domains/calendar';
import type { CalendarEvent } from '../../types';
import logger from '../../utils/logger';

import { LoadingSkeleton } from './LoadingSkeleton';
import { VirtualizedList } from './VirtualizedList';

interface OptimizedCalendarViewProps {
  month: Date;
  events?: CalendarEvent[];
  onEventClick?: (event: CalendarEvent) => void;
  onDateClick?: (date: Date) => void;
  className?: string;
  compact?: boolean;
  virtualizeEvents?: boolean;
  maxEventsPerDay?: number;
}

// Memoized day cell component
const DayCell = memo(({
  date,
  events,
  onEventClick,
  onDateClick,
  isCurrentMonth,
  maxEventsPerDay = 3,
}: {
  date: Date;
  events: CalendarEvent[];
  onEventClick?: (event: CalendarEvent) => void;
  onDateClick?: (date: Date) => void;
  isCurrentMonth: boolean;
  maxEventsPerDay: number;
}) => {
  const dayNumber = date.getDate();
  const isToday = useMemo(() => {
    const today = new Date();
    return (
      date.getDate() === today.getDate() &&
      date.getMonth() === today.getMonth() &&
      date.getFullYear() === today.getFullYear()
    );
  }, [date]);

  const handleDateClick = useCallback(() => {
    onDateClick?.(date);
  }, [date, onDateClick]);

  const visibleEvents = useMemo(() => events.slice(0, maxEventsPerDay), [events, maxEventsPerDay]);

  const hiddenEventCount = Math.max(0, events.length - maxEventsPerDay);

  return (
    <div
      className={`border p-1 min-h-16 cursor-pointer hover:bg-gray-50 transition-colors ${
        !isCurrentMonth ? 'bg-gray-100 text-gray-400' : ''
      } ${isToday ? 'bg-blue-50 border-blue-200' : ''}`}
      onClick={handleDateClick}
    >
      <div className={`font-bold text-xs mb-1 ${isToday ? 'text-blue-600' : ''}`}>
        {dayNumber}
      </div>

      <div className="space-y-0.5">
        {visibleEvents.map((event, _index) => (
          <div
            key={event.id}
            className="text-xs bg-gray-200 rounded px-1 py-0.5 cursor-pointer hover:bg-gray-300 transition-colors truncate"
            title={event.title}
            onClick={(e) => {
              e.stopPropagation();
              onEventClick?.(event);
            }}
          >
            {event.title}
          </div>
        ))}

        {hiddenEventCount > 0 && (
          <div className="text-xs text-gray-500 font-medium">
            +{hiddenEventCount} more
          </div>
        )}
      </div>
    </div>
  );
}, (prevProps, nextProps) => 
  // Optimize re-renders by comparing relevant props
   (
    format(prevProps.date, 'yyyy-MM-dd') === format(nextProps.date, 'yyyy-MM-dd') &&
    prevProps.events.length === nextProps.events.length &&
    prevProps.isCurrentMonth === nextProps.isCurrentMonth &&
    prevProps.maxEventsPerDay === nextProps.maxEventsPerDay &&
    prevProps.events.every((event, index) => 
      event.id === nextProps.events[index]?.id &&
      event.title === nextProps.events[index]?.title
    )
  )
