  label: string;
  sortable?: boolean;
  filterable?: boolean;
  width?: string;
  render?: (value: unknown, item: T) => React.ReactNode;
}

interface PaginatedResult<T> {
  items: T[];
  total: number;
  page: number;
  totalPages: number;
}

interface FetchParams {
  page: number;
  pageSize: number;
  sortBy?: string;
  sortOrder: 'asc' | 'desc';
  filters: Record<string, string | number | boolean>;
}

interface PaginatedDataTableProps<T> {
  columns: Column<T>[];
  fetchData: (params: FetchParams) => Promise<PaginatedResult<T>>;
  pageSize?: number;
  initialSort?: { key: keyof T; order: 'asc' | 'desc' };
  className?: string;
  emptyStateMessage?: string;
  searchPlaceholder?: string;
  enableGlobalSearch?: boolean;
}

export function PaginatedDataTable<T extends Record<string, unknown>>({
  columns,
  fetchData,
  pageSize = 25,
  initialSort,
  className = '',
  emptyStateMessage = 'No data available',
  enableGlobalSearch = false,
}: PaginatedDataTableProps<T>): JSX.Element {
  const [currentPage, setCurrentPage] = useState(1);
  const [sortBy, setSortBy] = useState<string | undefined>(initialSort?.key as string);
  const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>(initialSort?.order || 'asc');
  const [filters, setFilters] = useState<Record<string, string | number | boolean>>({});
  const [globalSearch, setGlobalSearch] = useState('');

  // Debounced filter updates
  const debouncedUpdateFilters = useMemo(
    () =>
      debounce<[Record<string, string | number | boolean>]>((newFilters: Record<string, string | number | boolean>) => {
        setFilters(newFilters);
        setCurrentPage(1); // Reset to first page when filtering
      }, 300),
    [],
  );

  // Debounced global search
  const debouncedGlobalSearch = useMemo(
    () =>
      debounce<[string]>((search: string) => {
        setFilters((prev) => {
          const newFilters = { ...prev };
          if (search) {
            newFilters._global = search;
          } else {
            // eslint-disable-next-line @typescript-eslint/no-dynamic-delete
            delete newFilters._global;
          }
          return newFilters;
        });
        setCurrentPage(1);
      }, 300),
    [],
  );

  // Fetch data query
  const { data, isLoading, error, refetch } = useQuery<PaginatedResult<T>>({
    queryKey: ['paginatedData', currentPage, pageSize, sortBy, sortOrder, filters],
    queryFn: () =>
      fetchData({
        page: currentPage,
        pageSize,
        sortBy,
        sortOrder,
        filters,
      }),
    placeholderData: (prev) => prev,
  });

  // Handle sorting
  const handleSort = useCallback(
    (columnKey: string) => {
      if (sortBy === columnKey) {
        setSortOrder((prev) => (prev === 'asc' ? 'desc' : 'asc'));
      } else {
        setSortBy(columnKey);
        setSortOrder('asc');
      }
      setCurrentPage(1);
    },
    [sortBy],
  );

  // Handle column filter
  const handleColumnFilter = useCallback(
    (columnKey: string, value: string) => {
      const newFilters = { ...filters };
      if (value.trim()) {
        newFilters[columnKey] = value;
      } else {
        delete newFilters[columnKey];
      }
      debouncedUpdateFilters(newFilters);
    },
    [filters, debouncedUpdateFilters],
  );

  // Handle global search
  const handleGlobalSearch = useCallback(
    (value: string) => {
      setGlobalSearch(value);
      debouncedGlobalSearch(value);
    },
    [debouncedGlobalSearch],
  );

  // Handle pagination
  const handlePageChange = useCallback((page: number) => {
    setCurrentPage(page);
  }, [])

  // Generate pagination buttons
  const paginationButtons = useMemo(() => {
    if (data === null || data === undefined) {
return [];
}

    const { totalPages } = data;
    const buttons: (number | string)[] = [];
    const maxButtons = 7;

    if (totalPages <= maxButtons) {
      for (let i = 1; i <= totalPages; i++) {
        buttons.push(i);
      }
    } else {
      if (currentPage <= 4) {
        for (let i = 1; i <= 5; i++) {
          buttons.push(i);
        }
        buttons.push('...', totalPages);
      } else if (currentPage >= totalPages - 3) {
        buttons.push(1, '...');
        for (let i = totalPages - 4; i <= totalPages; i++) {
          buttons.push(i);
        }
      } else {
        buttons.push(1, '...');
        for (let i = currentPage - 1; i <= currentPage + 1; i++) {
          buttons.push(i);
        }
        buttons.push('...', totalPages);
      }
    }

    return buttons;
  }, [data, currentPage]);

  // Render sort icon
  const renderSortIcon = (columnKey: string): JSX.Element => {
    if (sortBy !== columnKey) {
      return <ArrowUpDown className="h-4 w-4 text-gray-400" />;
    }
    return sortOrder === 'asc' ? (
      <ArrowUp className="h-4 w-4 text-blue-600" />
    ) : (
      <ArrowDown className="h-4 w-4 text-blue-600" />
    );
  };

  if (error) {
    return (
      <div className="text-center py-8">
        <div className="text-red-600 mb-4">Failed to load data</div>
        <Button aria-label="Click button" onClick={() => {
 void refetch(); 
}}>
          Retry
        </Button>
      </div>
    );
  }

  return (
    <div className={`space-y-4 ${className}`}>
      {/* Global Search */}
      {enableGlobalSearch && (
        <div className="flex justify-between items-center">
          <Input
            className="max-w-md"
            placeholder="Search all columns..."
            value={globalSearch}
            onChange={(e) => {
 handleGlobalSearch(e.target.value); 
}}
          />
          {data && (
            <div className="text-sm text-gray-500">
              Showing {data.items.length} of {data.total} results
            </div>
          )}
        </div>
      )}

      {/* Table */}
      <div className="overflow-x-auto border rounded-lg">
        <table className="min-w-full divide-y divide-gray-200">
          <thead className="bg-gray-50">
            <tr>
              {columns.map((column, _index) => (
                <th
                  key={column.key as string}
                  className={`px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider ${
                    column.sortable === true ? 'cursor-pointer hover:bg-gray-100' : ''
                  }`}
                  style={{ width: column.width }}
                  onClick={column.sortable === true ? (): void => {
 handleSort(column.key as string); 
} : undefined}
                >
                  <div className="flex items-center space-x-1">
                    <span>{column.label}</span>
                    {column.sortable === true && renderSortIcon(column.key as string)}
                  </div>
                </th>
              ))}
            </tr>

            {/* Filter Row */}
            <tr className="bg-gray-25">
              {columns.map((column, _index) => (
                <th key={`filter-${column.key as string}`} className="px-6 py-2">
                  {column.filterable === true && (
                    <Input
                      className="text-sm"
                      placeholder={`Filter by ${column.label.toLowerCase()}...`}
                      value={(filters[column.key as string] as string) || ''}
                      onChange={(e) => {
 handleColumnFilter(column.key as string, e.target.value); 
}}
                    />
                  )}
                </th>
              ))}
            </tr>
          </thead>

          <tbody className="bg-white divide-y divide-gray-200">
            {isLoading ? (
              // Loading skeleton
              Array.from({ length: pageSize }).map((_, _index) => (
                <tr key={`skeleton-${_index}`}>
                  {columns.map((column, _colIndex) => (
                    <td key={`skeleton-${_index}-${column.key as string}`} className="px-6 py-4">
                      <LoadingSkeleton lines={1} variant="text" />
                    </td>
                  ))}
                </tr>
              ))
            ) : data?.items.length === 0 ? (
              <tr>
                <td className="px-6 py-8 text-center text-gray-500" colSpan={columns.length}>
                  {emptyStateMessage}
                </td>
              </tr>
            ) : (
              data?.items.map((item, _index) => (
                <tr key={_index} className="hover:bg-gray-50">
                  {columns.map((column, _index) => (
                    <td
                      key={column.key as string}
                      className="px-6 py-4 whitespace-nowrap text-sm text-gray-900"
                    >
                      {column.render
                        ? column.render(item[column.key], item)
                        : String(item[column.key] ?? '')}
                    </td>
                  ))}
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {/* Pagination */}
      {data && data.totalPages > 1 && (
        <div className="flex items-center justify-between">
          <div className="text-sm text-gray-700">
            Page {data.page} of {data.totalPages} ({data.total} total items)
          </div>

          <div className="flex space-x-1">
            <Button
              disabled={currentPage <= 1}
              size="sm"
              variant="outline"
              onClick={() => {
 handlePageChange(currentPage - 1); 
}}
            >
              <ChevronLeft className="h-4 w-4" />
              Previous
            </Button>

            {paginationButtons.map((page, _index) => (
              <Button
                key={_index}
                className={page === '...' ? 'cursor-default' : ''}
                disabled={page === '...'}
                size="sm"
                variant={page === currentPage ? 'primary' : 'outline'}
                onClick={() => {
 typeof page === 'number' ? handlePageChange(page) : undefined; 
}}
              >
                {page}
              </Button>
            ))}

            <Button
              disabled={currentPage >= (data.totalPages || 1)}
              size="sm"
              variant="outline"
              onClick={() => {
 handlePageChange(currentPage + 1); 
}}
            >
              Next
              <ChevronRight className="h-4 w-4" />
            </Button>
          </div>
        </div>
      )}

      {/* Loading overlay for data fetching */}
      {isLoading && data !== null && data !== undefined && (
        <div
          className="absolute inset-0 bg-white bg-opacity-75 flex items-center justify-center"
          data-testid="loading-skeleton"
        >
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600" />
        </div>
      )}
    </div>
  );
}

import { AlertTriangle, RefreshCw } from 'lucide-react';
import React, { useState, useCallback, useEffect, useRef } from 'react';

import { Button } from '../ui/Button';

import { LoadingSkeleton } from './LoadingSkeleton';

interface LoadDataResult<T> {
  data: T[];
  hasMore: boolean;
  total?: number;
}

interface ProgressiveDataLoaderProps<T> {
  loadData: (offset: number, limit: number) => Promise<LoadDataResult<T>>;
  renderItem: (item: T, index: number) => React.ReactNode;
  batchSize?: number;
  infiniteScroll?: boolean;
  threshold?: number; // Pixels from bottom to trigger load more
  className?: string;
  emptyState?: React.ReactNode;
  loadingState?: React.ReactNode;
  errorState?: React.ReactNode;
  onLoadMore?: (currentCount: number) => void;
}

export function ProgressiveDataLoader<T>({
  loadData,
  renderItem,
  batchSize = 20,
  infiniteScroll = false,
  threshold = 100,
  className = '',
  emptyState,
  loadingState,
  errorState,
  onLoadMore,
}: ProgressiveDataLoaderProps<T>): React.ReactElement {
  const [items, setItems] = useState<T[]>([]);
  const [loading, setLoading] = useState(false);
  const [loadingMore, setLoadingMore] = useState(false);
  const [hasMore, setHasMore] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [total, setTotal] = useState<number | undefined>();

  const containerRef = useRef<HTMLDivElement>(null);
  const isInitialLoad = useRef(true);

  const loadInitialData = useCallback(async () => {
    setLoading(true);
    setError(null);

    try {
      const result = await loadData(0, batchSize);
      setItems(result.data);
      setHasMore(result.hasMore);
      setTotal(result.total);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load data');
    } finally {
      setLoading(false);
    }
  }, [loadData, batchSize]);

  // Load initial data
  useEffect(() => {
    return (): void => { // Cleanup
    };

    if (isInitialLoad.current) {
      isInitialLoad.current = false;
      void loadInitialData();
    }
  }, [loadInitialData]);

  const loadMoreData = useCallback(async () => {
    if (loadingMore || !hasMore) {
return;
}

    setLoadingMore(true);
    setError(null);

    try {
      const result = await loadData(items.length, batchSize);
      setItems((prev) => [...prev, ...result.data]);
      setHasMore(result.hasMore);
      setTotal(result.total);
      onLoadMore?.(items.length + result.data.length);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load more data');
    } finally {
      setLoadingMore(false);
    }
  }, [loadData, items.length, batchSize, hasMore, loadingMore, onLoadMore]);

  // Infinite scroll handler
  const handleScroll = useCallback((): void => {
    if (!infiniteScroll || !containerRef.current) {
return;
}

    const { scrollTop, scrollHeight, clientHeight } = containerRef.current;
    const remainingScroll = scrollHeight - scrollTop - clientHeight;

    if (remainingScroll <= threshold && hasMore && !loadingMore) {
      void loadMoreData();
    }
  }, [infiniteScroll, threshold, hasMore, loadingMore, loadMoreData]);

  // Attach scroll listener for infinite scroll
  useEffect(() => {
    return (): void => { // Cleanup
    };

    if (!infiniteScroll) {
return;
}

    const container = containerRef.current;
    if (!container) {
return;
}

    container!.addEventListener('scroll', handleScroll);
    return (): void => {
 container!.removeEventListener('scroll', handleScroll); 
};
  }, [handleScroll, infiniteScroll]);

  const handleRetry = (): void => {
    setItems([]);
    setError(null);
    setHasMore(true);
    isInitialLoad.current = true;
    void loadInitialData();
  };

  // Error state
  if (error !== null && error !== undefined && error !== '' && items.length === 0) {
    return (
      <div className={`text-center py-8 ${className}`}>
        {errorState ?? (
          <>
            <AlertTriangle className="h-12 w-12 text-red-500 mx-auto mb-4" />
            <div className="text-red-600 mb-4">Failed to load data</div>
            <div className="text-gray-500 text-sm mb-4">{error}</div>
            <Button aria-label="Click button" onClick={handleRetry}>
              <RefreshCw className="h-4 w-4 mr-2" />
              Retry
            </Button>
          </>
        )}
      </div>
    );
  }

  // Loading state for initial load
  if (loading && items.length === 0) {
    return (
      <div className={className} data-testid="progressive-loader-container">
        {loadingState ?? (
          <div className="space-y-4">
            {Array.from({ length: Math.min(batchSize, 10) }).map((_, index) => (
              <LoadingSkeleton key={index} variant="card" />
            ))}
          </div>
        )}
      </div>
    );
  }

  // Empty state
  if (items.length === 0 && !loading) {
    return (
      <div className={`text-center py-8 ${className}`}>
        {emptyState ?? (
          <>
            <div className="text-gray-500 text-lg mb-2">No items found</div>
            <div className="text-gray-400 text-sm">Try adjusting your search criteria</div>
          </>
        )}
      </div>
    );
  }

  return (
    <div
      ref={containerRef}
      className={`${className} ${infiniteScroll ? 'overflow-auto' : ''}`}
      data-testid="progressive-loader-container"
      style={infiniteScroll ? { maxHeight: '600px' } : undefined}
    >
      {/* Progress indicator */}
      {total !== null && total !== undefined && total > 0 && (
        <div className="mb-4 text-sm text-gray-500">
          Showing {items.length} of {total} items
          {items.length < total && ` (${((items.length / total) * 100).toFixed(1)}% loaded)`}
        </div>
      )}

      {/* Items */}
      <div className="space-y-2">
        {items.map((item, index) => (
          <div key={index}>{renderItem(item, index)}</div>
        ))}
      </div>

      {/* Load more section */}
      {hasMore && (
        <div className="mt-6 text-center">
          {loadingMore ? (
            <div className="py-4">
              <div className="animate-spin rounded-full h-6 w-6 border-b-2 border-blue-600 mx-auto mb-2" />
              <div className="text-sm text-gray-500">Loading...</div>
            </div>
          ) : !infiniteScroll ? (
            <Button
              className="min-w-[120px]"
              disabled={loadingMore}
              variant="outline"
              onClick={(): void => { void loadMoreData(); }}
            >
              Load More
            </Button>
          ) : (
            <div className="py-2 text-xs text-gray-400">Scroll down to load more items</div>
          )}
        </div>
      )}

      {/* End of results indicator */}
      {!hasMore && items.length > 0 && (
        <div className="mt-6 text-center">
          <div className="text-sm text-gray-500 py-4 border-t">
            {total !== null && total !== undefined && total > 0 ? `All ${total} items loaded` : 'All items loaded'}
          </div>
        </div>
      )}

      {/* Error state for load more */}
      {error !== null && error !== undefined && error !== '' && items.length > 0 && (
        <div className="mt-4 text-center">
          <div className="text-red-600 text-sm mb-2">Failed to load more items</div>
          <Button aria-label="Click button" onClick={() => { void loadMoreData(); }}>
            Try Again
          </Button>
        </div>
      )}
    </div>
  );
}

