import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
// Type-safe debounce implementation with cancel
type DebounceFunction<T extends unknown[]> = {
  (...args: T): void;
  cancel(): void;
};

const debounce = <T extends unknown[]>(
  func: (...args: T) => void,
  wait: number,
): DebounceFunction<T> => {
  let timeout: ReturnType<typeof setTimeout>;

  const debounced = (...args: T): void => {
    clearTimeout(timeout);
    timeout = setTimeout((): void => { func(...args); }, wait);
  };

  debounced.cancel = (): void => {
    clearTimeout(timeout);
  };

  return debounced;
};

interface VirtualizedListProps<T> {
  items: T[];
  itemHeight: number;
  height: number;
  renderItem: (props: { item: T; index: number; style: React.CSSProperties }) => React.ReactNode;
  onScrollEnd?: (scrollTop: number) => void;
  overscan?: number;
  className?: string;
  estimatedItemHeight?: number;
}

export function VirtualizedList<T>({
  items,
  itemHeight,
  height,
  renderItem,
  onScrollEnd,
  overscan = 5,
  className = '',
  estimatedItemHeight,
}: VirtualizedListProps<T>): JSX.Element {
  const [scrollTop, setScrollTop] = useState(0);
  const containerRef = useRef<HTMLDivElement>(null);

  // Calculate visible range
  const visibleRange = useMemo(() => {
    const containerHeight = height;
    const itemCount = items.length;

    if (itemCount === 0) {
      return { start: 0, end: 0 };
    }

    const effectiveItemHeight = estimatedItemHeight ?? itemHeight;
    const startIndex = Math.floor(scrollTop / effectiveItemHeight);
    const endIndex = Math.min(
      itemCount - 1,
      Math.ceil((scrollTop + containerHeight) / effectiveItemHeight),
    );

    return {
      start: Math.max(0, startIndex - overscan),
      end: Math.min(itemCount - 1, endIndex + overscan),
    };
  }, [scrollTop, height, items.length, itemHeight, estimatedItemHeight, overscan]);

  // Visible items
  const visibleItems = useMemo(() => {
    const result: { index: number; item: T }[] = [];
    for (let i = visibleRange.start; i <= visibleRange.end; i++) {
      if (i < items.length) {
        result.push({
          index: i,
          item: items[i],
        });
      }
    }
    return result;
  }, [items, visibleRange.start, visibleRange.end]);

  // Total height for scrollbar
  const totalHeight = useMemo(() => items.length * itemHeight, [items.length, itemHeight]);

  // Debounced scroll end handler
  const debouncedScrollEnd = useMemo(
    () =>
      debounce<[number]>((scrollTop: number) => {
        onScrollEnd?.(scrollTop);
      }, 150),
    [onScrollEnd],
  );

  // Handle scroll
  const handleScroll = useCallback(
    (e: React.UIEvent<HTMLDivElement>) => {
      const newScrollTop = e.currentTarget.scrollTop;
      setScrollTop(newScrollTop);
      debouncedScrollEnd(newScrollTop);
    },
    [debouncedScrollEnd],
  );

  // Cleanup debounced function
  useEffect((): (() => void) => () => {
      debouncedScrollEnd.cancel();
    }, [debouncedScrollEnd]);

  // Scroll to position (useful for external control)
  const _scrollToIndex = useCallback(
    (index: number, align: 'start' | 'center' | 'end' = 'start') => {
      if (!containerRef.current) {
return;
}

      let scrollTop = index * itemHeight;

      if (align === 'center') {
        scrollTop -= height / 2 - itemHeight / 2;
      } else if (align === 'end') {
        scrollTop -= height - itemHeight;
      }

      containerRef.current.scrollTop = Math.max(0, scrollTop);
    },
    [itemHeight, height],
  );

  // Note: For external scroll methods, use the returned containerRef.current.scrollTop directly
  // and call scrollToIndex from the component instance

  return (
    <div
      ref={containerRef}
      className={`overflow-auto ${className}`}
      data-testid="virtualized-list-container"
      style={{ height }}
      onScroll={handleScroll}
    >
      <div
        style={{
          height: totalHeight,
          position: 'relative',
        }}
      >
        {visibleItems.map(({ item, index }) => {
          const style: React.CSSProperties = {
            position: 'absolute',
            top: index * itemHeight,
            left: 0,
            right: 0,
            height: itemHeight,
          };

          return (
            <div key={index} style={style}>
              {renderItem({ item, index, style })}
            </div>
          );
        })}
      </div>
    </div>
  );
}

// HOC for memoizing items
export function withVirtualizedMemo<T>(
  Component: React.ComponentType<{ item: T; index: number; style: React.CSSProperties }>,
): React.ComponentType<{ item: T; index: number; style: React.CSSProperties }> {
  return React.memo(Component, (prevProps, nextProps) => (
      prevProps.index === nextProps.index &&
      prevProps.item === nextProps.item &&
      prevProps.style.top === nextProps.style.top &&
      prevProps.style.height === nextProps.style.height
    ));
}

import { useEffect } from 'react';

import { safeJsonParse } from '../../utils/typeGuards';

interface Props {
  filters: Record<string, boolean>;
  onChange: (f: Record<string, boolean>) => void;
}

const TAGS = ['HandsOn', 'Worksheet', 'Video'];
const STORAGE_KEY = 'te:planner:filters';

export default function PlannerFilters({ filters, onChange }: Props): React.ReactElement {
  useEffect(() => {
    return () => { // Cleanup
    };

    if (typeof window !== 'undefined') {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(filters));
    }
  }, [filters]);

  return (
    <div className="flex gap-2" title="Filter suggested activities">
      {TAGS.map((t, _index) => (
        <label key={t} className="inline-flex items-center gap-1" title={`Show ${t} activities`}>
          <input
            checked={filters[t] ?? true}
            type="checkbox"
            onChange={(e) => {
 onChange({ ...filters, [t]: e.target.checked }); 
}}
          />
          {t}
        </label>
      ))}
    </div>
  );
}

export function loadPlannerFilters(): Record<string, boolean> {
  if (typeof window === 'undefined') {
return {};
}
  const stored = localStorage.getItem(STORAGE_KEY);
  return stored ? (safeJsonParse(stored, {}) as Record<string, boolean>) : {};
}

import { useMutation, useQueryClient } from '@tanstack/react-query';
import React, { useState } from 'react';

import { apiClient } from '../../api/core/client';
import { Button } from '../ui/Button';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '../ui/Dialog';
import { Input } from '../ui/Input';
import { Label } from '../ui/Label';
import { Textarea } from '../ui/Textarea';
import { useToast } from '../ui/use-toast';

interface AISuggestedActivity {
  id: number;
  expectationId: string; // Updated for ETFO alignment
  userId: number;
  title: string;
  descriptionFr: string;
  descriptionEn?: string;
  materials: string[];
  duration: number;
  theme?: string;
  createdAt: string;
  updatedAt: string;
}

interface AISuggestionModalProps {
  suggestion: AISuggestedActivity;
  open: boolean;
  onClose: () => void;
  onAddToWeek?: (activity: AISuggestedActivity) => void;
}

export function AISuggestionModal({
  suggestion,
  open,
  onClose,
  onAddToWeek,
}: AISuggestionModalProps): React.ReactElement {
  const queryClient = useQueryClient();
  const { toast } = useToast();
  const [isEditing, setIsEditing] = useState(false);
  const [editedSuggestion, setEditedSuggestion] = useState({
    title: suggestion.title,
    descriptionFr: suggestion.descriptionFr,
    descriptionEn: suggestion.descriptionEn ?? '',
    materials: suggestion.materials.join(', '),
    duration: suggestion.duration,
    theme: suggestion.theme ?? '',
  });

  // Delete suggestion mutation
  const deleteSuggestion = useMutation({
    mutationFn: async () => {
      await apiClient.delete(`/ai-suggestions/suggestions/${suggestion.id}`);
    },
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: ['uncovered-outcomes'] });
      toast({
        title: 'Suggestion deleted',
        description: 'The AI suggestion has been removed.',
      });
      onClose();
    },
  });

  // Save to library (for future implementation)
  const saveToLibrary = (): void => {
    toast({
      title: 'Saved to library',
      description: 'This activity has been saved for future use.',
      variant: 'default',
    });
  };

  const handleAddToWeek = (): void => {
    if (onAddToWeek !== null && onAddToWeek !== undefined) {
      // If editing, create a modified version
      const activityToAdd = isEditing
        ? {
            ...suggestion,
            title: editedSuggestion.title,
            descriptionFr: editedSuggestion.descriptionFr,
            descriptionEn: editedSuggestion.descriptionEn,
            materials: editedSuggestion.materials
              .split(',')
              .map((m) => m.trim())
              .filter((m): m is string => m !== null && m !== undefined && m !== ''),
            duration: editedSuggestion.duration,
            theme: editedSuggestion.theme,
          }
        : suggestion;

      onAddToWeek(activityToAdd);
      onClose();
    }
  };

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>AI Suggested Activity</DialogTitle>
          <DialogDescription>
            Review and customize this AI-generated activity before adding it to your plan.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-4">
          {/* Title */}
          <div className="space-y-2">
            <Label htmlFor="title">Title</Label>
            {isEditing ? (
              <Input
                id="title"
                value={editedSuggestion.title}
                onChange={(e) => {
 setEditedSuggestion({
                    ...editedSuggestion,
                    title: e.target.value,
                  }); 
}
                }
              />
            ) : (
              <p className="text-sm font-medium">{suggestion.title}</p>
            )}
          </div>

          {/* Duration */}
          <div className="space-y-2">
            <Label className="flex items-center gap-2" htmlFor="duration">
              <span>⏰</span>
              Duration (minutes)
            </Label>
            {isEditing ? (
              <Input
                id="duration"
                type="number"
                value={editedSuggestion.duration}
                onChange={(e) => {
 setEditedSuggestion({
                    ...editedSuggestion,
                    duration: parseInt(e.target.value) || 0,
                  }); 
}
                }
              />
            ) : (
              <p className="text-sm">{suggestion.duration} minutes</p>
            )}
          </div>

          {/* French Description */}
          <div className="space-y-2">
            <Label htmlFor="descriptionFr">Description (Français)</Label>
            {isEditing ? (
              <Textarea
                id="descriptionFr"
                rows={4}
                value={editedSuggestion.descriptionFr}
                onChange={(e) => {
 setEditedSuggestion({
                    ...editedSuggestion,
                    descriptionFr: e.target.value,
                  }); 
}
                }
              />
            ) : (
              <p className="text-sm whitespace-pre-wrap">{suggestion.descriptionFr}</p>
            )}
          </div>

          {/* English Description */}
          <div className="space-y-2">
            <Label htmlFor="descriptionEn">Description (English)</Label>
            {isEditing ? (
              <Textarea
                id="descriptionEn"
                placeholder="Optional English description for teacher reference"
                rows={3}
                value={editedSuggestion.descriptionEn}
                onChange={(e) => {
 setEditedSuggestion({
                    ...editedSuggestion,
                    descriptionEn: e.target.value,
                  }); 
}
                }
              />
            ) : (
              <p className="text-sm whitespace-pre-wrap text-gray-600">
                {(suggestion.descriptionEn !== undefined && suggestion.descriptionEn !== '') ? suggestion.descriptionEn : 'No English description provided'}
              </p>
            )}
          </div>

          {/* Materials */}
          <div className="space-y-2">
            <Label className="flex items-center gap-2" htmlFor="materials">
              <span>📦</span>
              Materials Needed
            </Label>
            {isEditing ? (
              <Input
                id="materials"
                placeholder="Comma-separated list of materials"
                value={editedSuggestion.materials}
                onChange={(e) => {
 setEditedSuggestion({
                    ...editedSuggestion,
                    materials: e.target.value,
                  }); 
}
                }
              />
            ) : (
              <div className="flex flex-wrap gap-2">
                {suggestion.materials.map((material, _index) => (
                  <span key={_index} className="px-2 py-1 bg-gray-100 rounded-md text-sm">
                    {material}
                  </span>
                ))}
              </div>
            )}
          </div>

          {/* Theme */}
          {((suggestion.theme !== undefined && suggestion.theme !== '') || isEditing) ? (
            <div className="space-y-2">
              <Label htmlFor="theme">Theme</Label>
              {isEditing ? (
                <Input
                  id="theme"
                  placeholder="Optional theme connection"
                  value={editedSuggestion.theme}
                  onChange={(e) => {
 setEditedSuggestion({
                      ...editedSuggestion,
                      theme: e.target.value,
                    }); 
}
                  }
                />
              ) : (
                <p className="text-sm">
                  <span className="px-2 py-1 bg-blue-100 text-blue-700 rounded-md">
                    {suggestion.theme}
                  </span>
                </p>
              )}
            </div>
          ) : null}
        </div>

        <DialogFooter className="flex flex-col sm:flex-row gap-2">
          <div className="flex gap-2 flex-1">
            <Button aria-label="Click button" onClick={() => {
 setIsEditing(!isEditing); 
}}>
              {isEditing ? 'Cancel Edit' : 'Edit'}
            </Button>
            <Button
              disabled={deleteSuggestion.isPending}
              variant="outline"
              onClick={() => {
 deleteSuggestion.mutate(); 
}}
            >
              <span className="mr-2">🗑️</span>
              Discard
            </Button>
          </div>
          <div className="flex gap-2">
            <Button aria-label="Click button" onClick={saveToLibrary}>
              <span className="mr-2">🔖</span>
              Save to Library
            </Button>
            <Button aria-label="Click button" onClick={handleAddToWeek}>
              <span className="mr-2">+</span>
              Add to Week Plan
            </Button>
          </div>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { Sparkles, RefreshCw, Copy, Check } from 'lucide-react';
import React, { useState } from 'react';

import type { AISuggestion } from '@/hooks/useAIPlanningAssistant';

import { Alert, AlertDescription } from '../ui/alert';
import { Badge } from '../ui/Badge';
import { Button } from '../ui/Button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '../ui/card';
import { useToast } from '../ui/use-toast';

interface AISuggestionPanelProps {
  title: string;
  description?: string;
  suggestions: AISuggestion | null;
  isGenerating: boolean;
  onGenerate: () => void;
  onAcceptSuggestion: (suggestion: string) => void;
  onAcceptAll?: () => void;
  error?: Error | null;
}

export default function AISuggestionPanel({
  title,
  description,
  suggestions,
  isGenerating,
  onGenerate,
  onAcceptSuggestion,
  onAcceptAll,
  error,
}: AISuggestionPanelProps): React.ReactElement {
  const { toast } = useToast();
  const [acceptedIndices, setAcceptedIndices] = useState<Set<number>>(new Set());
  const [copiedIndex, setCopiedIndex] = useState<number | null>(null);

  const handleCopy = (suggestion: string, index: number): void => {
    void navigator.clipboard.writeText(suggestion);
    setCopiedIndex(index);
    setTimeout((): void => {
 setCopiedIndex(null); 
}, 2000);
    toast({
      title: 'Copied',
      description: 'Suggestion copied to clipboard',
    });
  };

  const handleAccept = (suggestion: string, index: number): void => {
    onAcceptSuggestion(suggestion);
    setAcceptedIndices(new Set([...acceptedIndices, index]));
    toast({
      title: 'Accepted',
      description: 'Suggestion added to your plan',
    });
  };

  const handleAcceptAll = (): void => {
    if (onAcceptAll !== null && onAcceptAll !== undefined) {
      onAcceptAll();
      const allIndices = new Set(suggestions?.suggestions.map((_, i) => i) || []);
      setAcceptedIndices(allIndices);
      toast({
        title: 'All Accepted',
        description: 'All suggestions added to your plan',
      });
    }
  };

  return (
    <Card className="border-dashed">
      <CardHeader>
        <div className="flex items-center justify-between">
          <div>
            <CardTitle className="flex items-center gap-2">
              <Sparkles className="h-5 w-5 text-purple-500" />
              {title}
            </CardTitle>
            {description !== null && description !== undefined && description !== '' && <CardDescription>{description}</CardDescription>}
          </div>
          <Button
            className="gap-2"
            disabled={isGenerating}
            size="sm"
            variant="outline"
            onClick={onGenerate}
          >
            {isGenerating ? (
              <>
                <RefreshCw className="h-4 w-4 animate-spin" />
                Generating...
              </>
            ) : (
              <>
                <Sparkles className="h-4 w-4" />
                Generate Suggestions
              </>
            )}
          </Button>
        </div>
      </CardHeader>
      <CardContent>
        {error && (
          <Alert className="mb-4" variant="destructive">
            <AlertDescription>Failed to generate suggestions. Please try again.</AlertDescription>
          </Alert>
        )}

        {suggestions && suggestions.suggestions.length > 0 && (
          <div className="space-y-3">
            {suggestions.rationale && (
              <p className="text-sm text-muted-foreground italic">{suggestions.rationale}</p>
            )}

            <div className="space-y-2">
              {suggestions.suggestions.map((suggestion, index) => (
                <div
                  key={index}
                  className={`p-3 rounded-lg border transition-colors ${
                    acceptedIndices.has(index)
                      ? 'bg-green-50 border-green-300'
                      : 'bg-muted/50 hover:bg-muted'
                  }`}
                >
                  <div className="flex items-start justify-between gap-2">
                    <p className="text-sm flex-1">{suggestion}</p>
                    <div className="flex gap-1">
                      <Button
                        className="h-8 w-8 p-0"
                        size="sm"
                        variant="ghost"
                        onClick={() => {
 handleCopy(suggestion, index); 
}}
                      >
                        {copiedIndex === index ? (
                          <Check className="h-4 w-4 text-green-500" />
                        ) : (
                          <Copy className="h-4 w-4" />
                        )}
                      </Button>
                      {!acceptedIndices.has(index) && (
                        <Button
                          className="h-8 w-8 p-0"
                          size="sm"
                          variant="ghost"
                          onClick={() => {
 handleAccept(suggestion, index); 
}}
                        >
                          <Check className="h-4 w-4 text-green-500" />
                        </Button>
                      )}
                    </div>
                  </div>
                  {acceptedIndices.has(index) && (
                    <Badge className="mt-2 text-xs" variant="secondary">
                      Accepted
                    </Badge>
                  )}
                </div>
              ))}
            </div>

            {onAcceptAll !== null && onAcceptAll !== undefined && acceptedIndices.size < suggestions.suggestions.length && (
              <Button aria-label="Click button" onClick={handleAcceptAll}>
                Accept All Suggestions
              </Button>
            )}
          </div>
        )}

        {suggestions !== null && suggestions !== undefined && suggestions.suggestions.length === 0 && (
          <div className="text-center py-8 text-muted-foreground">
            <Sparkles className="h-8 w-8 mx-auto mb-2 opacity-20" />
            <p className="text-sm">No suggestions generated. Try adjusting your input.</p>
          </div>
        )}

        {!suggestions && !isGenerating && !error && (
          <div className="text-center py-8 text-muted-foreground">
            <Sparkles className="h-8 w-8 mx-auto mb-2 opacity-20" />
            <p className="text-sm">Click generate to get AI-powered suggestions</p>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

import { Globe2, Eye, EyeOff } from 'lucide-react';
import React from 'react';

import { useLanguage } from '../../contexts/LanguageContext';
import { Button } from '../ui/Button';

interface BilingualPlanViewProps {
  children: React.ReactNode;
  mode?: 'side-by-side' | 'toggle' | 'overlay';
  defaultMode?: 'side-by-side' | 'toggle' | 'overlay';
}

export default function BilingualPlanView({ 
  children, 
  mode: controlledMode,
  defaultMode = 'toggle' 
}: BilingualPlanViewProps): React.ReactElement {
  const { t, language } = useLanguage();
  const [viewMode, setViewMode] = React.useState(controlledMode ?? defaultMode);
  const [showEnglish, setShowEnglish] = React.useState(true);
  const [showFrench, setShowFrench] = React.useState(true);

  // Allow controlled mode
  const activeMode = controlledMode ?? viewMode;

  const renderSideBySide = (): React.ReactElement => (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
      <div className="space-y-4">
        <div className="flex items-center justify-between bg-blue-50 p-3 rounded-t-lg">
          <h3 className="font-medium text-blue-900 flex items-center gap-2">
            <span className="text-lg">🇨🇦</span> English
          </h3>
          <Button
            size="sm"
            type="button"
            variant="ghost"
            onClick={() => {
 setShowEnglish(!showEnglish); 
}}
          >
            {showEnglish ? <Eye className="h-4 w-4" /> : <EyeOff className="h-4 w-4" />}
          </Button>
        </div>
        {showEnglish && (
          <div className="p-4 border border-t-0 rounded-b-lg">
            {React.cloneElement(children as React.ReactElement, { language: 'en' })}
          </div>
        )}
      </div>

      <div className="space-y-4">
        <div className="flex items-center justify-between bg-green-50 p-3 rounded-t-lg">
          <h3 className="font-medium text-green-900 flex items-center gap-2">
            <span className="text-lg">🇫🇷</span> Français
          </h3>
          <Button
            size="sm"
            type="button"
            variant="ghost"
            onClick={() => {
 setShowFrench(!showFrench); 
}}
          >
            {showFrench ? <Eye className="h-4 w-4" /> : <EyeOff className="h-4 w-4" />}
          </Button>
        </div>
        {showFrench && (
          <div className="p-4 border border-t-0 rounded-b-lg">
            {React.cloneElement(children as React.ReactElement, { language: 'fr' })}
          </div>
        )}
      </div>
    </div>
  );

  const renderToggle = (): React.ReactElement => (
    <div className="space-y-4">
      <div className="flex items-center gap-4 mb-4">
        <span className="text-sm font-medium text-gray-700">{t('teaching_language')}:</span>
        <div className="flex gap-2">
          <Button
            className="flex items-center gap-2"
            size="sm"
            type="button"
            variant={language === 'en' ? 'primary' : 'outline'}
            onClick={() => {
 setShowEnglish(true); setShowFrench(false); 
}}
          >
            <span>🇨🇦</span> English
          </Button>
          <Button
            className="flex items-center gap-2"
            size="sm"
            type="button"
            variant={language === 'fr' ? 'primary' : 'outline'}
            onClick={() => {
 setShowFrench(true); setShowEnglish(false); 
}}
          >
            <span>🇫🇷</span> Français
          </Button>
        </div>
      </div>
      {children}
    </div>
  );

  const renderOverlay = (): React.ReactElement => (
    <div className="relative">
      <div className="absolute top-2 right-2 z-10">
        <div className="bg-white rounded-lg shadow-sm border p-2 flex gap-2">
          <button
            className={`p-1.5 rounded ${showEnglish ? 'bg-blue-100 text-blue-700' : 'text-gray-400'}`}
            title="Toggle English"
            type="button"
            onClick={() => {
 setShowEnglish(!showEnglish); 
}}
          >
            <span className="text-sm">🇨🇦</span>
          </button>
          <button
            className={`p-1.5 rounded ${showFrench ? 'bg-green-100 text-green-700' : 'text-gray-400'}`}
            title="Toggle French"
            type="button"
            onClick={() => {
 setShowFrench(!showFrench); 
}}
          >
            <span className="text-sm">🇫🇷</span>
          </button>
        </div>
      </div>

      <div className="space-y-6">
        {showEnglish && showFrench ? (
          // Show both with visual distinction
          <div className="space-y-4">
            <div className="border-l-4 border-blue-400 pl-4">
              {React.cloneElement(children as React.ReactElement, { language: 'en' })}
            </div>
            <div className="border-l-4 border-green-400 pl-4">
              {React.cloneElement(children as React.ReactElement, { language: 'fr' })}
            </div>
          </div>
        ) : showEnglish ? (
          React.cloneElement(children as React.ReactElement, { language: 'en' })
        ) : showFrench ? (
          React.cloneElement(children as React.ReactElement, { language: 'fr' })
        ) : (
          <div className="text-center text-gray-500 py-8">
            {t('no_language_selected', 'Please select at least one language to view')}
          </div>
        )}
      </div>
    </div>
  );

  return (
    <div className="bilingual-plan-view">
      <div className="flex items-center justify-between mb-6">
        <h2 className="text-lg font-semibold flex items-center gap-2">
          <Globe2 className="h-5 w-5" />
          {t('bilingual_content')}
        </h2>

        <div className="flex gap-2">
          <Button
            size="sm"
            type="button"
            variant={activeMode === 'side-by-side' ? 'primary' : 'outline'}
            onClick={() => {
 setViewMode('side-by-side'); 
}}
          >
            {t('side_by_side', 'Side by Side')}
          </Button>
          <Button
            size="sm"
            type="button"
            variant={activeMode === 'toggle' ? 'primary' : 'outline'}
            onClick={() => {
 setViewMode('toggle'); 
}}
          >
