  isOpen, 
  onClose, 
  planType, 
  planId, 
  planTitle 
}: DuplicatePlanModalProps): React.ReactElement {
  const queryClient = useQueryClient();
  const [selectedType, setSelectedType] = useState(planType ?? '');
