                  <SelectValue placeholder="Select plan type" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="long-range">
                    <div className="flex items-center gap-2">
                      <Calendar className="h-4 w-4" />
                      Long-Range Plan
                    </div>
                  </SelectItem>
                  <SelectItem value="unit">
                    <div className="flex items-center gap-2">
                      <BookOpen className="h-4 w-4" />
                      Unit Plan
                    </div>
                  </SelectItem>
                  <SelectItem value="lesson">
                    <div className="flex items-center gap-2">
                      <GraduationCap className="h-4 w-4" />
                      Lesson Plan
                    </div>
                  </SelectItem>
                </SelectContent>
              </Select>
            </div>
          ) : null}

          {(selectedType !== '' || planType !== undefined) && planId === undefined ? (
            <div>
              <Label htmlFor="input">Select Plan to Duplicate</Label>
              <Select value={selectedPlanId} onValueChange={setSelectedPlanId}>
                <SelectTrigger className="mt-1">
                  <SelectValue placeholder="Choose a plan" />
                </SelectTrigger>
                <SelectContent>
                  {(availablePlans[selectedType as keyof typeof availablePlans] ?? []).map((plan: PlanItem, _index) => (
                    <SelectItem key={plan.id} value={plan.id}>
