interface PlanningWizardProps {
  currentLevel?: ETFOLevel;
  completedLevels?: ETFOLevel[];
  onClose?: () => void;
}

export function PlanningWizard({ 
  currentLevel: _currentLevel, 
  completedLevels = [], 
  onClose 
}: PlanningWizardProps): React.ReactElement {
  const navigate = useNavigate();
  const [currentStep, setCurrentStep] = useState(0);

  const currentStepData = WIZARD_STEPS[currentStep];
  const isFirstStep = currentStep === 0;
  const isLastStep = currentStep === WIZARD_STEPS.length - 1;
  const isStepCompleted = completedLevels.includes(currentStepData.id);

  const handleNext = (): void => {
    if (isLastStep) {
      onClose?.();
    } else {
      setCurrentStep(currentStep + 1);
    }
  };

  const handlePrevious = (): void => {
    if (!isFirstStep) {
      setCurrentStep(currentStep - 1);
    }
  };

  const handleStartStep = (): void => {
    navigate(currentStepData.route);
  };

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
      <Card className="max-w-2xl w-full max-h-[90vh] overflow-hidden">
        <CardHeader className="relative">
          <div className="absolute right-4 top-4">
            <Button
              className="text-gray-500 hover:text-gray-700"
              size="sm"
              variant="ghost"
              onClick={onClose}
            >
              ✕
            </Button>
          </div>

          <CardTitle className="text-2xl">Planning Wizard</CardTitle>
          <CardDescription>
            Let&apos;s walk through the ETFO planning process step by step
          </CardDescription>

          {/* Progress indicators */}
          <div className="flex items-center gap-2 mt-4">
            {WIZARD_STEPS.map((step, index) => (
              <div
                key={step.id}
                className={cn(
                  'flex-1 h-2 rounded-full transition-colors',
                  index === currentStep 
                    ? 'bg-indigo-600' 
                    : index < currentStep || completedLevels.includes(step.id)
                    ? 'bg-green-600'
                    : 'bg-gray-200'
                )}
              />
            ))}
          </div>
        </CardHeader>

        <CardContent className="space-y-6">
          {/* Step content */}
          <div className="space-y-4">
            <div className="flex items-start gap-4">
              <div className={cn(
                'p-3 rounded-lg flex-shrink-0',
                isStepCompleted ? 'bg-green-100' : 'bg-indigo-100'
              )}>
                {isStepCompleted ? (
                  <CheckCircle className="h-6 w-6 text-green-600" />
                ) : (
                  <div className={isStepCompleted ? 'text-green-700' : 'text-indigo-700'}>
                    {currentStepData.icon}
                  </div>
                )}
              </div>

              <div className="flex-1">
                <div className="flex items-center gap-2 mb-2">
                  <h3 className="text-lg font-semibold">
                    Step {currentStep + 1}: {currentStepData.title}
                  </h3>
                  {currentStepData.isAIAssisted === true && (
                    <span className="inline-flex items-center gap-1 text-xs bg-indigo-100 text-indigo-700 px-2 py-0.5 rounded-full">
                      <Sparkles className="h-3 w-3" />
                      AI-Assisted
                    </span>
                  )}
                </div>

                <p className="text-gray-600 mb-4">{currentStepData.description}</p>

                <div className="bg-gray-50 rounded-lg p-4 space-y-3">
                  <h4 className="font-medium text-sm text-gray-700">Tips for this step:</h4>
                  <ul className="space-y-2">
                    {currentStepData.tips.map((tip, index) => (
                      <li key={index} className="flex items-start gap-2 text-sm text-gray-600">
                        <span className="text-indigo-600 mt-0.5">•</span>
                        <span>{tip}</span>
                      </li>
                    ))}
                  </ul>

                  <div className="pt-2 border-t border-gray-200">
                    <p className="text-xs text-gray-500">
                      ⏱ Estimated time: {currentStepData.estimatedTime}
                    </p>
                  </div>
                </div>

                {isStepCompleted && (
                  <div className="mt-4 p-3 bg-green-50 rounded-lg flex items-center gap-2">
                    <CheckCircle className="h-4 w-4 text-green-600 flex-shrink-0" />
                    <p className="text-sm text-green-800">
                      You&apos;ve completed this step! Feel free to revisit it anytime.
                    </p>
                  </div>
                )}
              </div>
            </div>
          </div>

          {/* Action buttons */}
          <div className="flex items-center justify-between pt-6 border-t">
            <Button
              className="gap-2"
              disabled={isFirstStep}
              variant="outline"
              onClick={handlePrevious}
            >
              <ChevronLeft className="h-4 w-4" />
              Previous
            </Button>

            <Button
              className="bg-indigo-600 hover:bg-indigo-700 text-white gap-2"
              onClick={handleStartStep}
            >
              {isStepCompleted ? 'Revisit' : 'Start'} This Step
              <ArrowRight className="h-4 w-4" />
            </Button>

            <Button
              className="gap-2"
              variant="outline"
              onClick={handleNext}
            >
              {isLastStep ? 'Finish' : 'Next'}
              <ChevronRight className="h-4 w-4" />
            </Button>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

import { CheckCircle2, Circle, Lock } from 'lucide-react';
import React from 'react';
import { Link } from 'react-router-dom';

import { cn } from '@/lib/utils';

import type { LevelProgress } from '../../hooks/useWorkflowState';
import { ETFOLevel, ETFO_LEVEL_PATHS } from '../../hooks/useWorkflowState';
import { Badge } from '../ui/Badge';

interface PlanningWorkflowIndicatorProps {
  progress: LevelProgress[];
  currentLevel: ETFOLevel;
  className?: string;
}

const _LEVEL_DISPLAY_NAMES: Record<ETFOLevel, string> = {
  [ETFOLevel.CURRICULUM_EXPECTATIONS]: 'Curriculum',
  [ETFOLevel.LONG_RANGE_PLANS]: 'Long-Range',
  [ETFOLevel.UNIT_PLANS]: 'Unit Plans',
  [ETFOLevel.LESSON_PLANS]: 'Lessons',
  [ETFOLevel.DAYBOOK_ENTRIES]: 'Daybook',
};

const _LEVEL_DESCRIPTIONS: Record<ETFOLevel, string> = {
  [ETFOLevel.CURRICULUM_EXPECTATIONS]: 'Import and organize curriculum expectations',
  [ETFOLevel.LONG_RANGE_PLANS]: 'Create yearly overview with themes and timing',
  [ETFOLevel.UNIT_PLANS]: 'Design detailed unit plans with activities',
  [ETFOLevel.LESSON_PLANS]: 'Plan individual lessons with three-part structure',
  [ETFOLevel.DAYBOOK_ENTRIES]: 'Reflect on lessons and note teaching observations',
};

export function PlanningWorkflowIndicator({
  progress,
  currentLevel,
  className,
}: PlanningWorkflowIndicatorProps): React.ReactElement {
  const getStepIcon = (level: LevelProgress): React.ReactElement => {
    if (level.isComplete) {
      return <CheckCircle2 className="h-5 w-5 text-green-600" />;
    } else if (!level.isAccessible) {
      return <Lock className="h-5 w-5 text-gray-400" />;
    } else if (level.level === currentLevel) {
      return <Circle className="h-5 w-5 text-indigo-600 animate-pulse" />;
    } 
      return <Circle className="h-5 w-5 text-gray-400" />;

  };

  const getStepStyles = (level: LevelProgress): string => {
    if (level.isComplete) {
      return 'border-green-600 bg-green-50';
    } else if (!level.isAccessible) {
      return 'border-gray-300 bg-gray-50';
    } else if (level.level === currentLevel) {
      return 'border-indigo-600 bg-indigo-50';
    } 
      return 'border-gray-300 bg-white hover:bg-gray-50';

  };

  const canNavigate = (level: LevelProgress): boolean => level.isAccessible || level.isComplete;

  return (
    <div className={cn('bg-white rounded-lg shadow-sm p-6', className)}>
      <h3 className="text-lg font-semibold mb-4">Planning Workflow Progress</h3>

      <div className="space-y-3">
        {progress.map((level, index) => {
          const isLast = index === progress.length - 1;
          const stepContent = (
            <>
              <div className="flex-shrink-0 mt-0.5">{getStepIcon(level)}</div>

              <div className="flex-1 min-w-0">
                <h4 className="font-medium text-gray-900">{level.title}</h4>
                <p className="text-sm text-gray-600">{level.description}</p>

                {level.requiredFields !== null && level.requiredFields !== undefined && level.requiredFields.length > 0 && (
                  <div className="mt-2">
                    <p className="text-xs text-gray-500 mb-1">Required:</p>
                    <div className="flex flex-wrap gap-1">
                      {level.requiredFields.map((field, _index) => (
                        <Badge key={field} className="text-xs" variant="outline">
                          {field}
                        </Badge>
                      ))}
                    </div>
                  </div>
                )}
              </div>

              <div className="flex-shrink-0">
                {level.isComplete ? (
                  <Badge className="bg-green-600" variant="default">
                    Complete
                  </Badge>
                ) : level.isAccessible ? (
                  <Badge variant="outline">Available</Badge>
                ) : (
                  <Badge variant="secondary">Locked</Badge>
                )}
              </div>
            </>
          );

          return (
            <div key={level.level} className="relative">
              {canNavigate(level) ? (
                <Link
                  className={cn(
                    'flex items-start gap-4 p-4 rounded-lg border-2 transition-all',
                    getStepStyles(level),
                    'cursor-pointer',
                  )}
                  to={ETFO_LEVEL_PATHS[level.level]}
                >
                  {stepContent}
                </Link>
              ) : (
                <div
                  className={cn(
                    'flex items-start gap-4 p-4 rounded-lg border-2 transition-all',
                    getStepStyles(level),
                  )}
                >
                  {stepContent}
                </div>
              )}

              {!isLast && (
                <div className="absolute left-7 top-full h-3 w-0.5 bg-gray-300 -translate-x-1/2" />
              )}
            </div>
          );
        })}
      </div>

      <div className="mt-6 p-4 bg-blue-50 rounded-lg">
        <p className="text-sm text-blue-800">
          <strong>Pro tip:</strong> Follow the ETFO planning workflow from top to bottom. Each level
          builds on the previous one, ensuring comprehensive planning coverage.
        </p>
      </div>
    </div>
  );
}

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import React, { useState } from 'react';

import { apiClient } from '../../api/core/client';
interface CurriculumExpectation {
  id: string;
  code: string;
  subject: string;
  grade: number;
  description: string;
  strand: string; // Updated for ETFO alignment
  substrand?: string;
  createdAt: string;
  updatedAt: string;
}
import { Button } from '../ui/Button';

interface UncoveredExpectation {
  expectation: CurriculumExpectation; // Updated for ETFO alignment
  suggestion: AISuggestedActivity | null;
}

interface AISuggestedActivity {
  id: number;
  expectationId: string; // Updated for ETFO alignment
  userId: number;
  title: string;
  descriptionFr: string;
  descriptionEn?: string;
  materials: string[];
  duration: number;
  theme?: string;
  createdAt: string;
  updatedAt: string;
}

interface UncoveredOutcomesPanelProps {
  startDate?: Date;
  endDate?: Date;
  theme?: string;
  onSelectSuggestion: (suggestion: AISuggestedActivity) => void;
}

export function UncoveredOutcomesPanel({
  startDate,
  endDate,
  theme,
  onSelectSuggestion,
}: UncoveredOutcomesPanelProps): React.ReactElement {
  const queryClient = useQueryClient();
  const [generatingFor, setGeneratingFor] = useState<string | null>(null);

  // Fetch uncovered outcomes
  const { data: uncoveredOutcomes, isLoading } = useQuery({
    queryKey: ['uncovered-outcomes', startDate, endDate, theme],
    queryFn: async () => {
      const params = new URLSearchParams();
      if (startDate !== null && startDate !== undefined) {
params.append('startDate', startDate.toISOString());
}
      if (endDate !== null && endDate !== undefined) {
params.append('endDate', endDate.toISOString());
}
      if (theme !== null && theme !== undefined && theme !== '') {
params.append('theme', theme);
}

      const response = await apiClient.get<UncoveredExpectation[]>(
        `/ai-suggestions/uncovered?${params.toString()}`,
      );
      return response.data;
    },
  });

  // Generate AI suggestion mutation
  const generateSuggestion = useMutation({
    mutationFn: async (outcomeId: string) => {
      setGeneratingFor(outcomeId);
      const response = await apiClient.post<AISuggestedActivity>('/ai-suggestions/generate', {
        outcomeId,
        theme,
      });
      return response.data;
    },
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: ['uncovered-outcomes'] });
      setGeneratingFor(null);
    },
    onError: () => {
      setGeneratingFor(null);
    },
  });

  if (isLoading) {
    return (
      <div className="flex items-center justify-center p-8" role="status">
        <div className="animate-spin rounded-full h-6 w-6 border-b-2 border-blue-600" />
      </div>
    );
  }

  if (uncoveredOutcomes === null || uncoveredOutcomes === undefined || uncoveredOutcomes.length === 0) {
    return (
      <div className="text-center p-8 bg-green-50 rounded-lg">
        <div className="text-4xl mx-auto mb-4">🎯</div>
        <h3 className="text-lg font-semibold text-green-900 mb-2">Tous les résultats couverts!</h3>
        <p className="text-green-700">
          Excellent! All curriculum outcomes have been addressed in your plans.
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between mb-4">
        <h3 className="text-lg font-semibold">Uncovered Outcomes</h3>
        <span className="text-sm text-gray-500">
          {uncoveredOutcomes.length} outcomes need attention
        </span>
      </div>

      <div className="space-y-3">
        {uncoveredOutcomes.map(({ expectation, suggestion }) => (
          <div
            key={expectation.id}
            className="border rounded-lg p-4 hover:shadow-md transition-shadow"
          >
            <div className="flex items-start justify-between">
              <div className="flex-1">
                <div className="flex items-center gap-2 mb-2">
                  <span className="text-sm font-medium text-blue-600 bg-blue-50 px-2 py-1 rounded">
                    {expectation.code}
                  </span>
                  <span className="text-sm text-gray-500">{expectation.subject}</span>
                </div>
                <p className="text-sm text-gray-700">{expectation.description}</p>

                {suggestion !== null && (
                  <div className="mt-3 p-3 bg-gray-50 rounded-md">
                    <div className="flex items-center justify-between mb-2">
                      <h4 className="font-medium text-sm">{suggestion.title}</h4>
                      <span className="text-xs text-gray-500">{suggestion.duration} min</span>
                    </div>
                    <p className="text-xs text-gray-600 mb-2">{suggestion.descriptionFr}</p>
                    <Button
                      className="mt-2"
                      size="sm"
                      variant="outline"
                      onClick={() => {
 onSelectSuggestion(suggestion); 
}}
                    >
                      <span className="mr-1">📅</span>
                      Use this activity
                    </Button>
                  </div>
                )}
              </div>

              <div className="ml-4">
                {suggestion === null && (
                  <Button
                    disabled={generatingFor === expectation.id}
                    size="sm"
                    onClick={() => {
 generateSuggestion.mutate(expectation.id); 
}}
                  >
                    {generatingFor === expectation.id ? (
                      <>
                        <span className="inline-block animate-spin mr-2">⏳</span>
                        Generating...
                      </>
                    ) : (
                      <>
                        <span className="mr-2">✨</span>
                        Suggest Activity
                      </>
                    )}
                  </Button>
                )}
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
