            </div>
            <div>
              <CardTitle className="text-lg">{config.title}</CardTitle>
              <CardDescription className="text-sm">
                {config.description}
              </CardDescription>
            </div>
          </div>
        </CardHeader>
        <CardContent className="pt-0">
          <div className="flex gap-2">
            <Button
              className="flex items-center gap-2"
              size="sm"
              variant="outline"
              onClick={() => {
 handlePreview(key); 
}}
            >
              <Eye className="h-4 w-4" />
              Preview
            </Button>
            <Button
              className="flex items-center gap-2"
              size="sm"
              variant="outline"
              onClick={() => {
 handlePrint(key); 
}}
            >
              <Printer className="h-4 w-4" />
              Print
            </Button>
            <Button
              className="flex items-center gap-2"
              size="sm"
              variant="outline"
              onClick={() => {
 handleDownload(key); 
}}
            >
              <Download className="h-4 w-4" />
              Download
            </Button>
          </div>
        </CardContent>
      </Card>
    );
  };

