import { Keyboard, Settings, RefreshCw, Check, X, Info } from 'lucide-react';
import React, { useState } from 'react';

import type {
  KeyboardShortcut} from '../../contexts/KeyboardShortcutsContext';
import {
  useKeyboardShortcuts,
  formatShortcut
} from '../../contexts/KeyboardShortcutsContext';
import { Alert, AlertDescription } from '../ui/alert';
import { Button } from '../ui/Button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '../ui/card';
import { Input } from '../ui/Input';
import { Label } from '../ui/Label';
import { Switch } from '../ui/Switch';

export const KeyboardShortcutsSettings: React.FC = (): React.ReactElement => {
  const { shortcuts, preferences, updatePreferences } = useKeyboardShortcuts();
  const [editingShortcut, setEditingShortcut] = useState<string | null>(null);
  const [captureKey, setCaptureKey] = useState<string>('');
  const [captureModifiers, setCaptureModifiers] = useState({
    ctrl: false,
    cmd: false,
    alt: false,
    shift: false,
  });

  // Group shortcuts by category
  const shortcutsByCategory = shortcuts
    .filter((s) => s.visible !== false)
    .reduce<Record<KeyboardShortcut['category'], KeyboardShortcut[]>>(
      (acc, shortcut) => {
        if (!acc[shortcut.category]) {
          acc[shortcut.category] = [];
        }
        acc[shortcut.category].push(shortcut);
        return acc;
      },
      {
        global: [],
        navigation: [],
        planning: [],
        editing: [],
        other: [],
      },
    );

  const categoryLabels: Record<KeyboardShortcut['category'], string> = {
    global: 'Global Shortcuts',
    navigation: 'Navigation',
    planning: 'Planning & Editing',
    editing: 'Text Editing',
    other: 'Other',
  };

  const handleKeyCapture = (e: React.KeyboardEvent, _shortcutId: string): void => {
    e.preventDefault();

    const {key} = e;
    const modifiers = {
      ctrl: e.ctrlKey,
      cmd: e.metaKey,
      alt: e.altKey,
      shift: e.shiftKey,
    };

    setCaptureKey(key);
    setCaptureModifiers(modifiers);
  };

  const saveCustomShortcut = (shortcutId: string): void => {
    const customShortcuts = {
      ...preferences.customShortcuts,
      [shortcutId]: {
        key: captureKey,
        ...captureModifiers,
      },
    };

    updatePreferences({ customShortcuts });
    setEditingShortcut(null);
    setCaptureKey('');
    setCaptureModifiers({ ctrl: false, cmd: false, alt: false, shift: false });
  };

  const resetShortcut = (shortcutId: string): void => {
    const customShortcuts = { ...preferences.customShortcuts };
    delete customShortcuts[shortcutId];
    updatePreferences({ customShortcuts });
  };

  const resetAllShortcuts = (): void => {
    if (
      window.confirm('Are you sure you want to reset all keyboard shortcuts to their defaults?')
    ) {
      updatePreferences({ customShortcuts: {} });
    }
  };

  return (
    <div className="space-y-6">
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Keyboard className="h-5 w-5" />
            Keyboard Shortcuts
          </CardTitle>
          <CardDescription>
            Customize keyboard shortcuts to improve your workflow efficiency
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-6">
          {/* Master Toggle */}
          <div className="flex items-center justify-between p-4 bg-gray-50 rounded-lg">
            <div>
              <Label className="text-base font-medium">Enable Keyboard Shortcuts</Label>
              <p className="text-sm text-gray-600 mt-1">
                Turn on keyboard shortcuts for faster navigation and actions
              </p>
            </div>
            <Switch
              checked={preferences.enabled}
              size="md"
              onChange={(enabled): void => {
 updatePreferences({ enabled }); 
}}
            />
          </div>

          {/* Shortcut Hints Toggle */}
          <div className="flex items-center justify-between p-4 bg-gray-50 rounded-lg">
            <div>
              <Label className="text-base font-medium">Show Shortcut Hints</Label>
              <p className="text-sm text-gray-600 mt-1">
                Display keyboard shortcut hints next to buttons and menu items
              </p>
            </div>
            <Switch
              checked={preferences.showHints}
              size="md"
              onChange={(showHints): void => {
 updatePreferences({ showHints }); 
}}
            />
          </div>

          {/* Quick Reference */}
          <Alert>
            <Info className="h-4 w-4" />
            <AlertDescription>
              Press{' '}
              <kbd className="px-1 py-0.5 text-xs bg-gray-100 border border-gray-300 rounded">
                ?
              </kbd>{' '}
              at any time to view all available keyboard shortcuts
            </AlertDescription>
          </Alert>

          {/* Shortcuts List */}
          <div className="space-y-6">
            {Object.entries(shortcutsByCategory).map(([category, categoryShortcuts]) => (
              <div key={category}>
                <h3 className="text-lg font-medium text-gray-900 mb-3">
                  {categoryLabels[category as KeyboardShortcut['category']]}
                </h3>
                <div className="space-y-2">
                  {(categoryShortcuts).map((shortcut, _index) => {
                    const customShortcut = preferences.customShortcuts[shortcut.id];
                    const isEditing = editingShortcut === shortcut.id;
                    const hasCustom = !!customShortcut;
                    const displayShortcut = customShortcut
                      ? { ...shortcut, ...customShortcut }
                      : shortcut;

                    return (
                      <div
                        key={shortcut.id}
                        className="flex items-center justify-between p-3 border rounded-lg hover:bg-gray-50"
                      >
                        <div className="flex-1">
                          <p className="font-medium text-sm">{shortcut.description}</p>
                          {hasCustom && (
                            <p className="text-xs text-gray-500 mt-1">
                              Default: {formatShortcut(shortcut)}
                            </p>
                          )}
                        </div>

                        <div className="flex items-center gap-2">
                          {isEditing ? (
                            <>
                              <Input
                                readOnly
                                className="w-32 text-center"
                                placeholder="Press keys..."
                                type="text"
                                value={
                                  captureKey
                                    ? formatShortcut({
                                        ...shortcut,
                                        key: captureKey,
                                        ...captureModifiers,
                                      })
                                    : ''
                                }
                                onKeyDown={(e): void => {
 handleKeyCapture(e, shortcut.id); 
}}
                              />
                              <Button
                                disabled={!captureKey}
                                size="sm"
                                variant="ghost"
                                onClick={(): void => {
 saveCustomShortcut(shortcut.id); 
}}
                              >
                                <Check className="h-4 w-4" />
                              </Button>
                              <Button
                                size="sm"
                                variant="ghost"
                                onClick={(): void => {
                                  setEditingShortcut(null);
                                  setCaptureKey('');
                                  setCaptureModifiers({
                                    ctrl: false,
                                    cmd: false,
                                    alt: false,
                                    shift: false,
                                  });
                                }}
                              >
                                <X className="h-4 w-4" />
                              </Button>
                            </>
                          ) : (
                            <>
                              <kbd className="px-2 py-1 text-xs font-semibold text-gray-800 bg-gray-100 border border-gray-300 rounded-lg">
                                {formatShortcut(displayShortcut)}
                              </kbd>
                              <Button
                                size="sm"
                                variant="ghost"
                                onClick={(): void => {
 setEditingShortcut(shortcut.id); 
}}
                              >
                                <Settings className="h-4 w-4" />
                              </Button>
                              {hasCustom && (
                                <Button
                                  size="sm"
                                  title="Reset to default"
                                  variant="ghost"
                                  onClick={(): void => {
 resetShortcut(shortcut.id); 
}}
                                >
                                  <RefreshCw className="h-4 w-4" />
                                </Button>
                              )}
                            </>
                          )}
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            ))}
          </div>

          {/* Reset All Button */}
          <div className="pt-4 border-t">
            <Button aria-label="Click button" onClick={resetAllShortcuts}>
              <RefreshCw className="h-4 w-4 mr-2" />
              Reset All to Defaults
            </Button>
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

