 setProcedures(e.target.value); 
}}
      />
      <textarea
        className="border p-1 w-full"
        maxLength={1000}
        placeholder="Allergies"
        value={allergies}
        onChange={(e): void => {
 setAllergies(e.target.value); 
}}
      />
      <button className="px-2 py-1 bg-blue-600 text-white" onClick={handleSave}>
        Save
      </button>
    </div>
  );
}

