              value={weekData.weekFocus.communicationGoals.join('\n')}
              onChange={(e) => {
 setWeekData({
                  ...weekData,
                  weekFocus: {
                    ...weekData.weekFocus,
                    communicationGoals: e.target.value.split('\n').filter((_s) => _s.trim()),
                  },
                }); 
}
              }
            />
          </div>
        </div>
      </Card>

      {/* Daily Plans */}
      <Card className="p-6">
        <div className="flex items-center gap-2 mb-4">
