      <div className="flex justify-end gap-3 pt-6 border-t">
        {onCancel && (
          <Button aria-label="Click button" onClick={onCancel}>
            Cancel
          </Button>
        )}
        <Button type="submit" variant="primary">
          Save Weekly Plan
        </Button>
      </div>
    </form>
  );
}

