import { useMutation, useQuery } from '@tanstack/react-query';
import { format } from 'date-fns';
import { Calendar, FileText } from 'lucide-react';
import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'sonner';

import { api } from '../../api';
import type { PlanTemplate } from '../../types/template';
import { Button } from '../ui/Button';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from '../ui/Dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '../ui/select';

interface TemplateApplyModalProps {
  template: PlanTemplate;
  isOpen: boolean;
  onClose: () => void;
}

export default function TemplateApplyModal({
  template,
  isOpen,
  onClose,
}: TemplateApplyModalProps): React.ReactElement {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    title: template.title,
    longRangePlanId: '',
    unitPlanId: '',
    startDate: format(new Date(), 'yyyy-MM-dd'),
  });

  interface LongRangePlan {
    id: string;
    title: string;
    subject: string;
    grade: string;
  }

  // Fetch long-range plans for unit templates
  const { data: longRangePlans = [] } = useQuery<LongRangePlan[]>({
    queryKey: ['long-range-plans'],
    queryFn: async () => {
      const response = await api.get<LongRangePlan[]>('/api/long-range-plans');
      return response.data;
    },
    enabled: template.type === 'UNIT_PLAN',
  });

  interface UnitPlan {
    id: string;
    title: string;
  }

  // Fetch unit plans for lesson templates
  const { data: unitPlans = [] } = useQuery<UnitPlan[]>({
    queryKey: ['unit-plans'],
    queryFn: async () => {
      const response = await api.get<UnitPlan[]>('/api/unit-plans');
      return response.data;
    },
    enabled: template.type === 'LESSON_PLAN',
  });

  interface ApplyTemplateResponse {
    id: string;
  }

  // Apply template mutation
  const applyTemplateMutation = useMutation<ApplyTemplateResponse, Error, void>({
    mutationFn: async () => {
      const endpoint = `/api/templates/${template.id}/apply`;
      const payload = {
        title: formData.title,
        ...(template.type === 'UNIT_PLAN' && {
          longRangePlanId: formData.longRangePlanId,
          startDate: formData.startDate,
        }),
        ...(template.type === 'LESSON_PLAN' && {
          unitPlanId: formData.unitPlanId,
          date: formData.startDate,
        }),
      };

      const response = await api.post<ApplyTemplateResponse>(endpoint, payload);
      return response.data;
    },
    onSuccess: (data) => {
      toast.success(`${template.type === 'UNIT_PLAN' ? 'Unit' : 'Lesson'} created from template`);

      // Navigate to the created plan
      if (template.type === 'UNIT_PLAN') {
        navigate(`/planner/units/${data.id}`);
      } else {
        navigate(`/planner/lessons/${data.id}`);
      }

      onClose();
    },
    onError: () => {
      toast.error('Failed to apply template');
    },
  });

  const handleSubmit = (e: React.FormEvent): void => {
    e.preventDefault();

    // Validate required fields
    if (template.type === 'UNIT_PLAN' && (formData.longRangePlanId === null || formData.longRangePlanId === undefined || formData.longRangePlanId === '')) {
      toast.error('Please select a long-range plan');
      return;
    }

    if (template.type === 'LESSON_PLAN' && (formData.unitPlanId === null || formData.unitPlanId === undefined || formData.unitPlanId === '')) {
      toast.error('Please select a unit plan');
      return;
    }

    applyTemplateMutation.mutate();
  };

  return (
    <Dialog open={isOpen} onOpenChange={() => {
 onClose(); 
}}>
      <DialogContent className="sm:max-w-[500px]">
        <DialogHeader>
          <DialogTitle>Apply Template</DialogTitle>
          <DialogDescription>
            Customize how you want to apply the &quot;{template.title}&quot; template.
          </DialogDescription>
        </DialogHeader>

        <form className="space-y-4 mt-4" onSubmit={handleSubmit}>
          {/* Title */}
          <div>
            <label className="block text-sm font-medium mb-1" htmlFor="title">
              Title
            </label>
            <input
              required
              className="w-full px-3 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
              id="title"
              type="text"
              value={formData.title}
              onChange={(e) => {
 setFormData({ ...formData, title: e.target.value }); 
}}
            />
          </div>

          {/* Long-Range Plan Selection (for unit templates) */}
          {template.type === 'UNIT_PLAN' && (
            <div>
              <label className="block text-sm font-medium mb-1" htmlFor="longRangePlan">
                Long-Range Plan
              </label>
              <Select
                value={formData.longRangePlanId}
                onValueChange={(value) => {
 setFormData({ ...formData, longRangePlanId: value }); 
}}
              >
                <SelectTrigger id="longRangePlan">
                  <SelectValue placeholder="Select a long-range plan" />
                </SelectTrigger>
                <SelectContent>
                  {longRangePlans.map((plan, _index) => (
                    <SelectItem key={plan.id} value={plan.id}>
                      {plan.title} - {plan.subject} (Grade {plan.grade})
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          )}

          {/* Unit Plan Selection (for lesson templates) */}
          {template.type === 'LESSON_PLAN' && (
            <div>
              <label className="block text-sm font-medium mb-1" htmlFor="unitPlan">
                Unit Plan
              </label>
              <Select
                value={formData.unitPlanId}
                onValueChange={(value) => {
 setFormData({ ...formData, unitPlanId: value }); 
}}
              >
                <SelectTrigger id="unitPlan">
                  <SelectValue placeholder="Select a unit plan" />
                </SelectTrigger>
                <SelectContent>
                  {unitPlans.map((unit, _index) => (
                    <SelectItem key={unit.id} value={unit.id}>
                      {unit.title}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          )}

          {/* Start Date */}
          <div>
            <label className="block text-sm font-medium mb-1" htmlFor="startDate">
              <Calendar className="inline h-4 w-4 mr-1" />
              {template.type === 'UNIT_PLAN' ? 'Start Date' : 'Date'}
            </label>
            <input
              required
              className="w-full px-3 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
              id="startDate"
              type="date"
              value={formData.startDate}
              onChange={(e) => {
 setFormData({ ...formData, startDate: e.target.value }); 
}}
            />
          </div>

          {/* Template Info */}
          <div className="bg-gray-50 rounded-lg p-4 space-y-2">
            <div className="flex items-center gap-2 text-sm text-gray-600">
              {template.type === 'UNIT_PLAN' ? (
                <FileText className="h-4 w-4" />
              ) : (
                <Calendar className="h-4 w-4" />
              )}
              <span>{template.type === 'UNIT_PLAN' ? 'Unit Plan' : 'Lesson Plan'} Template</span>
            </div>
            {template.estimatedWeeks !== null && template.estimatedWeeks !== undefined && template.estimatedWeeks > 0 && (
              <p className="text-sm text-gray-600">
                Duration: {template.estimatedWeeks} weeks
              </p>
            )}
            {template.estimatedMinutes !== null && template.estimatedMinutes !== undefined && template.estimatedMinutes > 0 && (
              <p className="text-sm text-gray-600">
                Duration: {template.estimatedMinutes} minutes
              </p>
            )}
            {template.tags.length > 0 && (
              <div className="flex flex-wrap gap-1 mt-2">
                {template.tags.map((tag, _index) => (
                  <span
                    key={tag}
                    className="px-2 py-1 bg-white text-gray-600 text-xs rounded-full"
                  >
                    {tag}
                  </span>
                ))}
              </div>
            )}
          </div>

          {/* Actions */}
          <div className="flex justify-end gap-2 pt-4">
            <Button aria-label="Click button" onClick={onClose}>
              Cancel
            </Button>
            <Button
              disabled={applyTemplateMutation.isPending}
              type="submit"
            >
              {applyTemplateMutation.isPending ? 'Applying...' : 'Apply Template'}
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import { format } from 'date-fns';
import { Star, Calendar, Clock, Users, FileText, Copy } from 'lucide-react';
import React from 'react';

import type { PlanTemplate } from '../../types/template';
import { Button } from '../ui/Button';

interface TemplateCardProps {
  template: PlanTemplate;
  onPreview: (template: PlanTemplate) => void;
  onApply: (template: PlanTemplate) => void;
  onDuplicate?: (template: PlanTemplate) => void;
}

export default function TemplateCard({
  template,
  onPreview,
  onApply,
  onDuplicate,
}: TemplateCardProps): React.ReactElement {
  const getTypeIcon = (): React.ReactElement => template.type === 'UNIT_PLAN' ? (
      <FileText className="h-5 w-5 text-blue-600" />
    ) : (
      <Calendar className="h-5 w-5 text-green-600" />
    );

  const getDuration = (): string => {
    if (template.type === 'UNIT_PLAN' && template.estimatedWeeks !== null && template.estimatedWeeks !== undefined && template.estimatedWeeks > 0) {
      return `${template.estimatedWeeks} week${template.estimatedWeeks > 1 ? 's' : ''}`;
    } else if (template.type === 'LESSON_PLAN' && template.estimatedMinutes !== null && template.estimatedMinutes !== undefined && template.estimatedMinutes > 0) {
      return `${template.estimatedMinutes} minutes`;
    }
    return 'Duration not specified';
  };

  const getGradeRange = (): string => {
    if (template.gradeMin !== null && template.gradeMin !== undefined && template.gradeMax !== undefined) {
      return template.gradeMin === template.gradeMax
        ? `Grade ${template.gradeMin}`
        : `Grades ${template.gradeMin}-${template.gradeMax}`;
    }
    return 'All grades';
  };

  return (
    <div className="bg-white rounded-lg shadow-sm border hover:shadow-md transition-shadow p-6">
      {/* Header */}
      <div className="flex items-start justify-between mb-4">
        <div className="flex items-start gap-3">
          {getTypeIcon()}
          <div>
            <h3 className="font-semibold text-lg">{template.title}</h3>
            {template.subject !== null && template.subject !== undefined && template.subject !== '' && (
              <p className="text-sm text-gray-600 capitalize">{template.subject}</p>
            )}
          </div>
        </div>
        {template.isSystem && (
          <span className="px-2 py-1 bg-blue-100 text-blue-700 text-xs rounded-full">
            System
          </span>
        )}
      </div>

      {/* Description */}
      {template.description !== null && template.description !== undefined && template.description !== '' && (
        <p className="text-gray-700 text-sm mb-4 line-clamp-2">
          {template.description}
        </p>
      )}

      {/* Metadata */}
      <div className="grid grid-cols-2 gap-3 mb-4 text-sm">
        <div className="flex items-center gap-2 text-gray-600">
          <Users className="h-4 w-4" />
          <span>{getGradeRange()}</span>
        </div>
        <div className="flex items-center gap-2 text-gray-600">
          <Clock className="h-4 w-4" />
          <span>{getDuration()}</span>
        </div>
      </div>

      {/* Stats */}
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-4 text-sm">
          {template.averageRating !== null && template.averageRating !== undefined && template.averageRating > 0 && (
            <div className="flex items-center gap-1">
              <Star className="h-4 w-4 text-yellow-500 fill-current" />
              <span className="font-medium">{template.averageRating.toFixed(1)}</span>
              {template._count?.ratings !== null && template._count?.ratings !== undefined && template._count.ratings > 0 && (
                <span className="text-gray-500">({template._count.ratings})</span>
              )}
            </div>
          )}
          <div className="text-gray-500">
            Used {template.usageCount} time{template.usageCount !== 1 ? 's' : ''}
          </div>
        </div>
      </div>

      {/* Tags */}
      {template.tags.length > 0 && (
        <div className="flex flex-wrap gap-1 mb-4">
          {template.tags.slice(0, 3).map((tag, _index) => (
            <span
              key={tag}
              className="px-2 py-1 bg-gray-100 text-gray-600 text-xs rounded-full"
            >
              {tag}
            </span>
          ))}
          {template.tags.length > 3 && (
            <span className="px-2 py-1 text-gray-500 text-xs">
              +{template.tags.length - 3} more
            </span>
          )}
        </div>
      )}

      {/* Actions */}
      <div className="flex gap-2">
        <Button
          className="flex-1"
          size="sm"
          variant="outline"
          onClick={() => {
 onPreview(template); 
}}
        >
          Preview
        </Button>
        <Button
          className="flex-1"
          size="sm"
          onClick={() => {
 onApply(template); 
}}
        >
          Use Template
        </Button>
        {onDuplicate !== undefined && (
          <Button
            size="sm"
            title="Duplicate template"
            variant="ghost"
            onClick={() => {
 onDuplicate(template); 
}}
          >
            <Copy className="h-4 w-4" />
          </Button>
        )}
      </div>

      {/* Created info */}
      <div className="mt-4 pt-4 border-t text-xs text-gray-500">
        {template.createdByUser !== null && template.createdByUser !== undefined ? (
          <span>Created by {template.createdByUser.name}</span>
        ) : (
          <span>System template</span>
        )}
        {template.lastUsedAt !== null && template.lastUsedAt !== undefined && template.lastUsedAt !== '' && (
          <span className="ml-2">
            • Last used {format(new Date(template.lastUsedAt), 'MMM d, yyyy')}
          </span>
        )}
      </div>
    </div>
  );
}

import { Filter, X } from 'lucide-react';

import type { TemplateCategory, TemplateSearchOptions } from '../../types/template';
import { TEMPLATE_CATEGORIES, TEMPLATE_TYPES } from '../../types/template';
import { Button } from '../ui/Button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '../ui/select';

interface TemplateFiltersProps {
  filters: TemplateSearchOptions;
  onFiltersChange: (filters: TemplateSearchOptions) => void;
  availableSubjects: string[];
  availableGrades: number[];
}

const SORT_OPTIONS = [
  { value: 'title', label: 'Title' },
  { value: 'usageCount', label: 'Most Used' },
  { value: 'averageRating', label: 'Highest Rated' },
  { value: 'createdAt', label: 'Newest First' },
  { value: 'lastUsedAt', label: 'Recently Used' },
];

export default function TemplateFilters({
  filters,
  onFiltersChange,
  availableSubjects,
  availableGrades,
}: TemplateFiltersProps): React.ReactElement {
  const updateFilter = (key: keyof TemplateSearchOptions, value: unknown): void => {
    onFiltersChange({ ...filters, [key]: value });
  };

  const clearFilters = (): void => {
    onFiltersChange({
      sortBy: 'usageCount',
      sortOrder: 'desc',
    });
  };

  const hasActiveFilters =
    filters.type !== undefined ||
    filters.category !== undefined ||
    (filters.subject !== undefined && filters.subject !== '') ||
    filters.gradeMin !== undefined ||
    filters.gradeMax !== undefined ||
    (filters.search !== undefined && filters.search !== '') ||
    (filters.tags !== undefined && filters.tags.length > 0);

  return (
    <div className="bg-gray-50 rounded-lg p-4 space-y-4">
      <div className="flex items-center justify-between">
        <h3 className="font-semibold text-gray-700 flex items-center gap-2">
          <Filter className="h-4 w-4" />
          Filter Templates
        </h3>
        {hasActiveFilters && (
          <Button
            className="text-gray-500 hover:text-gray-700"
            size="sm"
            variant="ghost"
            onClick={clearFilters}
          >
            <X className="h-4 w-4 mr-1" />
            Clear All
          </Button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        {/* Search */}
        <div className="md:col-span-2 lg:col-span-4">
          <input
            className="w-full px-3 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
            placeholder="Search templates..."
            type="text"
            value={filters.search ?? ''}
            onChange={(e): void => {
 updateFilter('search', e.target.value); 
}}
          />
        </div>

        {/* Template Type */}
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Type</label>
          <Select
            value={filters.type ?? 'all'}
            onValueChange={(value): void => {
 updateFilter('type', value === 'all' ? undefined : value); 
}}
          >
            <SelectTrigger>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Types</SelectItem>
              {Object.entries(TEMPLATE_TYPES).map(([key, { label }]) => (
                <SelectItem key={key} value={key}>
                  {label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        {/* Category */}
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Category</label>
          <Select
            value={filters.category ?? 'all'}
            onValueChange={(value): void => {
 updateFilter('category', value === 'all' ? undefined : (value as TemplateCategory)); 
}
            }
          >
            <SelectTrigger>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Categories</SelectItem>
              {Object.entries(TEMPLATE_CATEGORIES).map(([key, { label }]) => (
                <SelectItem key={key} value={key}>
                  {label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        {/* Subject */}
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Subject</label>
          <Select
            value={filters.subject ?? 'all'}
            onValueChange={(value): void => {
 updateFilter('subject', value === 'all' ? undefined : value); 
}}
          >
            <SelectTrigger>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Subjects</SelectItem>
              {availableSubjects.map((subject, _index) => (
                <SelectItem key={subject} value={subject}>
                  {subject}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        {/* Grade Range */}
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Grade Level</label>
          <div className="flex gap-2 items-center">
            <Select
              value={filters.gradeMin !== undefined ? filters.gradeMin.toString() : 'all'}
              onValueChange={(value): void => {
 updateFilter('gradeMin', value === 'all' ? undefined : parseInt(value)); 
}
              }
            >
              <SelectTrigger className="flex-1">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">Any</SelectItem>
                {availableGrades.map((grade, _index) => (
                  <SelectItem key={grade} value={grade.toString()}>
                    {grade}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            <span className="text-gray-500">to</span>
            <Select
              value={filters.gradeMax !== undefined ? filters.gradeMax.toString() : 'all'}
              onValueChange={(value): void => {
 updateFilter('gradeMax', value === 'all' ? undefined : parseInt(value)); 
}
              }
            >
              <SelectTrigger className="flex-1">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">Any</SelectItem>
                {availableGrades.map((grade, _index) => (
                  <SelectItem key={grade} value={grade.toString()}>
                    {grade}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        </div>
      </div>

      {/* Sort Options */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 pt-2 border-t">
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Sort By</label>
          <Select
            value={filters.sortBy ?? 'usageCount'}
            onValueChange={(value): void => {
 updateFilter(
                'sortBy',
                value as 'title' | 'usageCount' | 'averageRating' | 'createdAt' | 'lastUsedAt',
              ); 
}
            }
          >
            <SelectTrigger>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {SORT_OPTIONS.map((option, _index) => (
                <SelectItem key={option.value} value={option.value}>
                  {option.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Order</label>
          <Select
            value={filters.sortOrder ?? 'desc'}
            onValueChange={(value): void => {
 updateFilter('sortOrder', value as 'asc' | 'desc'); 
}}
          >
            <SelectTrigger>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="asc">Ascending</SelectItem>
              <SelectItem value="desc">Descending</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </div>

      {/* Filter Options */}
      <div className="flex flex-wrap gap-2">
        <label className="flex items-center space-x-2 text-sm">
          <input
            checked={Boolean(filters.isSystem)}
            className="rounded border-gray-300"
            type="checkbox"
            onChange={(e): void => {
 updateFilter('isSystem', e.target.checked ? true : undefined); 
}}
          />
          <span>System Templates Only</span>
        </label>
        <label className="flex items-center space-x-2 text-sm">
          <input
            checked={Boolean(filters.isPublic)}
            className="rounded border-gray-300"
            type="checkbox"
            onChange={(e): void => {
 updateFilter('isPublic', e.target.checked ? true : undefined); 
}}
          />
          <span>Public Templates Only</span>
        </label>
      </div>
    </div>
  );
}

import { X, FileText, Calendar, Clock, Users, Tag, ChevronDown, ChevronRight } from 'lucide-react';
import React, { useState } from 'react';

import type { PlanTemplate, UnitPlanContent, LessonPlanContent } from '../../types/template';
import { Button } from '../ui/Button';

interface TemplatePreviewModalProps {
  template: PlanTemplate;
  onClose: () => void;
  onApply: (template: PlanTemplate) => void;
}

export default function TemplatePreviewModal({
  template,
  onClose,
  onApply,
}: TemplatePreviewModalProps): React.ReactElement {
  const [expandedSections, setExpandedSections] = useState<Set<string>>(new Set(['overview']));

  const toggleSection = (section: string): void => {
    setExpandedSections(prev => {
      const newSet = new Set(prev);
      if (newSet.has(section)) {
        newSet.delete(section);
      } else {
        newSet.add(section);
      }
      return newSet;
    });
  };

  const renderUnitPlanContent = (content: UnitPlanContent): React.ReactElement => {
    const sections = [
      { key: 'overview', title: 'Overview', content: content.overview },
      { key: 'bigIdeas', title: 'Big Ideas', content: content.bigIdeas },
      { key: 'learningGoals', title: 'Learning Goals', content: content.learningGoals, isList: true },
      { key: 'essentialQuestions', title: 'Essential Questions', content: content.essentialQuestions, isList: true },
      { key: 'assessments', title: 'Assessments', content: content.assessments, isAssessments: true },
      { key: 'successCriteria', title: 'Success Criteria', content: content.successCriteria, isList: true },
      { key: 'keyVocabulary', title: 'Key Vocabulary', content: content.keyVocabulary, isList: true },
      { key: 'differentiationStrategies', title: 'Differentiation Strategies', content: content.differentiationStrategies, isDiff: true },
      { key: 'culminatingTask', title: 'Culminating Task', content: content.culminatingTask },
    ];

    return (
      <div className="space-y-4">
        {sections.map(({ key, title, content, isList, isAssessments, isDiff }) => {
          if (!content || (Array.isArray(content) && content.length === 0)) {
return null;
}

          const isExpanded = expandedSections.has(key);

          return (
            <div key={key} className="border rounded-lg">
              <button
                className="w-full px-4 py-3 flex items-center justify-between hover:bg-gray-50 transition-colors"
                onClick={(): void => {
 toggleSection(key); 
}}
              >
                <h4 className="font-medium text-left">{title}</h4>
                {isExpanded ? (
                  <ChevronDown className="h-4 w-4 text-gray-500" />
                ) : (
                  <ChevronRight className="h-4 w-4 text-gray-500" />
                )}
              </button>
              {isExpanded && (
                <div className="px-4 pb-3">
                  {isList === true && Array.isArray(content) ? (
                    <ul className="list-disc list-inside space-y-1">
                      {content.map((item, _index) => (
                        <li key={_index} className="text-gray-700">{item}</li>
                      ))}
                    </ul>
                  ) : isAssessments === true && Array.isArray(content) ? (
                    <div className="space-y-2">
                      {content.map((assessment, _index) => (
                        <div key={_index} className="bg-gray-50 p-3 rounded">
                          <div className="font-medium">{assessment.type}</div>
                          <div className="text-gray-700">{assessment.description}</div>
                          {assessment.timing && (
                            <div className="text-sm text-gray-500 mt-1">Timing: {assessment.timing}</div>
                          )}
                        </div>
                      ))}
                    </div>
                  ) : isDiff === true && typeof content === 'object' ? (
                    <div className="space-y-2">
                      {Object.entries(content).map(([key, strategies]) => (
                        <div key={key}>
                          <div className="font-medium text-sm capitalize">
                            {key.replace(/([A-Z])/g, ' $1').trim()}:
                          </div>
                          <ul className="list-disc list-inside ml-4">
                            {(strategies).map((strategy, _index) => (
                              <li key={_index} className="text-gray-700 text-sm">{strategy}</li>
                            ))}
                          </ul>
                        </div>
                      ))}
                    </div>
                  ) : (
                    <p className="text-gray-700">{typeof content === 'string' ? content : JSON.stringify(content)}</p>
                  )}
                </div>
              )}
            </div>
          );
        })}
      </div>
    );
  };

  const renderLessonPlanContent = (content: LessonPlanContent): React.ReactElement => {
    const sections = [
      { key: 'objectives', title: 'Learning Objectives', content: content.objectives, isList: true },
      { key: 'materials', title: 'Materials', content: content.materials, isList: true },
      { key: 'mindsOn', title: 'Minds On', content: content.mindsOn },
      { key: 'action', title: 'Action', content: content.action },
      { key: 'consolidation', title: 'Consolidation', content: content.consolidation },
      { key: 'accommodations', title: 'Accommodations', content: content.accommodations, isList: true },
      { key: 'modifications', title: 'Modifications', content: content.modifications, isList: true },
      { key: 'extensions', title: 'Extensions', content: content.extensions, isList: true },
      { key: 'assessment', title: 'Assessment', content: content.assessmentNotes, assessmentType: content.assessmentType },
    ];

    return (
      <div className="space-y-4">
        {sections.map(({ key, title, content, isList, assessmentType }) => {
          if (!content || (Array.isArray(content) && content.length === 0)) {
return null;
}

          const isExpanded = expandedSections.has(key);

          return (
            <div key={key} className="border rounded-lg">
              <button
                className="w-full px-4 py-3 flex items-center justify-between hover:bg-gray-50 transition-colors"
                onClick={(): void => {
 toggleSection(key); 
}}
              >
                <h4 className="font-medium text-left">{title}</h4>
                {isExpanded ? (
                  <ChevronDown className="h-4 w-4 text-gray-500" />
                ) : (
                  <ChevronRight className="h-4 w-4 text-gray-500" />
                )}
              </button>
              {isExpanded && (
                <div className="px-4 pb-3">
                  {isList === true && Array.isArray(content) ? (
                    <ul className="list-disc list-inside space-y-1">
                      {content.map((item, _index) => (
                        <li key={_index} className="text-gray-700">{item}</li>
                      ))}
                    </ul>
                  ) : key === 'assessment' ? (
                    <div>
                      {assessmentType && (
                        <div className="mb-2">
                          <span className="font-medium">Type:</span>{' '}
                          <span className="capitalize">{assessmentType}</span>
                        </div>
                      )}
                      <p className="text-gray-700">{typeof content === 'string' ? content : JSON.stringify(content)}</p>
                    </div>
                  ) : (
                    <p className="text-gray-700">{typeof content === 'string' ? content : JSON.stringify(content)}</p>
                  )}
                </div>
              )}
            </div>
          );
        })}
      </div>
    );
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-lg shadow-xl max-w-4xl w-full max-h-[90vh] overflow-hidden flex flex-col">
        {/* Header */}
        <div className="px-6 py-4 border-b flex items-center justify-between">
          <div className="flex items-center gap-3">
            {template.type === 'UNIT_PLAN' ? (
              <FileText className="h-6 w-6 text-blue-600" />
            ) : (
              <Calendar className="h-6 w-6 text-green-600" />
            )}
            <div>
              <h2 className="text-xl font-semibold">{template.title}</h2>
              <p className="text-sm text-gray-600">
                {template.type === 'UNIT_PLAN' ? 'Unit Plan Template' : 'Lesson Plan Template'}
              </p>
            </div>
          </div>
          <button
            className="text-gray-400 hover:text-gray-600 transition-colors"
            onClick={onClose}
          >
            <X className="h-6 w-6" />
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-6">
          {/* Metadata */}
          <div className="mb-6 grid grid-cols-2 md:grid-cols-4 gap-4">
            {template.subject && (
              <div className="flex items-center gap-2 text-sm">
                <Tag className="h-4 w-4 text-gray-400" />
                <span className="capitalize">{template.subject}</span>
              </div>
            )}
            <div className="flex items-center gap-2 text-sm">
              <Users className="h-4 w-4 text-gray-400" />
              <span>
                {template.gradeMin !== undefined && template.gradeMax !== undefined
                  ? template.gradeMin === template.gradeMax
                    ? `Grade ${template.gradeMin}`
                    : `Grades ${template.gradeMin}-${template.gradeMax}`
                  : 'All grades'}
              </span>
            </div>
            <div className="flex items-center gap-2 text-sm">
              <Clock className="h-4 w-4 text-gray-400" />
              <span>
                {template.type === 'UNIT_PLAN' && template.estimatedWeeks && template.estimatedWeeks > 0
                  ? `${template.estimatedWeeks} weeks`
                  : template.type === 'LESSON_PLAN' && template.estimatedMinutes && template.estimatedMinutes > 0
                  ? `${template.estimatedMinutes} minutes`
                  : 'Duration varies'}
              </span>
            </div>
          </div>

          {/* Description */}
          {template.description && (
            <div className="mb-6">
              <h3 className="font-medium mb-2">Description</h3>
              <p className="text-gray-700">{template.description}</p>
            </div>
          )}

          {/* Tags */}
          {template.tags.length > 0 && (
            <div className="mb-6">
              <h3 className="font-medium mb-2">Tags</h3>
              <div className="flex flex-wrap gap-2">
                {template.tags.map((tag, _index) => (
                  <span
                    key={tag}
                    className="px-3 py-1 bg-gray-100 text-gray-700 text-sm rounded-full"
                  >
                    {tag}
                  </span>
                ))}
              </div>
            </div>
          )}

          {/* Template Content */}
          <div>
            <h3 className="font-medium mb-3">Template Content</h3>
            {template.type === 'UNIT_PLAN'
              ? renderUnitPlanContent(template.content as UnitPlanContent)
              : renderLessonPlanContent(template.content as LessonPlanContent)}
          </div>

          {/* Structure */}
          {template.type === 'UNIT_PLAN' && template.unitStructure && (
            <div className="mt-6">
              <h3 className="font-medium mb-3">Unit Structure</h3>
              {template.unitStructure.phases && template.unitStructure.phases.length > 0 && (
                <div className="space-y-3">
                  {template.unitStructure.phases.map((phase, _index) => (
                    <div key={_index} className="bg-gray-50 p-4 rounded-lg">
                      <div className="font-medium">{phase.name}</div>
                      {phase.description && (
                        <p className="text-gray-700 text-sm mt-1">{phase.description}</p>
                      )}
                      {phase.estimatedDays && phase.estimatedDays > 0 && (
                        <p className="text-gray-500 text-sm mt-1">
                          Estimated: {phase.estimatedDays} days
                        </p>
                      )}
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="px-6 py-4 border-t flex justify-between items-center">
          <div className="text-sm text-gray-500">
            {template.createdByUser ? (
              <span>Created by {template.createdByUser.name}</span>
            ) : (
              <span>System template</span>
            )}
            {template.usageCount > 0 && (
              <span className="ml-2">• Used {template.usageCount} times</span>
            )}
          </div>
          <div className="flex gap-2">
            <Button aria-label="Click button" onClick={onClose}>
              Close
            </Button>
            <Button aria-label="Click button" onClick={() => {
 onApply(template); 
}}>
              Use This Template
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
}

import { formatDistanceToNow } from 'date-fns';
import { Check, Clock, Save, AlertCircle, WifiOff, Cloud, CloudOff } from 'lucide-react';
import React, { useState, useEffect } from 'react';

import { isOnline } from '../../utils/serviceWorkerRegistration';

import { Badge } from './Badge';
import { Button } from './Button';
import { Tooltip } from './Tooltip';

interface AutoSaveIndicatorProps {
  lastSaved: Date | null;
  isSaving: boolean;
  hasUnsavedChanges: boolean;
  onManualSave?: () => void;
  className?: string;
  isOnlineProp?: boolean;
  syncStatus?: 'idle' | 'syncing' | 'error';
  syncError?: string | null;
  pendingChanges?: number;
}

export function AutoSaveIndicator({
  lastSaved,
  isSaving,
  hasUnsavedChanges,
  onManualSave,
  className = '',
  isOnlineProp,
  syncStatus = 'idle',
  syncError = null,
  pendingChanges = 0,
}: AutoSaveIndicatorProps): React.ReactElement {
  const [isOnlineState, setIsOnlineState] = useState(isOnlineProp ?? isOnline());

  useEffect((): (() => void) => {
    const handleOnline = (): void => {
 setIsOnlineState(true); 
};
    const handleOffline = (): void => {
 setIsOnlineState(false); 
};

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []) // eslint-disable-line react-hooks/exhaustive-deps

  const getStatus = (): { icon: React.ReactElement; text: string; variant: 'outline' | 'secondary' | 'destructive'; tooltip: string } => {
    // Offline status takes priority
    if (!isOnlineState) {
      return {
        icon: <WifiOff className="w-3 h-3" />,
        text: pendingChanges > 0 ? `Offline (${pendingChanges} pending)` : 'Offline mode',
        variant: 'outline' as const,
        tooltip: 'You are working offline. Changes will sync when you reconnect.',
      };
    }

    // Syncing status
    if (syncStatus === 'syncing') {
      return {
        icon: <Cloud className="w-3 h-3 animate-pulse" />,
        text: 'Syncing...',
        variant: 'secondary' as const,
        tooltip: 'Syncing your changes with the server.',
      };
    }

    // Sync error
    if (syncStatus === 'error' && syncError !== null && syncError !== undefined && syncError !== '') {
      return {
        icon: <CloudOff className="w-3 h-3" />,
        text: 'Sync failed',
        variant: 'destructive' as const,
        tooltip: `Sync error: ${syncError}. Will retry automatically.`,
      };
    }

    // Regular save states
    if (isSaving) {
      return {
        icon: <Clock className="w-3 h-3 animate-spin" />,
        text: 'Saving...',
        variant: 'secondary' as const,
        tooltip: 'Saving your changes...',
      };
    }

    if (hasUnsavedChanges) {
      return {
        icon: <AlertCircle className="w-3 h-3" />,
        text: 'Unsaved changes',
        variant: 'destructive' as const,
        tooltip: 'You have unsaved changes. They will be saved automatically.',
      };
    }

    if (lastSaved !== null) {
      return {
        icon: <Check className="w-3 h-3" />,
        text: `Saved ${formatDistanceToNow(lastSaved)} ago`,
        variant: 'secondary' as const,
        tooltip: `Last saved at ${lastSaved.toLocaleTimeString()}`,
      };
    }

    return {
      icon: <Save className="w-3 h-3" />,
      text: 'Not saved',
      variant: 'outline' as const,
      tooltip: 'No changes to save.',
    };
  };

  const status = getStatus();

  return (
    <div className={`flex items-center gap-2 ${className}`}>
      <Tooltip content={status.tooltip}>
        <Badge 
          className={`flex items-center gap-1 transition-all duration-200 ${
            hasUnsavedChanges && isOnlineState ? 'animate-pulse' : ''
          } ${!isOnlineState ? 'opacity-90' : ''}`} 
          variant={status.variant}
        >
          {status.icon}
          <span className="text-xs font-medium">{status.text}</span>
        </Badge>
      </Tooltip>

      {/* Connection status indicator */}
      {!isOnlineState && (
        <Badge className="flex items-center gap-1 bg-yellow-50 border-yellow-200" variant="outline">
          <WifiOff className="w-3 h-3 text-yellow-600" />
          <span className="text-xs font-medium text-yellow-700">Offline</span>
        </Badge>
      )}

      {/* Manual save button - only show when online */}
      {hasUnsavedChanges && onManualSave && isOnlineState && (
        <Button
          className="h-6 px-2 text-xs bg-orange-50 border-orange-200 text-orange-700 hover:bg-orange-100"
          disabled={isSaving || syncStatus === 'syncing'}
          size="sm"
          variant="outline"
          onClick={onManualSave}
        >
          <Save className="w-3 h-3 mr-1" />
          Save now
        </Button>
      )}

      {/* Progress indicator for auto-save countdown */}
      {hasUnsavedChanges && !isSaving && isOnlineState && (
        <div className="w-16 h-1 bg-gray-200 rounded-full overflow-hidden">
          <div 
            className="h-full bg-blue-500 transition-all duration-1000 ease-linear"
            style={{ 
              width: '100%',
              animation: 'autoSaveCountdown 30s linear infinite'
            }}
          />
        </div>
      )}

      {/* Pending changes indicator for offline mode */}
      {!isOnlineState && pendingChanges > 0 && (
        <Tooltip content={`${pendingChanges} changes will sync when you're back online`}>
          <Badge className="h-5 px-2 text-xs" variant="secondary">
            {pendingChanges}
          </Badge>
        </Tooltip>
      )}
    </div>
  );
}

// CSS for auto-save countdown animation
